{"command":"mkdir -p /workspace/src && cat > /workspace/src/symbol.rs <<'EOF'
//! String interning and keyword table.

use std::collections::HashMap;
use std::fmt;
use std::sync::Mutex;
use std::sync::OnceLock;

#[derive(Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct Symbol(pub u32);

struct Interner {
    map: HashMap<&'static str, Symbol>,
    strings: Vec<&'static str>,
}

static INTERNER: OnceLock<Mutex<Interner>> = OnceLock::new();

fn interner() -> &'static Mutex<Interner> {
    INTERNER.get_or_init(|| {
        let mut i = Interner { map: HashMap::new(), strings: Vec::new() };
        for &kw in PREDEFINED {
            let leaked: &'static str = Box::leak(kw.to_string().into_boxed_str());
            let sym = Symbol(i.strings.len() as u32);
            i.map.insert(leaked, sym);
            i.strings.push(leaked);
        }
        Mutex::new(i)
    })
}

impl Symbol {
    pub fn intern(s: &str) -> Symbol {
        let mut i = interner().lock().unwrap();
        if let Some(&sym) = i.map.get(s) {
            return sym;
        }
        let leaked: &'static str = Box::leak(s.to_string().into_boxed_str());
        let sym = Symbol(i.strings.len() as u32);
        i.map.insert(leaked, sym);
        i.strings.push(leaked);
        sym
    }

    pub fn as_str(self) -> &'static str {
        let i = interner().lock().unwrap();
        i.strings[self.0 as usize]
    }

    pub fn is_keyword(self) -> bool {
        (self.0 as usize) < KEYWORDS_END
    }
    pub fn is_reserved(self) -> bool {
        (self.0 as usize) >= KEYWORDS_END && (self.0 as usize) < RESERVED_END
    }
    pub fn is_yul_keyword(self) -> bool {
        (self.0 as usize) >= RESERVED_END && (self.0 as usize) < YUL_KW_END
    }
    pub fn is_yul_builtin(self) -> bool {
        (self.0 as usize) >= YUL_KW_END && (self.0 as usize) < YUL_BUILTIN_END
    }
    /// Keywords that may not be used as identifiers (non-contextual).
    pub fn is_used_keyword(self) -> bool {
        self.is_keyword() || self.is_reserved()
    }
    pub fn is_elementary_type(self) -> bool {
        matches!(
            self,
            kw::Address | kw::Bool | kw::String | kw::Bytes | kw::Fixed | kw::UFixed | kw::Int | kw::UInt
        ) || elementary_type_size(self).is_some()
    }
    pub fn is_bool_lit(self) -> bool {
        self == kw::True || self == kw::False
    }
    pub fn is_unit(self) -> bool {
        matches!(
            self,
            kw::Wei | kw::Gwei | kw::Ether | kw::Seconds | kw::Minutes | kw::Hours | kw::Days | kw::Weeks | kw::Years
        )
    }
}

/// Returns `Some((kind, size))` for `uintN`, `intN`, `bytesN`: kind 0 = uint, 1 = int, 2 = bytes.
pub fn elementary_type_size(sym: Symbol) -> Option<(u8, u16)> {
    let idx = sym.0 as usize;
    if idx >= SIZED_START && idx < SIZED_END {
        let off = idx - SIZED_START;
        // 32 uintN, 32 intN, 32 bytesN
        let kind = (off / 32) as u8;
        let n = (off % 32) as u16 + 1;
        return Some((kind, if kind == 2 { n } else { n * 8 }));
    }
    None
}

impl fmt::Debug for Symbol {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.as_str())
    }
}
impl fmt::Display for Symbol {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.as_str())
    }
}

macro_rules! define_symbols {
    (
        keywords { $($kw:ident : $kws:literal,)* }
        reserved { $($rw:ident : $rws:literal,)* }
        yul_keywords { $($yk:ident : $yks:literal,)* }
        yul_builtins { $($yb:ident : $ybs:literal,)* }
        sized { $($sz:ident : $szs:literal,)* }
        other { $($o:ident : $os:literal,)* }
    ) => {
        #[allow(non_upper_case_globals, dead_code)]
        pub mod kw {
            use super::Symbol;
            define_symbols!(@idx 0u32; $($kw)* $($rw)* $($yk)* $($yb)* $($sz)* $($o)*);
        }
        pub const PREDEFINED: &[&str] = &[$($kws,)* $($rws,)* $($yks,)* $($ybs,)* $($szs,)* $($os,)*];
        pub const KEYWORDS_END: usize = [$($kws,)*].len();
        pub const RESERVED_END: usize = KEYWORDS_END + [$($rws,)*].len();
        pub const YUL_KW_END: usize = RESERVED_END + [$($yks,)*].len();
        pub const YUL_BUILTIN_END: usize = YUL_KW_END + [$($ybs,)*].len();
        pub const SIZED_START: usize = YUL_BUILTIN_END;
        pub const SIZED_END: usize = SIZED_START + [$($szs,)*].len();
    };
    (@idx $i:expr; $name:ident $($rest:ident)*) => {
        pub const $name: Symbol = Symbol($i);
        define_symbols!(@idx $i + 1u32; $($rest)*);
    };
    (@idx $i:expr;) => {};
}

