cat > /workspace/src/source_map.rs <<'EOF'
use crate::span::Span;
use std::cell::RefCell;
use std::path::PathBuf;
use std::rc::Rc;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum FileName {
    Real(PathBuf),
    Stdin,
    Custom(String),
}

impl FileName {
    pub fn display(&self) -> String {
        match self {
            FileName::Real(p) => p.display().to_string(),
            FileName::Stdin => "<stdin>".to_string(),
            FileName::Custom(s) => format!("<{s}>"),
        }
    }
}

pub struct SourceFile {
    pub name: FileName,
    pub src: Rc<String>,
    /// Start position of this file in the global source map.
    pub start_pos: u32,
    /// Byte offsets (relative to file) at which each line starts.
    pub lines: Vec<u32>,
    /// Positions (relative) of multibyte chars: (pos, byte len)
    pub multibyte: Vec<(u32, u8)>,
}

impl SourceFile {
    pub fn new(name: FileName, src: String, start_pos: u32) -> SourceFile {
        let mut lines = vec![0u32];
        let mut multibyte = Vec::new();
        let bytes = src.as_bytes();
        let mut i = 0;
        while i < bytes.len() {
            let b = bytes[i];
            if b == b'\n' {
                lines.push((i + 1) as u32);
                i += 1;
            } else if b < 0x80 {
                i += 1;
            } else {
                let len = if b >= 0xF0 { 4 } else if b >= 0xE0 { 3 } else { 2 };
                multibyte.push((i as u32, len as u8));
                i += len;
            }
        }
        SourceFile { name, src: Rc::new(src), start_pos, lines, multibyte }
    }

    pub fn end_pos(&self) -> u32 {
        self.start_pos + self.src.len() as u32
    }

    /// Returns the 0-based line index for a relative byte position.
    pub fn lookup_line(&self, rel_pos: u32) -> usize {
        match self.lines.binary_search(&rel_pos) {
            Ok(i) => i,
            Err(i) => i - 1,
        }
    }

    pub fn line_bounds(&self, line: usize) -> (u32, u32) {
        let start = self.lines[line];
        let end = if line + 1 < self.lines.len() { self.lines[line + 1] } else { self.src.len() as u32 };
        (start, end)
    }

    /// Line text without trailing newline.
    pub fn get_line(&self, line: usize) -> Option<&str> {
        if line >= self.lines.len() {
            return None;
        }
        let (start, end) = self.line_bounds(line);
        let mut s = &self.src[start as usize..end as usize];
        if let Some(stripped) = s.strip_suffix('\n') {
            s = stripped;
        }
        if let Some(stripped) = s.strip_suffix('\r') {
            s = stripped;
        }
        Some(s)
    }

    pub fn num_lines(&self) -> usize {
        self.lines.len()
    }

    /// Returns (line 0-based, column 0-based in chars, column display width) for a relative byte pos.
    pub fn lookup_char_pos(&self, rel_pos: u32) -> Loc {
        let line = self.lookup_line(rel_pos);
        let (start, _) = self.line_bounds(line);
        let text = &self.src[start as usize..rel_pos as usize];
        let col_chars = text.chars().count();
        let col_display = crate::diag::human::str_width(text);
        Loc { line, col: col_chars, col_display }
    }
}

#[derive(Clone, Copy, Debug)]
pub struct Loc {
    /// 0-based line
    pub line: usize,
    /// 0-based column, in chars
    pub col: usize,
    /// 0-based column, in display width
    pub col_display: usize,
}

#[derive(Default)]
pub struct SourceMap {
    files: RefCell<Vec<Rc<SourceFile>>>,
}

impl SourceMap {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn new_source_file(&self, name: FileName, src: String) -> Rc<SourceFile> {
        let mut files = self.files.borrow_mut();
        // Leave a 1-byte gap between files so that EOF positions are unambiguous.
        let start_pos = files.last().map(|f| f.end_pos() + 1).unwrap_or(0);
        let file = Rc::new(SourceFile::new(name, src, start_pos));
        files.push(file.clone());
        file
    }

    pub fn get_by_name(&self, name: &FileName) -> Option<Rc<SourceFile>> {
        self.files.borrow().iter().find(|f| &f.name == name).cloned()
    }

    pub fn files(&self) -> Vec<Rc<SourceFile>> {
        self.files.borrow().clone()
    }

    pub fn lookup_file(&self, pos: u32) -> Rc<SourceFile> {
        let files = self.files.borrow();
        let idx = match files.binary_search_by_key(&pos, |f| f.start_pos) {
            Ok(i) => i,
            Err(i) => i.saturating_sub(1),
        };
        files[idx].clone()
    }

    pub fn span_to_snippet(&self, span: Span) -> String {
        let f = self.lookup_file(span.lo);
        let lo = (span.lo - f.start_pos) as usize;
        let hi = ((span.hi - f.start_pos) as usize).min(f.src.len());
        f.src[lo..hi].to_string()
    }

    /// Returns file, (line 1-based, col 1-based char)
    pub fn span_to_location(&self, span: Span) -> (Rc<SourceFile>, usize, usize) {
        let f = self.lookup_file(span.lo);
        let loc = f.lookup_char_pos(span.lo - f.start_pos);
        (f, loc.line + 1, loc.col + 1)
    }

    pub fn span_to_string(&self, span: Span) -> String {
        let f = self.lookup_file(span.lo);
        let lo = f.lookup_char_pos(span.lo - f.start_pos);
        let hi = f.lookup_char_pos(span.hi - f.start_pos);
