use std::fmt;

/// A byte position in the global source map.
#[derive(Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Default)]
pub struct BytePos(pub u32);

#[derive(Clone, Copy, PartialEq, Eq, Hash, Default)]
pub struct Span {
    pub lo: u32,
    pub hi: u32,
}

impl Span {
    pub const DUMMY: Span = Span { lo: 0, hi: 0 };

    pub fn new(lo: u32, hi: u32) -> Span {
        if lo <= hi { Span { lo, hi } } else { Span { lo: hi, hi: lo } }
    }
    pub fn lo(&self) -> u32 {
        self.lo
    }
    pub fn hi(&self) -> u32 {
        self.hi
    }
    pub fn is_dummy(&self) -> bool {
        self.lo == 0 && self.hi == 0
    }
    pub fn to(self, other: Span) -> Span {
        Span::new(self.lo.min(other.lo), self.hi.max(other.hi))
    }
    pub fn until(self, other: Span) -> Span {
        Span::new(self.lo, other.lo)
    }
    pub fn between(self, other: Span) -> Span {
        Span::new(self.hi, other.lo)
    }
    pub fn shrink_to_lo(self) -> Span {
        Span::new(self.lo, self.lo)
    }
    pub fn shrink_to_hi(self) -> Span {
        Span::new(self.hi, self.hi)
    }
    pub fn with_lo(self, lo: u32) -> Span {
        Span::new(lo, self.hi)
    }
    pub fn with_hi(self, hi: u32) -> Span {
        Span::new(self.lo, hi)
    }
    pub fn len(&self) -> u32 {
        self.hi - self.lo
    }
    pub fn contains(&self, other: Span) -> bool {
        self.lo <= other.lo && other.hi <= self.hi
    }
}

