pub const DEFAULT_COLUMN_WIDTH: usize = 140;

pub fn char_width(c: char) -> usize {
    match c {
        '\t' => 4,
        _ => unicode_char_width(c),
    }
}

pub fn str_width(s: &str) -> usize {
    s.chars().map(char_width).sum()
}

/// Approximate unicode width (wide East Asian chars = 2, combining = 0, else 1).
pub fn unicode_char_width(c: char) -> usize {
    let cp = c as u32;
    if cp == 0 {
        return 0;
    }
    if cp < 0x20 || (0x7f..0xa0).contains(&cp) {
        return 1;
    }
    // Combining marks
    if (0x0300..=0x036F).contains(&cp)
        || (0x0483..=0x0489).contains(&cp)
        || (0x0591..=0x05BD).contains(&cp)
        || (0x0610..=0x061A).contains(&cp)
        || (0x064B..=0x065F).contains(&cp)
        || (0x200B..=0x200F).contains(&cp)
        || (0x20D0..=0x20FF).contains(&cp)
        || (0xFE00..=0xFE0F).contains(&cp)
        || (0xFE20..=0xFE2F).contains(&cp)
        || (0xE0100..=0xE01EF).contains(&cp)
    {
        return 0;
    }
    if (0x1100..=0x115F).contains(&cp)
        || (0x2E80..=0x303E).contains(&cp)
        || (0x3041..=0x33FF).contains(&cp)
        || (0x3400..=0x4DBF).contains(&cp)
        || (0x4E00..=0x9FFF).contains(&cp)
        || (0xA000..=0xA4CF).contains(&cp)
        || (0xAC00..=0xD7A3).contains(&cp)
        || (0xF900..=0xFAFF).contains(&cp)
        || (0xFE30..=0xFE4F).contains(&cp)
        || (0xFF00..=0xFF60).contains(&cp)
        || (0xFFE0..=0xFFE6).contains(&cp)
        || (0x1F300..=0x1F64F).contains(&cp)
        || (0x1F900..=0x1F9FF).contains(&cp)
        || (0x20000..=0x2FFFD).contains(&cp)
        || (0x30000..=0x3FFFD).contains(&cp)
    {
        return 2;
    }
    1
}

pub fn normalize_whitespace(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '\t' => out.push_str("    "),
            '\u{200D}' | '\u{202A}' | '\u{202B}' | '\u{202D}' | '\u{202E}' | '\u{2066}' | '\u{2067}' | '\u{2068}'
            | '\u{202C}' | '\u{2069}' => {}
            _ => out.push(c),
        }
    }
    out
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Style {
    MainHeaderMsg,
    HeaderMsg,
    LineAndColumn,
    LineNumber,
    Quotation,
    UnderlinePrimary,
    UnderlineSecondary,
    LabelPrimary,
    LabelSecondary,
    NoStyle,
    Level(Level),
}

#[derive(Clone, Debug)]
struct StyledString {
    text: String,
    style: Style,
}

#[derive(Default)]
struct StyledBuffer {
    lines: Vec<Vec<(char, Style)>>,
}

impl StyledBuffer {
    fn new() -> Self {
        Self::default()
    }

    fn ensure_lines(&mut self, line: usize) {
        while line >= self.lines.len() {
            self.lines.push(Vec::new());
        }
    }

    fn putc(&mut self, line: usize, col: usize, chr: char, style: Style) {
        self.ensure_lines(line);
        if col >= self.lines[line].len() {
            self.lines[line].resize(col + 1, (' ', Style::NoStyle));
        }
        self.lines[line][col] = (chr, style);
    }

    fn puts(&mut self, line: usize, col: usize, string: &str, style: Style) {
        let mut n = col;
        for c in string.chars() {
            self.putc(line, n, c, style);
            n += 1;
        }
    }

    fn prepend(&mut self, line: usize, string: &str, style: Style) {
        self.ensure_lines(line);
        let string_len = string.chars().count();
        if !self.lines[line].is_empty() {
            for _ in 0..string_len {
                self.lines[line].insert(0, (' ', Style::NoStyle));
            }
        }
        self.puts(line, 0, string, style);
    }

    fn append(&mut self, line: usize, string: &str, style: Style) {
        if line >= self.lines.len() {
            self.puts(line, 0, string, style);
        } else {
            let col = self.lines[line].len();
            self.puts(line, col, string, style);
        }
    }

    fn num_lines(&self) -> usize {
        self.lines.len()
    }

    fn replace(&mut self, line: usize, start: usize, end: usize, string: &str) {
        if start > end || line >= self.lines.len() {
            return;
        }
        let l = &mut self.lines[line];
        let end = end.min(l.len());
        let start = start.min(end);
        let replacement: Vec<(char, Style)> = string.chars().map(|c| (c, Style::LineNumber)).collect();
        l.splice(start..end, replacement);
    }

    fn render(&self) -> Vec<Vec<StyledString>> {
        let mut output = vec![];
        for line in &self.lines {
            let mut styled_vec: Vec<StyledString> = vec![];
            let mut current_style = Style::NoStyle;
            let mut current_text = String::new();
            for &(c, style) in line {
                if style != current_style {
                    if !current_text.is_empty() {
                        styled_vec.push(StyledString { text: current_text.clone(), style: current_style });
                    }
                    current_style = style;
                    current_text = String::new();
                }
                current_text.push(c);
            }
            if !current_text.is_empty() {
                styled_vec.push(StyledString { text: current_text, style: current_style });
            }
            output.push(styled_vec);
        }
        output
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Default)]
struct AnnotationColumn {
    display: usize,
    file: usize,
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum AnnotationType {
    Singleline,
    MultilineStart(usize),
    MultilineEnd(usize),
    MultilineLine(usize),
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct Annotation {
    start_col: AnnotationColumn,
    end_col: AnnotationColumn,
    is_primary: bool,
    label: Option<String>,
    annotation_type: AnnotationType,
}

impl Annotation {
    fn is_line(&self) -> bool {
        matches!(self.annotation_type, AnnotationType::MultilineLine(_))
    }
    fn len(&self) -> usize {
        if self.end_col.display > self.start_col.display {
            self.end_col.display - self.start_col.display
        } else {
            self.start_col.display - self.end_col.display
        }
    }
    fn has_label(&self) -> bool {
        matches!(&self.label, Some(l) if !l.is_empty())
    }
    fn takes_space(&self) -> bool {
        matches!(self.annotation_type, AnnotationType::MultilineStart(_) | AnnotationType::MultilineEnd(_))
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct MultilineAnnotation {
    depth: usize,
    line_start: usize,
    line_end: usize,
    start_col: AnnotationColumn,
    end_col: AnnotationColumn,
    is_primary: bool,
    label: Option<String>,
    overlaps_exactly: bool,
}

impl MultilineAnnotation {
    fn increase_depth(&mut self) {
        self.depth += 1;
    }
    fn same_span(&self, other: &MultilineAnnotation) -> bool {
        self.line_start == other.line_start
            && self.line_end == other.line_end
            && self.start_col == other.start_col
            && self.end_col == other.end_col
    }
    fn as_start(&self) -> Annotation {
        Annotation {
            start_col: self.start_col,
            end_col: AnnotationColumn { file: self.start_col.file + 1, display: self.start_col.display + 1 },
            is_primary: self.is_primary,
            label: None,
            annotation_type: AnnotationType::MultilineStart(self.depth),
        }
    }
    fn as_end(&self) -> Annotation {
        Annotation {
            start_col: AnnotationColumn {
                file: self.end_col.file.saturating_sub(1),
                display: self.end_col.display.saturating_sub(1),
            },
            end_col: self.end_col,
            is_primary: self.is_primary,
            label: self.label.clone(),
            annotation_type: AnnotationType::MultilineEnd(self.depth),
        }
    }
    fn as_line(&self) -> Annotation {
        Annotation {
            start_col: AnnotationColumn::default(),
            end_col: AnnotationColumn::default(),
            is_primary: self.is_primary,
            label: None,
            annotation_type: AnnotationType::MultilineLine(self.depth),
        }
    }
}

#[derive(Clone, Debug)]
struct Line {
    /// 1-based line index
    line_index: usize,
    annotations: Vec<Annotation>,
}

struct FileWithAnnotatedLines {
    file: Rc<SourceFile>,
    lines: Vec<Line>,
    multiline_depth: usize,
}

#[derive(Clone, Copy, Debug)]
struct Margin {
    whitespace_left: usize,
    span_left: usize,
    span_right: usize,
    computed_left: usize,
    computed_right: usize,
    column_width: usize,
    label_right: usize,
}

impl Margin {
    fn new(
        whitespace_left: usize,
        span_left: usize,
        span_right: usize,
        label_right: usize,
        column_width: usize,
        max_line_len: usize,
    ) -> Self {
        let mut m = Margin {
            whitespace_left: whitespace_left.saturating_sub(6),
            span_left: span_left.saturating_sub(6),
            span_right: span_right + 6,
            computed_left: 0,
            computed_right: 0,
            column_width,
            label_right: label_right + 6,
        };
        m.compute(max_line_len);
        m
    }

    fn was_cut_left(&self) -> bool {
        self.computed_left > 0
    }

    fn was_cut_right(&self, line_len: usize) -> bool {
        let right = if self.computed_right == self.span_right || self.computed_right == self.label_right {
            self.computed_right.saturating_sub(6)
        } else {
            self.computed_right
        };
        right < line_len && self.computed_left + self.column_width < line_len
    }

    fn compute(&mut self, max_line_len: usize) {
        self.computed_left = if self.whitespace_left > 20 { self.whitespace_left - 16 } else { 0 };
        self.computed_right = max(max_line_len, self.computed_left);

        if self.computed_right - self.computed_left > self.column_width {
            if self.label_right.saturating_sub(self.whitespace_left) <= self.column_width {
                self.computed_left = self.whitespace_left;
                self.computed_right = self.computed_left + self.column_width;
            } else if self.label_right.saturating_sub(self.span_left) <= self.column_width {
                let padding_left = (self.column_width - (self.label_right - self.span_left)) / 2;
                self.computed_left = self.span_left.saturating_sub(padding_left);
                self.computed_right = self.computed_left + self.column_width;
            } else if self.span_right.saturating_sub(self.span_left) <= self.column_width {
                let padding_left = (self.column_width - (self.span_right - self.span_left)) / 5 * 2;
                self.computed_left = self.span_left.saturating_sub(padding_left);
                self.computed_right = self.computed_left + self.column_width;
            } else {
                self.computed_left = self.span_left;
                self.computed_right = self.span_right;
            }
        }
    }

    fn left(&self, line_len: usize) -> usize {
        min(self.computed_left, line_len)
    }

    fn right(&self, line_len: usize) -> usize {
        if line_len.saturating_sub(self.computed_left) <= self.column_width {
            line_len
        } else {
            min(line_len, self.computed_right)
        }
    }
}

struct UnderlineParts {
    style: Style,
    underline: char,
    label_start: char,
    vertical_text_line: char,
    multiline_vertical: char,
    multiline_horizontal: char,
    multiline_whole_line: char,
    multiline_start_down: char,
    bottom_right: char,
    top_left: char,
    top_right_flat: char,
    bottom_left: char,
    #[allow(dead_code)]
    multiline_end_up: char,
    multiline_end_same_line: char,
    multiline_bottom_right_with_text: char,
}

pub struct Renderer<'a> {
    dcx: &'a DiagCtxt,
    unicode: bool,
    short: bool,
    color: bool,
}

fn overlaps(a1: &Annotation, a2: &Annotation, padding: usize) -> bool {
    num_overlap(a1.start_col.display, a1.end_col.display + padding, a2.start_col.display, a2.end_col.display, false)
}

fn num_overlap(a_start: usize, a_end: usize, b_start: usize, b_end: usize, inclusive: bool) -> bool {
    let extra = if inclusive { 1 } else { 0 };
    (b_start..b_end + extra).contains(&a_start) || (a_start..a_end + extra).contains(&b_start)
}

pub fn render(dcx: &DiagCtxt, diag: &Diag, color: bool) -> String {
    let r = Renderer {
        dcx,
        unicode: dcx.config.style == HumanStyle::Unicode,
        short: dcx.config.style == HumanStyle::Short,
        color,
    };
    r.emit_diagnostic(diag)
}

impl<'a> Renderer<'a> {
    fn style_prefix(&self, style: Style, level: Level) -> &'static str {
        match style {
            Style::LineAndColumn | Style::NoStyle | Style::Quotation | Style::HeaderMsg => "",
            Style::LineNumber | Style::UnderlineSecondary | Style::LabelSecondary => "\x1b[1m\x1b[94m",
            Style::MainHeaderMsg => "\x1b[1m",
            Style::Level(l) | Style::UnderlinePrimary | Style::LabelPrimary => {
                let l = if matches!(style, Style::Level(_)) { if let Style::Level(l) = style { l } else { level } } else { level };
                match l {
                    Level::Error => "\x1b[1m\x1b[91m",
                    Level::Warning => "\x1b[1m\x1b[33m",
                    Level::Note => "\x1b[1m\x1b[92m",
                    Level::Help => "\x1b[1m\x1b[96m",
                }
            }
        }
    }

    fn render_buffer(&self, buffer: &StyledBuffer, level: Level, out: &mut String) {
        for line in buffer.render() {
            for part in line {
                if self.color {
                    let prefix = self.style_prefix(part.style, level);
                    if prefix.is_empty() {
                        out.push_str(&part.text);
                    } else {
                        out.push_str(prefix);
                        out.push_str(&part.text);
                        out.push_str("\x1b[0m");
                    }
                } else {
                    out.push_str(&part.text);
                }
            }
            out.push('\n');
        }
    }

    pub fn emit_diagnostic(&self, diag: &Diag) -> String {
        let mut out = String::new();
        let max_line_num_len = if self.short { 0 } else { self.get_max_line_num(diag).to_string().len() };
        let primary = self.emit_messages_default_inner(
            &diag.span,
            &diag.message,
            diag.code,
            diag.level,
            max_line_num_len,
            false,
            !diag.children.is_empty(),
        );
        self.render_buffer(&primary, diag.level, &mut out);
        if !self.short {
            for (i, child) in diag.children.iter().enumerate() {
                let should_close = match diag.children.get(i + 1) {
                    Some(c) => c.span.has_primary_spans(),
                    None => i + 1 == diag.children.len(),
                };
                let buf = self.emit_messages_default_inner(
                    &child.span,
                    &child.message,
                    None,
                    child.level,
                    max_line_num_len,
                    true,
                    !should_close,
                );
                self.render_buffer(&buf, child.level, &mut out);
            }
        }
        out.push('\n');
        out
    }

    fn get_max_line_num(&self, diag: &Diag) -> usize {
        let mut m = self.get_multispan_max_line_num(&diag.span);
        for child in &diag.children {
            m = max(m, self.get_multispan_max_line_num(&child.span));
        }
        m
    }

    fn get_multispan_max_line_num(&self, msp: &MultiSpan) -> usize {
        let sm = &self.dcx.source_map;
        let mut m = 0;
        for primary_span in &msp.primary_spans {
            if !primary_span.is_dummy() {
                let (_, line, _) = sm.span_to_location(primary_span.shrink_to_hi());
                m = max(m, line);
            }
        }
        for (span, _) in &msp.span_labels {
            if !span.is_dummy() {
                let (_, line, _) = sm.span_to_location(span.shrink_to_hi());
                m = max(m, line);
            }
        }
        m
    }

    fn underline(&self, is_primary: bool) -> UnderlineParts {
        let style = if is_primary { Style::UnderlinePrimary } else { Style::UnderlineSecondary };
        match (self.unicode, is_primary) {
            (false, true) => UnderlineParts {
                style,
                underline: '^',
                label_start: '^',
                vertical_text_line: '|',
                multiline_vertical: '|',
                multiline_horizontal: '_',
                multiline_whole_line: '/',
                multiline_start_down: '^',
                bottom_right: '|',
                top_left: ' ',
                top_right_flat: '^',
                bottom_left: '|',
                multiline_end_up: '^',
                multiline_end_same_line: '^',
                multiline_bottom_right_with_text: '|',
            },
            (false, false) => UnderlineParts {
                style,
                underline: '-',
                label_start: '-',
                vertical_text_line: '|',
                multiline_vertical: '|',
                multiline_horizontal: '_',
                multiline_whole_line: '/',
                multiline_start_down: '-',
                bottom_right: '|',
                top_left: ' ',
                top_right_flat: '-',
                bottom_left: '|',
                multiline_end_up: '-',
                multiline_end_same_line: '-',
                multiline_bottom_right_with_text: '|',
            },
            (true, true) => UnderlineParts {
                style,
                underline: '━',
                label_start: '┯',
                vertical_text_line: '│',
                multiline_vertical: '┃',
                multiline_horizontal: '━',
                multiline_whole_line: '┏',
                multiline_start_down: '╿',
                bottom_right: '┘',
                top_left: '┏',
                top_right_flat: '┛',
                bottom_left: '┗',
                multiline_end_up: '╿',
                multiline_end_same_line: '┛',
                multiline_bottom_right_with_text: '┥',
            },
            (true, false) => UnderlineParts {
                style,
                underline: '─',
                label_start: '┬',
                vertical_text_line: '│',
                multiline_vertical: '│',
                multiline_horizontal: '─',
                multiline_whole_line: '┌',
                multiline_start_down: '│',
                bottom_right: '┘',
                top_left: '┌',
                top_right_flat: '┘',
                bottom_left: '└',
                multiline_end_up: '│',
                multiline_end_same_line: '┘',
                multiline_bottom_right_with_text: '┤',
            },
        }
    }

    fn col_separator(&self) -> char {
        if self.unicode { '│' } else { '|' }
    }
    fn draw_col_separator_no_space(&self, buffer: &mut StyledBuffer, line: usize, col: usize) {
        let chr = self.col_separator();
        buffer.putc(line, col, chr, Style::LineNumber);
    }
    fn draw_col_separator_end(&self, buffer: &mut StyledBuffer, line: usize, col: usize) {
        if self.unicode {
            buffer.puts(line, col, "╰╴", Style::LineNumber);
        } else {
            buffer.puts(line, col, "|", Style::LineNumber);
        }
    }
    fn draw_note_separator(&self, buffer: &mut StyledBuffer, line: usize, col: usize, is_cont: bool) {
        let chr = if !self.unicode {
            "= "
        } else if is_cont {
            "├ "
        } else {
            "╰ "
        };
        buffer.puts(line, col, chr, Style::LineNumber);
    }
    fn file_start(&self) -> &'static str {
        if self.unicode { " ╭▸ " } else { "--> " }
    }
    fn secondary_file_start(&self) -> &'static str {
        if self.unicode { " ⸬ " } else { "::: " }
    }
    fn draw_line_separator(&self, buffer: &mut StyledBuffer, line: usize, col: usize) {
        let (column, dots) = if self.unicode { (col, "‡") } else { (0, "...") };
        buffer.puts(line, column, dots, Style::LineNumber);
    }
    fn margin(&self) -> &'static str {
        if self.unicode { "…" } else { "..." }
    }
    fn draw_multiline_line(&self, buffer: &mut StyledBuffer, line: usize, offset: usize, depth: usize, style: Style) {
        let chr = match (style, self.unicode) {
            (Style::UnderlinePrimary | Style::LabelPrimary, true) => '┃',
            (_, true) => '│',
            (_, false) => '|',
        };
        buffer.putc(line, offset + depth - 1, chr, style);
    }
    fn draw_range(&self, buffer: &mut StyledBuffer, symbol: char, line: usize, col_from: usize, col_to: usize, style: Style) {
        for col in col_from..col_to {
            buffer.putc(line, col, symbol, style);
        }
    }

    fn column_width(&self, code_offset: usize) -> usize {
        if let Some(width) = self.dcx.config.width {
            width.saturating_sub(code_offset)
        } else if self.dcx.config.ui_testing {
            DEFAULT_COLUMN_WIDTH
        } else {
            match terminal_width() {
                Some(w) => w.saturating_sub(code_offset),
                None => DEFAULT_COLUMN_WIDTH,
            }
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn emit_messages_default_inner(
        &self,
        msp: &MultiSpan,
        msg: &str,
        code: Option<u32>,
        level: Level,
        max_line_num_len: usize,
        is_secondary: bool,
        is_cont: bool,
    ) -> StyledBuffer {
        let mut buffer = StyledBuffer::new();
        let sm = &self.dcx.source_map;

        if !msp.has_primary_spans() && msp.span_labels.is_empty() && is_secondary && !self.short {
            // This is a secondary message with no span info
            for _ in 0..max_line_num_len {
                buffer.prepend(0, " ", Style::NoStyle);
            }
            self.draw_note_separator(&mut buffer, 0, max_line_num_len + 1, is_cont);
            buffer.append(0, level.as_str(), Style::MainHeaderMsg);
            buffer.append(0, ": ", Style::NoStyle);
            let printed_lines = self.msgs_to_buffer(&mut buffer, msg, max_line_num_len, "note");
            if is_cont && self.unicode {
                for i in 1..=printed_lines {
                    self.draw_col_separator_no_space(&mut buffer, i, max_line_num_len + 1);
                }
            }
        } else {
            let mut label_width = 0;
            buffer.append(0, level.as_str(), Style::Level(level));
            label_width += level.as_str().len();
            if let Some(code) = code {
                buffer.append(0, "[", Style::Level(level));
                let code = code.to_string();
                buffer.append(0, &code, Style::Level(level));
                buffer.append(0, "]", Style::Level(level));
                label_width += 2 + code.len();
            }
            let header_style = if is_secondary { Style::HeaderMsg } else { Style::MainHeaderMsg };
            buffer.append(0, ": ", header_style);
            label_width += 2;
            let mut line = 0;
            for text in normalize_whitespace(msg).lines() {
                buffer.append(line, &format!("{}{}", " ".repeat(if line == 0 { 0 } else { label_width }), text), header_style);
                line += 1;
            }
            let _ = line;
            if self.short {
                if let Some(primary_span) = msp.primary_span() {
                    if !primary_span.is_dummy() {
                        let (file, line, col) = sm.span_to_location(primary_span);
                        buffer.prepend(0, &format!("{}:{}:{}: ", file.name.display(), line, col), Style::LineAndColumn);
                    }
                }
                return buffer;
            }
        }

        let mut annotated_files = self.collect_annotations(msp);

        let primary_span = msp.primary_span().unwrap_or_default();
        if primary_span.is_dummy() {
            return buffer;
        }
        let (primary_file, primary_line, primary_col) = sm.span_to_location(primary_span);
        if let Some(pos) = annotated_files.iter().position(|x| x.file.name == primary_file.name) {
            annotated_files.swap(0, pos);
        }

        for annotated_file in annotated_files {
            let is_primary = primary_file.name == annotated_file.file.name;
            if is_primary {
                let buffer_msg_line_offset = buffer.num_lines();
                buffer.prepend(buffer_msg_line_offset, self.file_start(), Style::LineNumber);
                buffer.append(
                    buffer_msg_line_offset,
                    &format!("{}:{}:{}", primary_file.name.display(), primary_line, primary_col),
                    Style::LineAndColumn,
                );
                for _ in 0..max_line_num_len {
                    buffer.prepend(buffer_msg_line_offset, " ", Style::NoStyle);
                }
            } else {
                let buffer_msg_line_offset = buffer.num_lines();
                self.draw_col_separator_no_space(&mut buffer, buffer_msg_line_offset, max_line_num_len + 1);
                buffer.prepend(buffer_msg_line_offset + 1, self.secondary_file_start(), Style::LineNumber);
                let loc = if let Some(first_line) = annotated_file.lines.first() {
                    let col = if let Some(first_annotation) = first_line.annotations.first() {
                        format!(":{}", first_annotation.start_col.file + 1)
                    } else {
                        String::new()
                    };
                    format!("{}:{}{}", annotated_file.file.name.display(), first_line.line_index, col)
                } else {
                    annotated_file.file.name.display()
                };
                buffer.append(buffer_msg_line_offset + 1, &loc, Style::LineAndColumn);
                for _ in 0..max_line_num_len {
                    buffer.prepend(buffer_msg_line_offset + 1, " ", Style::NoStyle);
                }
            }

            // Put in the spacer between the location and annotated source
            let buffer_msg_line_offset = buffer.num_lines();
            self.draw_col_separator_no_space(&mut buffer, buffer_msg_line_offset, max_line_num_len + 1);

            // Contains the vertical lines' positions for active multiline annotations
            let mut multilines: Vec<(usize, Style)> = Vec::new();

            // Get the left-side margin to remove it
            let mut whitespace_margin = usize::MAX;
            for line in &annotated_file.lines {
                if let Some(source_string) = line.line_index.checked_sub(1).and_then(|l| annotated_file.file.get_line(l)) {
                    let leading_whitespace: usize = source_string
                        .chars()
                        .take_while(|c| is_whitespace(*c))
                        .map(|c| match c {
                            '\t' => 4,
                            _ => 1,
                        })
                        .sum();
                    if source_string.chars().any(|c| !is_whitespace(c)) {
                        whitespace_margin = min(whitespace_margin, leading_whitespace);
                    }
                }
            }
            if whitespace_margin == usize::MAX {
                whitespace_margin = 0;
            }

            let mut span_left_margin = usize::MAX;
            for line in &annotated_file.lines {
                for ann in &line.annotations {
                    span_left_margin = min(span_left_margin, ann.start_col.display);
                    span_left_margin = min(span_left_margin, ann.end_col.display);
                }
            }
            if span_left_margin == usize::MAX {
                span_left_margin = 0;
            }

            let mut span_right_margin = 0;
            let mut label_right_margin = 0;
            let mut max_line_len = 0;
            for line in &annotated_file.lines {
                max_line_len = max(
                    max_line_len,
                    annotated_file.file.get_line(line.line_index - 1).map_or(0, |s| s.len()),
                );
                for ann in &line.annotations {
                    span_right_margin = max(span_right_margin, ann.start_col.display);
                    span_right_margin = max(span_right_margin, ann.end_col.display);
                    let label_right = ann.label.as_ref().map_or(0, |l| l.len() + 1);
                    label_right_margin = max(label_right_margin, ann.end_col.display + label_right);
                }
            }

            let width_offset = 3 + max_line_num_len;
            let code_offset = if annotated_file.multiline_depth == 0 {
                width_offset
            } else {
                width_offset + annotated_file.multiline_depth + 1
            };

            let column_width = self.column_width(code_offset);

            let margin = Margin::new(
                whitespace_margin,
                span_left_margin,
                span_right_margin,
                label_right_margin,
                column_width,
                max_line_len,
            );

            for line_idx in 0..annotated_file.lines.len() {
                let previous_buffer_line = buffer.num_lines();

                let depths = self.render_source_line(
                    &mut buffer,
                    &annotated_file.file,
                    &annotated_file.lines[line_idx],
                    width_offset,
                    code_offset,
                    margin,
                    !is_cont && line_idx + 1 == annotated_file.lines.len(),
                );

                let mut to_add: Vec<(usize, Style)> = Vec::new();
                for (depth, style) in depths {
                    if let Some(pos) = multilines.iter().position(|(d, _)| *d == depth) {
                        multilines.swap_remove(pos);
                    } else {
                        to_add.push((depth, style));
                    }
                }

                for (depth, style) in &multilines {
                    for line in previous_buffer_line..buffer.num_lines() {
                        self.draw_multiline_line(&mut buffer, line, width_offset, *depth, *style);
                    }
                }
                if line_idx < (annotated_file.lines.len() - 1) {
                    let line_idx_delta =
                        annotated_file.lines[line_idx + 1].line_index - annotated_file.lines[line_idx].line_index;
                    if line_idx_delta > 2 {
                        let last_buffer_line_num = buffer.num_lines();
                        self.draw_line_separator(&mut buffer, last_buffer_line_num, max_line_num_len + 1);
                        for (depth, style) in &multilines {
                            self.draw_multiline_line(&mut buffer, last_buffer_line_num, width_offset, *depth, *style);
                        }
                        if let Some(line) = annotated_file.lines.get(line_idx) {
                            for ann in &line.annotations {
                                if let AnnotationType::MultilineStart(pos) = ann.annotation_type {
                                    self.draw_multiline_line(
                                        &mut buffer,
                                        last_buffer_line_num,
                                        width_offset,
                                        pos,
                                        if ann.is_primary { Style::UnderlinePrimary } else { Style::UnderlineSecondary },
                                    );
                                }
                            }
                        }
                    } else if line_idx_delta == 2 {
                        let unannotated_line = annotated_file
                            .file
                            .get_line(annotated_file.lines[line_idx].line_index)
                            .unwrap_or("")
                            .to_string();
                        let last_buffer_line_num = buffer.num_lines();
                        self.draw_line(
                            &mut buffer,
                            &normalize_whitespace(&unannotated_line),
                            annotated_file.lines[line_idx + 1].line_index - 1,
                            last_buffer_line_num,
                            width_offset,
                            code_offset,
                            margin,
                        );
                        for (depth, style) in &multilines {
                            self.draw_multiline_line(&mut buffer, last_buffer_line_num, width_offset, *depth, *style);
                        }
                        if let Some(line) = annotated_file.lines.get(line_idx) {
                            for ann in &line.annotations {
                                if let AnnotationType::MultilineStart(pos) = ann.annotation_type {
                                    self.draw_multiline_line(
                                        &mut buffer,
                                        last_buffer_line_num,
                                        width_offset,
                                        pos,
                                        if ann.is_primary { Style::UnderlinePrimary } else { Style::UnderlineSecondary },
                                    );
                                }
                            }
                        }
                    }
                }
                multilines.extend(to_add);
            }
        }
        buffer
    }

    fn msgs_to_buffer(&self, buffer: &mut StyledBuffer, msg: &str, padding: usize, label: &str) -> usize {
        // The extra 5 ` ` is padding that's always needed to align to the `note: `:
        //
        //   error: message
        //     --> file.rs:13:20
        //      |
        //   13 |     <CODE>
        //      |      ^^^^
        //      |
        //      = note: multiline
        //              message
        //   ++^^^----xx
        //    |  |   | |
        //    |  |   | magic `2`
        //    |  |   length of label
        //    |  magic `3`
        //    `max_line_num_len`
        let padding = " ".repeat(padding + label.len() + 5);
        let mut line_number = 0;
        let text = normalize_whitespace(msg);
        let lines = text.split('\n').collect::<Vec<_>>();
        if lines.len() > 1 {
            for (i, line) in lines.iter().enumerate() {
                if i != 0 {
                    line_number += 1;
                    buffer.append(line_number, &padding, Style::NoStyle);
                }
                buffer.append(line_number, line, Style::NoStyle);
            }
        } else {
            buffer.append(line_number, &text, Style::NoStyle);
        }
        line_number
    }

    fn collect_annotations(&self, msp: &MultiSpan) -> Vec<FileWithAnnotatedLines> {
        fn add_annotation_to_file(
            file_vec: &mut Vec<FileWithAnnotatedLines>,
            file: Rc<SourceFile>,
            line_index: usize,
            ann: Annotation,
        ) {
            for slot in file_vec.iter_mut() {
                if slot.file.name == file.name {
                    for line_slot in &mut slot.lines {
                        if line_slot.line_index == line_index {
                            line_slot.annotations.push(ann);
                            return;
                        }
                    }
                    slot.lines.push(Line { line_index, annotations: vec![ann] });
                    slot.lines.sort_by_key(|l| l.line_index);
                    return;
                }
            }
            file_vec.push(FileWithAnnotatedLines {
                file,
                lines: vec![Line { line_index, annotations: vec![ann] }],
                multiline_depth: 0,
            });
        }

        let sm = &self.dcx.source_map;
        let mut output: Vec<FileWithAnnotatedLines> = vec![];
        let mut multiline_annotations: Vec<(Rc<SourceFile>, MultilineAnnotation)> = vec![];

        for sl in msp.span_labels() {
            let span = match (sl.span.is_dummy(), msp.primary_span()) {
                (_, None) | (false, _) => sl.span,
                (true, Some(span)) => span,
            };
            if span.is_dummy() {
                continue;
            }
            let file = sm.lookup_file(span.lo);
            let lo = file.lookup_char_pos(span.lo - file.start_pos);
            let hi_pos = (span.hi - file.start_pos).min(file.src.len() as u32);
            let mut hi = file.lookup_char_pos(hi_pos);
            if lo.col_display == hi.col_display && lo.line == hi.line {
                hi.col_display += 1;
            }
            let label = sl.label.as_ref().map(|m| normalize_whitespace(m));
            // 1-based lines
            let lo_line = lo.line + 1;
            let hi_line = hi.line + 1;
            if lo_line != hi_line {
                let ml = MultilineAnnotation {
                    depth: 1,
                    line_start: lo_line,
                    line_end: hi_line,
                    start_col: AnnotationColumn { display: lo.col_display, file: lo.col },
                    end_col: AnnotationColumn { display: hi.col_display, file: hi.col },
                    is_primary: sl.is_primary,
                    label,
                    overlaps_exactly: false,
                };
                multiline_annotations.push((file, ml));
            } else {
                let ann = Annotation {
                    start_col: AnnotationColumn { display: lo.col_display, file: lo.col },
                    end_col: AnnotationColumn { display: hi.col_display, file: hi.col },
                    is_primary: sl.is_primary,
                    label,
                    annotation_type: AnnotationType::Singleline,
                };
                add_annotation_to_file(&mut output, file, lo_line, ann);
            }
        }

        multiline_annotations.sort_by_key(|(_, ml)| (ml.line_start, usize::MAX - ml.line_end));
        let cloned = multiline_annotations.clone();
        for (_, ann) in cloned {
            for (_, a) in multiline_annotations.iter_mut() {
                if !(ann.same_span(a)) && num_overlap(ann.line_start, ann.line_end, a.line_start, a.line_end, true) {
                    a.increase_depth();
                } else if ann.same_span(a) && &ann != a {
                    a.overlaps_exactly = true;
                } else {
                    break;
                }
            }
        }

        let mut max_depth = 0;
        for (_, ann) in &multiline_annotations {
            max_depth = max(max_depth, ann.depth);
        }
        for (_, a) in multiline_annotations.iter_mut() {
            a.depth = max_depth - a.depth + 1;
        }
        for (file, ann) in multiline_annotations {
            let mut end_ann = ann.as_end();
            if !ann.overlaps_exactly {
                add_annotation_to_file(&mut output, file.clone(), ann.line_start, ann.as_start());
                let middle = min(ann.line_start + 4, ann.line_end);
                let filter = |s: &str| {
                    let s = s.trim();
                    !(s.starts_with("//") && !(s.starts_with("///") || s.starts_with("//!")))
                        && !["", "{", "}", "(", ")", "[", "]"].contains(&s)
                };
                let until = (ann.line_start..middle)
                    .rev()
                    .filter_map(|line| file.get_line(line - 1).map(|s| (line + 1, s)))
                    .find(|(_, s)| filter(s))
                    .map(|(line, _)| line)
                    .unwrap_or(ann.line_start);
                for line in ann.line_start + 1..until {
                    add_annotation_to_file(&mut output, file.clone(), line, ann.as_line());
                }
                let line_end = ann.line_end - 1;
                let end_is_empty = file.get_line(line_end - 1).is_some_and(|s| !filter(s));
                if middle < line_end && !end_is_empty {
                    add_annotation_to_file(&mut output, file.clone(), line_end, ann.as_line());
                }
            } else {
                end_ann.annotation_type = AnnotationType::Singleline;
            }
            add_annotation_to_file(&mut output, file, ann.line_end, end_ann);
        }
        for file_vec in output.iter_mut() {
            file_vec.multiline_depth = max_depth;
        }
        output
    }

    #[allow(clippy::too_many_arguments)]
    fn draw_line(
        &self,
        buffer: &mut StyledBuffer,
        source_string: &str,
        line_index: usize,
        line_offset: usize,
        width_offset: usize,
        code_offset: usize,
        margin: Margin,
    ) {
        let line_len = source_string.len();
        let left = margin.left(line_len);
        let right = margin.right(line_len);
        let mut taken = 0;
        let code: String = source_string
            .chars()
            .skip(left)
            .take_while(|ch| {
                let next = char_width(*ch);
                if taken + next > right - left {
                    return false;
                }
                taken += next;
                true
            })
            .collect();
        buffer.puts(line_offset, code_offset, &code, Style::Quotation);
        let placeholder = self.margin();
        if margin.was_cut_left() {
            buffer.puts(line_offset, code_offset, placeholder, Style::LineNumber);
        }
        if margin.was_cut_right(line_len) {
            let padding = str_width(placeholder);
            buffer.puts(line_offset, code_offset + taken - padding, placeholder, Style::LineNumber);
        }
        buffer.puts(line_offset, 0, &line_index.to_string(), Style::LineNumber);
        self.draw_col_separator_no_space(buffer, line_offset, width_offset - 2);
    }

    #[allow(clippy::too_many_arguments)]
    fn render_source_line(
        &self,
        buffer: &mut StyledBuffer,
        file: &Rc<SourceFile>,
        line: &Line,
        width_offset: usize,
        code_offset: usize,
        margin: Margin,
        close_window: bool,
    ) -> Vec<(usize, Style)> {
        if line.line_index == 0 {
            return Vec::new();
        }
        let Some(source_string) = file.get_line(line.line_index - 1) else {
            return Vec::new();
        };
        let source_string = normalize_whitespace(source_string);

        let line_offset = buffer.num_lines();

        let left = margin.left(source_string.len());
        let mut taken = 0;
        let code: String = source_string
            .chars()
            .skip_while(|ch| {
                let next = char_width(*ch);
                if taken + next > left {
                    return false;
                }
                taken += next;
                true
            })
            .collect();
        let _ = code;

        self.draw_line(buffer, &source_string, line.line_index, line_offset, width_offset, code_offset, margin);

        // Special case when there's only one annotation involved, it is the start of a multiline
        // span and there's no text at the beginning of the code line.
        let mut buffer_ops = vec![];
        let mut annotations = vec![];
        let mut short_start = true;
        for ann in &line.annotations {
            if let AnnotationType::MultilineStart(depth) = ann.annotation_type {
                if source_string.chars().take(ann.start_col.display).all(|c| c.is_whitespace()) {
                    let uline = self.underline(ann.is_primary);
                    let chr = uline.multiline_whole_line;
                    annotations.push((depth, uline.style));
                    buffer_ops.push((line_offset, width_offset + depth - 1, chr, uline.style));
                } else {
                    short_start = false;
                }
            } else if let AnnotationType::MultilineLine(_) = ann.annotation_type {
            } else {
                short_start = false;
            }
        }
        if short_start {
            for (y, x, c, s) in buffer_ops {
                buffer.putc(y, x, c, s);
            }
            return annotations;
        }

        let mut annotations = line.annotations.clone();
        annotations.sort_by_key(|a| Reverse(a.start_col));

        let mut annotations_position = vec![];
        let mut line_len: usize = 0;
        let mut p = 0;
        for (i, annotation) in annotations.iter().enumerate() {
            for (j, next) in annotations.iter().enumerate() {
                if overlaps(next, annotation, 0) && annotation.has_label() && j > i && p == 0 {
                    if next.start_col == annotation.start_col && next.end_col == annotation.end_col && !next.has_label() {
                        continue;
                    }
                    p += 1;
                    break;
                }
            }
            annotations_position.push((p, annotation));
            for (j, next) in annotations.iter().enumerate() {
                if j > i {
                    let l = next.label.as_ref().map_or(0, |label| label.len() + 2);
                    if (overlaps(next, annotation, l) && annotation.has_label() && next.has_label())
                        || (annotation.takes_space() && next.has_label())
                        || (annotation.has_label() && next.takes_space())
                        || (annotation.takes_space() && next.takes_space())
                        || (overlaps(next, annotation, l)
                            && next.end_col <= annotation.end_col
                            && next.has_label()
                            && p == 0)
                    {
                        p += 1;
                        break;
                    }
                }
            }
            line_len = max(line_len, p);
        }

        if line_len != 0 {
            line_len += 1;
        }

        if line.annotations.iter().all(|a| a.is_line()) {
            return vec![];
        }

        if annotations_position.iter().all(|(_, ann)| matches!(ann.annotation_type, AnnotationType::MultilineStart(_))) {
            if let Some(max_pos) = annotations_position.iter().map(|(pos, _)| *pos).max() {
                for (pos, _) in &mut annotations_position {
                    *pos = max_pos - *pos;
                }
                line_len = line_len.saturating_sub(1);
            }
        }

        for pos in 0..=line_len {
            self.draw_col_separator_no_space(buffer, line_offset + pos + 1, width_offset - 2);
        }
        if close_window {
            self.draw_col_separator_end(buffer, line_offset + line_len + 1, width_offset - 2);
        }

        // Write the horizontal lines for multiline annotations
        for &(pos, annotation) in &annotations_position {
            let underline = self.underline(annotation.is_primary);
            let pos = pos + 1;
            match annotation.annotation_type {
                AnnotationType::MultilineStart(depth) | AnnotationType::MultilineEnd(depth) => {
                    self.draw_range(
                        buffer,
                        underline.multiline_horizontal,
                        line_offset + pos,
                        width_offset + depth,
                        (code_offset + annotation.start_col.display).saturating_sub(left),
                        underline.style,
                    );
                }
                _ => {}
            }
        }

        // Write the vertical lines for labels that are on a different line as the underline.
        for &(pos, annotation) in &annotations_position {
            let underline = self.underline(annotation.is_primary);
            let pos = pos + 1;

            if pos > 1 && (annotation.has_label() || annotation.takes_space()) {
                for p in line_offset + 1..=line_offset + pos {
                    buffer.putc(
                        p,
                        (code_offset + annotation.start_col.display).saturating_sub(left),
                        match annotation.annotation_type {
                            AnnotationType::MultilineLine(_) => underline.multiline_vertical,
                            _ => underline.vertical_text_line,
                        },
                        underline.style,
                    );
                }
                if let AnnotationType::MultilineStart(_) = annotation.annotation_type {
                    buffer.putc(
                        line_offset + pos,
                        (code_offset + annotation.start_col.display).saturating_sub(left),
                        underline.bottom_right,
                        underline.style,
                    );
                }
                if let AnnotationType::MultilineEnd(_) = annotation.annotation_type {
                    if annotation.has_label() {
                        buffer.putc(
                            line_offset + pos,
                            (code_offset + annotation.start_col.display).saturating_sub(left),
                            underline.multiline_bottom_right_with_text,
                            underline.style,
                        );
                    }
                }
            }
            match annotation.annotation_type {
                AnnotationType::MultilineStart(depth) => {
                    buffer.putc(line_offset + pos, width_offset + depth - 1, underline.top_left, underline.style);
                    for p in line_offset + pos + 1..line_offset + line_len + 2 {
                        buffer.putc(p, width_offset + depth - 1, underline.multiline_vertical, underline.style);
                    }
                }
                AnnotationType::MultilineEnd(depth) => {
                    for p in line_offset..line_offset + pos {
                        buffer.putc(p, width_offset + depth - 1, underline.multiline_vertical, underline.style);
                    }
                    buffer.putc(line_offset + pos, width_offset + depth - 1, underline.bottom_left, underline.style);
                }
                _ => (),
            }
        }

        // Write the labels on the annotations that actually have a label.
        for &(pos, annotation) in &annotations_position {
            let style = if annotation.is_primary { Style::LabelPrimary } else { Style::LabelSecondary };
            let (pos, col) = if pos == 0 {
                let pre: usize = source_string.chars().take(annotation.end_col.file).skip(left).map(char_width).sum();
                if annotation.end_col.file == 0 {
                    (pos + 1, pre + 2)
                } else {
                    let pad = if annotation.end_col.file - annotation.start_col.file == 0 { 2 } else { 1 };
                    (pos + 1, pre + pad)
                }
            } else {
                let pre: usize = source_string.chars().take(annotation.start_col.file).skip(left).map(char_width).sum();
                (pos + 2, pre)
            };
            if let Some(ref label) = annotation.label {
                buffer.puts(line_offset + pos, code_offset + col, label, style);
            }
        }

        // Sort from biggest span to smallest span so that smaller spans are
        // represented in the output.
        annotations_position.sort_by_key(|(_, ann)| (Reverse(ann.len()), ann.is_primary));

        // Write the underlines.
        for &(pos, annotation) in &annotations_position {
            let uline = self.underline(annotation.is_primary);
            for p in annotation.start_col.display..annotation.end_col.display {
                buffer.putc(line_offset + 1, (code_offset + p).saturating_sub(left), uline.underline, uline.style);
            }

            if pos == 0
                && matches!(annotation.annotation_type, AnnotationType::MultilineStart(_) | AnnotationType::MultilineEnd(_))
            {
                buffer.putc(
                    line_offset + 1,
                    (code_offset + annotation.start_col.display).saturating_sub(left),
                    match annotation.annotation_type {
                        AnnotationType::MultilineStart(_) => uline.top_right_flat,
                        AnnotationType::MultilineEnd(_) => uline.multiline_end_same_line,
                        _ => unreachable!(),
                    },
                    uline.style,
                );
            } else if pos != 0
                && matches!(annotation.annotation_type, AnnotationType::MultilineStart(_) | AnnotationType::MultilineEnd(_))
            {
                buffer.putc(
                    line_offset + 1,
                    (code_offset + annotation.start_col.display).saturating_sub(left),
                    match annotation.annotation_type {
                        AnnotationType::MultilineStart(_) => uline.multiline_start_down,
                        AnnotationType::MultilineEnd(_) => uline.bottom_right,
                        _ => unreachable!(),
                    },
                    uline.style,
                );
            } else if pos != 0 && annotation.has_label() {
                buffer.putc(
                    line_offset + 1,
                    (code_offset + annotation.start_col.display).saturating_sub(left),
                    uline.label_start,
                    uline.style,
                );
            }
        }

        // We look for individual *long* spans, and we trim the *middle*.
        let overlap: Vec<bool> = {
            let mut overlap = vec![false; annotations_position.len()];
            for (i, (_, a)) in annotations_position.iter().enumerate() {
                for (j, (_, b)) in annotations_position.iter().enumerate() {
                    if i != j && overlaps(a, b, 0) {
                        overlap[i] = true;
                        overlap[j] = true;
                    }
                }
            }
            overlap
        };
        for (i, (_pos, annotation)) in annotations_position.iter().enumerate() {
            if overlap[i] {
                continue;
            }
            let AnnotationType::Singleline = annotation.annotation_type else {
                continue;
            };
            let width = annotation.end_col.display - annotation.start_col.display;
            if width > margin.column_width * 2 && width > 10 {
                let pad = max(margin.column_width / 3, 5);
                buffer.replace(
                    line_offset,
                    code_offset + annotation.start_col.file + pad,
                    code_offset + annotation.end_col.file - pad,
                    self.margin(),
                );
                buffer.replace(
                    line_offset + 1,
                    code_offset + annotation.start_col.file + pad,
                    code_offset + annotation.end_col.file - pad,
                    self.margin(),
                );
            }
        }

        annotations_position
            .iter()
            .filter_map(|&(_, annotation)| match annotation.annotation_type {
                AnnotationType::MultilineStart(p) | AnnotationType::MultilineEnd(p) => {
                    let style = if annotation.is_primary { Style::LabelPrimary } else { Style::LabelSecondary };
                    Some((p, style))
                }
                _ => None,
            })
            .collect()
    }
}

fn is_whitespace(c: char) -> bool {
    matches!(c, ' ' | '\t' | '\n' | '\r')
}

pub fn terminal_width() -> Option<usize> {
    #[repr(C)]
    struct Winsize {
        ws_row: u16,
        ws_col: u16,
        ws_xpixel: u16,
        ws_ypixel: u16,
    }
    extern "C" {
        fn ioctl(fd: i32, request: u64, ...) -> i32;
    }
    const TIOCGWINSZ: u64 = 0x5413;
    let mut ws = Winsize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
    // stderr
    let r = unsafe { ioctl(2, TIOCGWINSZ, &mut ws as *mut Winsize) };
    if r == 0 && ws.ws_col > 0 {
        Some(ws.ws_col as usize)
    } else {
        None
    }
}

