//! Lexer: converts source text into tokens, emitting diagnostics for invalid literals.

use crate::diag::{Diag, DiagCtxt, Level};
use crate::span::Span;
use crate::symbol::Symbol;
use crate::token::{BinOpToken, Delimiter, LitKind, Token, TokenKind};
use std::str::Chars;

const EOF_CHAR: char = '\0';

struct Cursor<'a> {
    chars: Chars<'a>,
    len_remaining: usize,
}

impl<'a> Cursor<'a> {
    fn new(src: &'a str) -> Self {
        Cursor { chars: src.chars(), len_remaining: src.len() }
    }
    fn first(&self) -> char {
        self.chars.clone().next().unwrap_or(EOF_CHAR)
    }
    fn second(&self) -> char {
        let mut c = self.chars.clone();
        c.next();
        c.next().unwrap_or(EOF_CHAR)
    }
    fn third(&self) -> char {
        let mut c = self.chars.clone();
        c.next();
        c.next();
        c.next().unwrap_or(EOF_CHAR)
    }
    fn is_eof(&self) -> bool {
        self.chars.as_str().is_empty()
    }
    fn pos_within_token(&self) -> u32 {
        (self.len_remaining - self.chars.as_str().len()) as u32
    }
    fn reset_pos_within_token(&mut self) {
        self.len_remaining = self.chars.as_str().len();
    }
    fn bump(&mut self) -> Option<char> {
        self.chars.next()
    }
    fn eat_while(&mut self, mut pred: impl FnMut(char) -> bool) {
        while pred(self.first()) && !self.is_eof() {
            self.bump();
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum RawKind {
    LineComment { doc: bool },
    BlockComment { doc: bool, terminated: bool },
    Whitespace,
    Ident,
    Literal(RawLit),
    Punct(TokenKind),
    Unknown,
    Eof,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum RawLit {
    Int { base: Base, empty_int: bool },
    Rational { base: Base, empty_exponent: bool, empty_fraction: bool, plus_in_exponent: bool },
    Str { terminated: bool, kind: StrKind },
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum StrKind {
    Str,
    Unicode,
    Hex,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Base {
    Binary,
    Octal,
    Decimal,
    Hexadecimal,
}

fn is_whitespace(c: char) -> bool {
    matches!(c, ' ' | '\t' | '\n' | '\r')
}

pub fn is_id_start(c: char) -> bool {
    c.is_ascii_alphabetic() || c == '_' || c == '$'
}

pub fn is_id_continue(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_' || c == '$'
}

impl<'a> Cursor<'a> {
    fn advance_token(&mut self) -> (RawKind, u32) {
        let Some(first) = self.bump() else {
            return (RawKind::Eof, 0);
        };
        let kind = match first {
            '/' => match self.first() {
                '/' => self.line_comment(),
                '*' => self.block_comment(),
                '=' => {
                    self.bump();
                    RawKind::Punct(TokenKind::BinOpEq(BinOpToken::Slash))
                }
                _ => RawKind::Punct(TokenKind::BinOp(BinOpToken::Slash)),
            },
            c if is_whitespace(c) => {
                self.eat_while(is_whitespace);
                RawKind::Whitespace
            }
            c if is_id_start(c) => {
                self.eat_while(is_id_continue);
                RawKind::Ident
            }
            c @ '0'..='9' => {
                let lit = self.number(c);
                RawKind::Literal(lit)
            }
            '.' if self.first().is_ascii_digit() => {
                // `.5`
                self.eat_decimal_digits();
                let (empty_exponent, plus_in_exponent) = self.maybe_exponent();
                RawKind::Literal(RawLit::Rational {
                    base: Base::Decimal,
                    empty_exponent,
                    empty_fraction: false,
                    plus_in_exponent,
                })
            }
            '"' | '\'' => {
                let terminated = self.quoted_string(first);
                RawKind::Literal(RawLit::Str { terminated, kind: StrKind::Str })
            }
            ';' => RawKind::Punct(TokenKind::Semi),
            ',' => RawKind::Punct(TokenKind::Comma),
            '.' => RawKind::Punct(TokenKind::Dot),
            '(' => RawKind::Punct(TokenKind::OpenDelim(Delimiter::Parenthesis)),
            ')' => RawKind::Punct(TokenKind::CloseDelim(Delimiter::Parenthesis)),
            '{' => RawKind::Punct(TokenKind::OpenDelim(Delimiter::Brace)),
            '}' => RawKind::Punct(TokenKind::CloseDelim(Delimiter::Brace)),
            '[' => RawKind::Punct(TokenKind::OpenDelim(Delimiter::Bracket)),
            ']' => RawKind::Punct(TokenKind::CloseDelim(Delimiter::Bracket)),
            '~' => RawKind::Punct(TokenKind::Tilde),
            '?' => RawKind::Punct(TokenKind::Question),
            ':' => {
                if self.first() == '=' {
                    self.bump();
                    RawKind::Punct(TokenKind::Walrus)
                } else {
                    RawKind::Punct(TokenKind::Colon)
                }
            }
            '=' => match self.first() {
                '=' => {
                    self.bump();
                    RawKind::Punct(TokenKind::EqEq)
                }
                '>' => {
                    self.bump();
                    RawKind::Punct(TokenKind::FatArrow)
                }
                _ => RawKind::Punct(TokenKind::Eq),
            },
            '!' => {
                if self.first() == '=' {
                    self.bump();
                    RawKind::Punct(TokenKind::Ne)
                } else {
                    RawKind::Punct(TokenKind::Not)
                }
            }
            '<' => match self.first() {
                '=' => {
                    self.bump();
                    RawKind::Punct(TokenKind::Le)
                }
                '<' => {
                    self.bump();
                    if self.first() == '=' {
                        self.bump();
                        RawKind::Punct(TokenKind::BinOpEq(BinOpToken::Shl))
                    } else {
                        RawKind::Punct(TokenKind::BinOp(BinOpToken::Shl))
                    }
                }
                _ => RawKind::Punct(TokenKind::Lt),
            },
            '>' => match self.first() {
                '=' => {
                    self.bump();
                    RawKind::Punct(TokenKind::Ge)
                }
                '>' => {
                    self.bump();
                    match self.first() {
                        '=' => {
                            self.bump();
                            RawKind::Punct(TokenKind::BinOpEq(BinOpToken::Shr))
                        }
                        '>' => {
                            self.bump();
                            if self.first() == '=' {
                                self.bump();
                                RawKind::Punct(TokenKind::BinOpEq(BinOpToken::Sar))
                            } else {
                                RawKind::Punct(TokenKind::BinOp(BinOpToken::Sar))
                            }
                        }
                        _ => RawKind::Punct(TokenKind::BinOp(BinOpToken::Shr)),
                    }
                }
                _ => RawKind::Punct(TokenKind::Gt),
            },
            '-' => match self.first() {
                '-' => {
                    self.bump();
                    RawKind::Punct(TokenKind::MinusMinus)
                }
                '>' => {
                    self.bump();
                    RawKind::Punct(TokenKind::Arrow)
                }
                '=' => {
                    self.bump();
                    RawKind::Punct(TokenKind::BinOpEq(BinOpToken::Minus))
                }
                _ => RawKind::Punct(TokenKind::BinOp(BinOpToken::Minus)),
            },
            '+' => match self.first() {
                '+' => {
                    self.bump();
                    RawKind::Punct(TokenKind::PlusPlus)
                }
                '=' => {
                    self.bump();
                    RawKind::Punct(TokenKind::BinOpEq(BinOpToken::Plus))
                }
                _ => RawKind::Punct(TokenKind::BinOp(BinOpToken::Plus)),
            },
            '&' => match self.first() {
                '&' => {
                    self.bump();
                    RawKind::Punct(TokenKind::AndAnd)
                }
                '=' => {
                    self.bump();
                    RawKind::Punct(TokenKind::BinOpEq(BinOpToken::And))
                }
                _ => RawKind::Punct(TokenKind::BinOp(BinOpToken::And)),
            },
            '|' => match self.first() {
                '|' => {
                    self.bump();
                    RawKind::Punct(TokenKind::OrOr)
                }
                '=' => {
                    self.bump();
                    RawKind::Punct(TokenKind::BinOpEq(BinOpToken::Or))
                }
                _ => RawKind::Punct(TokenKind::BinOp(BinOpToken::Or)),
            },
            '*' => match self.first() {
                '*' => {
                    self.bump();
                    RawKind::Punct(TokenKind::BinOp(BinOpToken::StarStar))
                }
                '=' => {
                    self.bump();
                    RawKind::Punct(TokenKind::BinOpEq(BinOpToken::Star))
                }
                _ => RawKind::Punct(TokenKind::BinOp(BinOpToken::Star)),
            },
            '^' => {
                if self.first() == '=' {
                    self.bump();
                    RawKind::Punct(TokenKind::BinOpEq(BinOpToken::Caret))
                } else {
                    RawKind::Punct(TokenKind::BinOp(BinOpToken::Caret))
                }
            }
            '%' => {
                if self.first() == '=' {
                    self.bump();
                    RawKind::Punct(TokenKind::BinOpEq(BinOpToken::Percent))
                } else {
                    RawKind::Punct(TokenKind::BinOp(BinOpToken::Percent))
                }
            }
            _ => RawKind::Unknown,
        };
        let len = self.pos_within_token();
        self.reset_pos_within_token();
        (kind, len)
    }

    fn line_comment(&mut self) -> RawKind {
        self.bump(); // second '/'
        let doc = self.first() == '/' && self.second() != '/';
        self.eat_while(|c| c != '\n');
        RawKind::LineComment { doc }
    }

    fn block_comment(&mut self) -> RawKind {
        self.bump(); // '*'
        let doc = self.first() == '*' && !matches!(self.second(), '*' | '/');
        let mut terminated = false;
        while let Some(c) = self.bump() {
            if c == '*' && self.first() == '/' {
                self.bump();
                terminated = true;
                break;
            }
        }
        RawKind::BlockComment { doc, terminated }
    }

    fn number(&mut self, first_digit: char) -> RawLit {
        let mut base = Base::Decimal;
        if first_digit == '0' {
            match self.first() {
                'b' => {
                    base = Base::Binary;
                    self.bump();
                    if !self.eat_decimal_digits() {
                        return RawLit::Int { base, empty_int: true };
                    }
                }
                'o' => {
                    base = Base::Octal;
                    self.bump();
                    if !self.eat_decimal_digits() {
                        return RawLit::Int { base, empty_int: true };
                    }
                }
                'x' => {
                    base = Base::Hexadecimal;
                    self.bump();
                    if !self.eat_hexadecimal_digits() {
                        return RawLit::Int { base, empty_int: true };
                    }
                }
                '0'..='9' | '_' => {
                    self.eat_decimal_digits();
                }
                '.' | 'e' | 'E' => {}
                _ => return RawLit::Int { base, empty_int: false },
            }
        } else {
            self.eat_decimal_digits();
        }

        match self.first() {
            '.' if !is_id_start(self.second()) => {
                self.bump();
                let mut empty_fraction = true;
                if self.first().is_ascii_digit() || self.first() == '_' {
                    empty_fraction = !self.eat_decimal_digits();
                }
                let (empty_exponent, plus_in_exponent) = self.maybe_exponent();
                RawLit::Rational { base, empty_exponent, empty_fraction, plus_in_exponent }
            }
            'e' | 'E' => {
                let (empty_exponent, plus_in_exponent) = self.maybe_exponent();
                RawLit::Rational { base, empty_exponent, empty_fraction: false, plus_in_exponent }
            }
            _ => RawLit::Int { base, empty_int: false },
        }
    }

    /// Returns (empty_exponent, plus_in_exponent). Only consumes if next is `e`/`E`.
    fn maybe_exponent(&mut self) -> (bool, bool) {
        if matches!(self.first(), 'e' | 'E') {
            self.bump();
            let mut plus = false;
            if self.first() == '-' {
                self.bump();
            } else if self.first() == '+' {
                self.bump();
                plus = true;
            }
            let has_digits = self.eat_decimal_digits();
            (!has_digits, plus)
        } else {
            (false, false)
        }
    }

    fn eat_decimal_digits(&mut self) -> bool {
        let mut has_digits = false;
        loop {
            match self.first() {
                '_' => {
                    self.bump();
                }
                '0'..='9' => {
                    has_digits = true;
                    self.bump();
                }
                _ => break,
            }
        }
        has_digits
    }

    fn eat_hexadecimal_digits(&mut self) -> bool {
        let mut has_digits = false;
        loop {
            match self.first() {
                '_' => {
                    self.bump();
                }
                '0'..='9' | 'a'..='f' | 'A'..='F' => {
                    has_digits = true;
                    self.bump();
                }
                _ => break,
            }
        }
        has_digits
    }

    fn quoted_string(&mut self, quote: char) -> bool {
        while let Some(c) = self.bump() {
            match c {
                c if c == quote => return true,
                '\\' if self.first() == '\\' || self.first() == quote || self.first() == '\n' => {
                    self.bump();
                }
                '\\' => {
                    // other escapes: skip the escaped char too (so `\"` handled above)
                }
                _ => {}
            }
        }
        false
    }
}

pub struct Lexer<'a> {
    dcx: &'a DiagCtxt,
    src: &'a str,
    start_pos: u32,
    pos: u32,
    cursor: Cursor<'a>,
}

impl<'a> Lexer<'a> {
    pub fn new(dcx: &'a DiagCtxt, src: &'a str, start_pos: u32) -> Self {
        Lexer { dcx, src, start_pos, pos: start_pos, cursor: Cursor::new(src) }
    }

    pub fn into_tokens(mut self) -> Vec<Token> {
        let mut tokens = Vec::new();
        loop {
            let tok = self.next_token();
            let eof = tok.kind == TokenKind::Eof;
            tokens.push(tok);
            if eof {
                break;
            }
        }
        tokens
    }

    fn str_from_to(&self, start: u32, end: u32) -> &'a str {
        &self.src[(start - self.start_pos) as usize..(end - self.start_pos) as usize]
    }

    fn new_span(&self, lo: u32, hi: u32) -> Span {
        Span::new(lo, hi)
    }

    fn next_token(&mut self) -> Token {
        loop {
            let start = self.pos;
            let (kind, len) = self.cursor.advance_token();
            self.pos += len;
            let end = self.pos;
            let kind = match kind {
                RawKind::Whitespace => continue,
                RawKind::LineComment { doc } => {
                    if doc {
                        let text = self.str_from_to(start, end);
                        TokenKind::DocComment(false, Symbol::intern(text))
                    } else {
                        continue;
                    }
                }
                RawKind::BlockComment { doc, terminated } => {
                    if !terminated {
                        self.dcx.emit(Diag::new(Level::Error, "unterminated block comment").span(self.new_span(start, end)));
                    }
                    if doc {
                        let text = self.str_from_to(start, end);
                        TokenKind::DocComment(true, Symbol::intern(text))
                    } else {
                        continue;
                    }
                }
                RawKind::Ident => {
                    let text = self.str_from_to(start, end);
                    let sym = Symbol::intern(text);
                    // `hex"..."` and `unicode"..."` prefixed strings
                    if (sym == crate::symbol::kw::Hex || sym == crate::symbol::kw::Unicode)
                        && matches!(self.cursor.first(), '"' | '\'')
                    {
                        let quote = self.cursor.bump().unwrap();
                        let terminated = self.cursor.quoted_string(quote);
                        let len = self.cursor.pos_within_token();
                        self.cursor.reset_pos_within_token();
                        self.pos += len;
                        let end = self.pos;
                        let kind = if sym == crate::symbol::kw::Hex { StrKind::Hex } else { StrKind::Unicode };
                        self.cook_string(start, end, terminated, kind, (end - start) as usize - len as usize)
                    } else {
                        TokenKind::Ident(sym)
                    }
                }
                RawKind::Literal(lit) => match lit {
                    RawLit::Str { terminated, kind } => self.cook_string(start, end, terminated, kind, 0),
                    RawLit::Int { base, empty_int } => self.cook_int(start, end, base, empty_int),
                    RawLit::Rational { base, empty_exponent, empty_fraction, plus_in_exponent } => {
                        self.cook_rational(start, end, base, empty_exponent, empty_fraction, plus_in_exponent)
                    }
                },
                RawKind::Punct(k) => k,
                RawKind::Unknown => {
                    let c = self.str_from_to(start, end).chars().next().unwrap();
                    let escaped = if c == '\\' { "\\".to_string() } else { c.escape_default().to_string() };
                    self.dcx.emit(
                        Diag::new(Level::Error, format!("unknown start of token: {escaped}")).span(self.new_span(start, end)),
                    );
                    continue;
                }
                RawKind::Eof => TokenKind::Eof,
            };
            return Token::new(kind, self.new_span(start, end));
        }
    }

    fn cook_int(&mut self, start: u32, end: u32, base: Base, empty_int: bool) -> TokenKind {
        let span = self.new_span(start, end);
        let text = self.str_from_to(start, end);
        if empty_int {
            self.dcx.emit(Diag::new(Level::Error, "no valid digits found for number").span(span));
            return TokenKind::Literal(LitKind::Err, Symbol::intern(text));
        }
        match base {
            Base::Binary | Base::Octal => {
                let name = if base == Base::Binary { "binary" } else { "octal" };
                // Point at the digits after the prefix.
                let digits_span = self.new_span(start + 2, end);
                self.dcx.emit(
                    Diag::new(Level::Error, format!("integers in base {name} are not supported")).span(digits_span),
                );
                return TokenKind::Literal(LitKind::Err, Symbol::intern(text));
            }
            _ => {}
        }
        if base == Base::Decimal {
            if let Some(err) = self.check_underscores(text, span, false) {
                return err;
            }
            // Leading zeros check
            let digits: Vec<u8> = text.bytes().filter(|b| *b != b'_').collect();
            if digits.len() > 1 && digits[0] == b'0' {
                self.dcx.emit(Diag::new(Level::Error, "leading zeros are not allowed in integers").span(span));
                return TokenKind::Literal(LitKind::Err, Symbol::intern(text));
            }
        } else if let Some(err) = self.check_underscores(text, span, true) {
            return err;
        }
        TokenKind::Literal(LitKind::Integer, Symbol::intern(text))
    }

    /// Checks underscore placement. Returns an error token if invalid.
    fn check_underscores(&mut self, text: &str, span: Span, hex: bool) -> Option<TokenKind> {
        let body = if hex { &text[2..] } else { text };
        let bytes = body.as_bytes();
        let mut help: Option<&str> = None;
        if bytes.last() == Some(&b'_') {
            help = Some("remove trailing underscores");
        } else {
            let mut prev_underscore = false;
            for &b in bytes {
                if b == b'_' {
                    if prev_underscore {
                        help = Some("only 1 consecutive underscore `_` is allowed between digits");
                        break;
                    }
                    prev_underscore = true;
                } else {
                    prev_underscore = false;
                }
            }
        }
        if let Some(help) = help {
            self.dcx.emit(Diag::new(Level::Error, "invalid use of underscores in number literal").span(span).help(help));
            return Some(TokenKind::Literal(LitKind::Err, Symbol::intern(text)));
        }
        None
    }

    fn cook_rational(
        &mut self,
        start: u32,
        end: u32,
        base: Base,
        empty_exponent: bool,
        empty_fraction: bool,
        plus_in_exponent: bool,
    ) -> TokenKind {
        let span = self.new_span(start, end);
        let text = self.str_from_to(start, end);
        let sym = Symbol::intern(text);
        if base == Base::Hexadecimal {
            self.dcx.emit(Diag::new(Level::Error, "hexadecimal rational numbers are not supported").span(span));
            return TokenKind::Literal(LitKind::Err, sym);
        }
        if base != Base::Decimal {
            let name = if base == Base::Binary { "binary" } else { "octal" };
            self.dcx.emit(Diag::new(Level::Error, format!("integers in base {name} are not supported")).span(span));
            return TokenKind::Literal(LitKind::Err, sym);
        }
        if plus_in_exponent {
            self.dcx.emit(Diag::new(Level::Error, "`+` is not allowed in the exponent").span(span));
            return TokenKind::Literal(LitKind::Err, sym);
        }
        if empty_exponent {
            self.dcx.emit(Diag::new(Level::Error, "expected at least one digit in exponent").span(span));
            return TokenKind::Literal(LitKind::Err, sym);
        }
        if empty_fraction {
            self.dcx.emit(Diag::new(Level::Error, "empty rational").span(span));
            return TokenKind::Literal(LitKind::Err, sym);
        }
        // Underscore checks.
        let bytes = text.as_bytes();
        let mut help: Option<&str> = None;
        // Split into int part, fraction part, exponent part.
        let (mantissa, exponent) = match text.find(['e', 'E']) {
            Some(i) => (&text[..i], Some(&text[i + 1..])),
            None => (text, None),
        };
        let (int_part, frac_part) = match mantissa.find('.') {
            Some(i) => (&mantissa[..i], Some(&mantissa[i + 1..])),
            None => (mantissa, None),
        };
        if let Some(frac) = frac_part {
            if int_part.ends_with('_') || frac.starts_with('_') {
                help = Some("remove underscores in front of the fraction part");
            }
        }
        if help.is_none() {
            if let Some(exp) = exponent {
                let exp = exp.strip_prefix('-').unwrap_or(exp);
                if mantissa.ends_with('_') || exp.starts_with('_') {
                    help = Some("remove underscores in front of the exponent");
                }
            }
        }
        if help.is_none() && bytes.last() == Some(&b'_') {
            help = Some("remove trailing underscores");
        }
        if help.is_none() {
            let mut prev = false;
            for &b in bytes {
                if b == b'_' {
                    if prev {
                        help = Some("only 1 consecutive underscore `_` is allowed between digits");
                        break;
                    }
                    prev = true;
                } else {
                    prev = false;
                }
            }
        }
        if let Some(help) = help {
            self.dcx.emit(Diag::new(Level::Error, "invalid use of underscores in number literal").span(span).help(help));
            return TokenKind::Literal(LitKind::Err, sym);
        }
        // Leading zeros in the integer part.
        let digits: Vec<u8> = int_part.bytes().filter(|b| *b != b'_').collect();
        if digits.len() > 1 && digits[0] == b'0' {
            self.dcx.emit(Diag::new(Level::Error, "leading zeros are not allowed in integers").span(span));
            return TokenKind::Literal(LitKind::Err, sym);
        }
        TokenKind::Literal(LitKind::Rational, sym)
    }

    /// `prefix_len` is the length of the `hex`/`unicode` prefix.
    fn cook_string(&mut self, start: u32, end: u32, terminated: bool, kind: StrKind, prefix_len: usize) -> TokenKind {
        let span = self.new_span(start, end);
        let text = self.str_from_to(start, end);
        let sym = Symbol::intern(text);
        if !terminated {
            self.dcx.emit(Diag::new(Level::Error, "unterminated string").span(span));
            return TokenKind::Literal(LitKind::Err, sym);
        }
        // content between the quotes
        let content_start = start + prefix_len as u32 + 1;
        let content_end = end - 1;
        let content = self.str_from_to(content_start, content_end);
        let mut ok = true;
        match kind {
            StrKind::Hex => {
                ok = self.validate_hex_str(content, content_start);
            }
            StrKind::Str | StrKind::Unicode => {
                ok = self.validate_str(content, content_start, kind == StrKind::Unicode);
            }
        }
        if !ok {
            return TokenKind::Literal(LitKind::Err, sym);
        }
        let lit_kind = match kind {
            StrKind::Str => LitKind::Str,
            StrKind::Unicode => LitKind::UnicodeStr,
            StrKind::Hex => LitKind::HexStr,
        };
        TokenKind::Literal(lit_kind, sym)
    }

    fn validate_hex_str(&mut self, content: &str, content_start: u32) -> bool {
        let bytes = content.as_bytes();
        let num_digits = bytes.iter().filter(|b| b.is_ascii_hexdigit()).count();
        if num_digits % 2 != 0 {
            let span = self.new_span(content_start, content_start + content.len() as u32);
            self.dcx.emit(Diag::new(Level::Error, "odd number of hex nibbles").span(span));
            return false;
        }
        let mut ok = true;
        let mut digits_so_far = 0usize;
        let mut prev_underscore = false;
        let mut i = 0;
        let chars: Vec<(usize, char)> = content.char_indices().collect();
        while i < chars.len() {
            let (off, c) = chars[i];
            let clen = c.len_utf8();
            let cspan = self.new_span(content_start + off as u32, content_start + (off + clen) as u32);
            if c.is_ascii_hexdigit() {
                digits_so_far += 1;
                prev_underscore = false;
            } else if c == '_' {
                let is_last = i + 1 == chars.len();
                if digits_so_far == 0 || digits_so_far % 2 != 0 || prev_underscore || is_last {
                    self.dcx.emit(Diag::new(Level::Error, "invalid underscore in hex literal").span(cspan));
                    return false;
                }
                prev_underscore = true;
            } else {
                self.dcx.emit(Diag::new(Level::Error, "invalid hex digit").span(cspan));
                ok = false;
                prev_underscore = false;
            }
            i += 1;
        }
        ok
    }

    fn validate_str(&mut self, content: &str, content_start: u32, unicode: bool) -> bool {
        let mut ok = true;
        let mut chars = content.char_indices().peekable();
        let span_at = |off: usize, len: usize| Span::new(content_start + off as u32, content_start + (off + len) as u32);
        while let Some((off, c)) = chars.next() {
            match c {
                '\\' => {
                    let Some((eoff, e)) = chars.next() else {
                        // Trailing backslash before closing quote can't happen (would be unterminated).
                        break;
                    };
                    match e {
                        '\\' | '\'' | '"' | 'n' | 'r' | 't' | '\n' => {}
                        'x' | 'u' => {
                            let n = if e == 'x' { 2 } else { 4 };
                            let mut consumed_end = eoff + 1;
                            let mut i = 0;
                            while i < n {
                                match chars.peek().copied() {
                                    None => {
                                        let msg = if e == 'x' {
                                            "hex escape must be followed by 2 hex digits"
                                        } else {
                                            "unicode escape must be followed by 4 hex digits"
                                        };
                                        self.dcx.emit(
                                            Diag::new(Level::Error, msg).span(span_at(off, consumed_end - off)),
                                        );
                                        ok = false;
                                        break;
                                    }
                                    Some((doff, d)) => {
                                        chars.next();
                                        consumed_end = doff + d.len_utf8();
                                        if !d.is_ascii_hexdigit() {
                                            let msg = if e == 'x' {
                                                "invalid character in hex escape"
                                            } else {
                                                "invalid character in unicode escape"
                                            };
                                            self.dcx.emit(Diag::new(Level::Error, msg).span(span_at(doff, d.len_utf8())));
                                            ok = false;
                                            break;
                                        }
                                    }
                                }
                                i += 1;
                            }
                        }
                        _ => {
                            self.dcx.emit(
                                Diag::new(Level::Error, "unknown character escape").span(span_at(eoff, e.len_utf8())),
                            );
                            ok = false;
                        }
                    }
                }
                '\n' => {
                    self.dcx.emit(Diag::new(Level::Error, "unescaped newline").span(span_at(off, 1)));
                    ok = false;
                }
                c if !c.is_ascii() && !unicode => {
                    self.dcx.emit(
                        Diag::new(
                            Level::Error,
                            "unicode characters are not allowed in string literals; use a `unicode\"...\"` literal instead",
                        )
                        .span(span_at(off, c.len_utf8())),
                    );
                    ok = false;
                }
                _ => {}
            }
        }
        ok
    }
}
EOF
