    FixedBytes(u8),
    Fixed(u16, u16),
    UFixed(u16, u16),
}

impl ElementaryType {
    pub fn to_abi_str(self) -> String {
        match self {
            ElementaryType::Address(_) => "address".into(),
            ElementaryType::Bool => "bool".into(),
            ElementaryType::String => "string".into(),
            ElementaryType::Bytes => "bytes".into(),
            ElementaryType::Int(n) => format!("int{}", if n == 0 { 256 } else { n }),
            ElementaryType::UInt(n) => format!("uint{}", if n == 0 { 256 } else { n }),
            ElementaryType::FixedBytes(n) => format!("bytes{n}"),
            ElementaryType::Fixed(m, n) => format!("fixed{}x{}", if m == 0 { 256 } else { m }, n),
            ElementaryType::UFixed(m, n) => format!("ufixed{}x{}", if m == 0 { 256 } else { m }, n),
        }
    }
