    DeclSingle(VariableDefinition),
    DeclMulti(Vec<Option<VariableDefinition>>, Box<Expr>),
    Block(Block),
    Break,
    Continue,
    DoWhile(Box<Stmt>, Box<Expr>),
    Emit(Path, CallArgs),
    Expr(Box<Expr>),
    For { init: Option<Box<Stmt>>, cond: Option<Box<Expr>>, next: Option<Box<Expr>>, body: Box<Stmt> },
    If(Box<Expr>, Box<Stmt>, Option<Box<Stmt>>),
    Return(Option<Box<Expr>>),
    Revert(Path, CallArgs),
    Try(Box<StmtTry>),
    UncheckedBlock(Block),
    While(Box<Expr>, Box<Stmt>),
    Placeholder,
}

#[derive(Debug)]
pub struct StmtAssembly {
    pub dialect: Option<StrLit>,
    pub flags: Vec<StrLit>,
    pub block: crate::yul::Block,
}

#[derive(Debug)]
pub struct StmtTry {
    pub expr: Box<Expr>,
    pub returns: Option<ParameterList>,
    pub block: Block,
    pub catch: Vec<CatchClause>,
}

#[derive(Debug)]
pub struct CatchClause {
    pub name: Option<Ident>,
    pub args: ParameterList,
    pub block: Block,
}

// ---- Expressions ----

#[derive(Debug)]
pub struct Expr {
    pub span: Span,
    pub kind: ExprKind,
}

#[derive(Debug)]
pub enum ExprKind {
    Array(Vec<Box<Expr>>),
    Assign(Box<Expr>, Option<BinOpKind>, Box<Expr>),
    Binary(Box<Expr>, Spanned<BinOpKind>, Box<Expr>),
    Call(Box<Expr>, CallArgs),
    CallOptions(Box<Expr>, Vec<NamedArg>),
    Delete(Box<Expr>),
    Ident(Ident),
    Index(Box<Expr>, Option<Box<Expr>>),
    Slice(Box<Expr>, Option<Box<Expr>>, Option<Box<Expr>>),
    Lit(Box<Lit>, Option<Spanned<SubDenomination>>),
    Member(Box<Expr>, Ident),
    New(Type),
    Payable(CallArgs),
    Ternary(Box<Expr>, Box<Expr>, Box<Expr>),
    Tuple(Vec<Option<Box<Expr>>>),
    TypeCall(Type),
    Type(Type),
    Unary(Spanned<UnOpKind>, Box<Expr>),
}

#[derive(Debug)]
pub struct NamedArg {
    pub name: Ident,
    pub value: Box<Expr>,
}

#[derive(Debug)]
pub struct CallArgs {
    pub span: Span,
    pub kind: CallArgsKind,
}

impl CallArgs {
    pub fn empty(span: Span) -> Self {
        CallArgs { span, kind: CallArgsKind::Unnamed(vec![]) }
    }
    pub fn len(&self) -> usize {
        match &self.kind {
            CallArgsKind::Unnamed(v) => v.len(),
            CallArgsKind::Named(v) => v.len(),
        }
    }
    pub fn exprs(&self) -> Vec<&Expr> {
        match &self.kind {
            CallArgsKind::Unnamed(v) => v.iter().map(|e| &**e).collect(),
            CallArgsKind::Named(v) => v.iter().map(|a| &*a.value).collect(),
        }
    }
}

#[derive(Debug)]
pub enum CallArgsKind {
    Unnamed(Vec<Box<Expr>>),
    Named(Vec<NamedArg>),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum UnOpKind {
    PreInc,
    PreDec,
    Not,
    Neg,
    BitNot,
    PostInc,
    PostDec,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BinOpKind {
    Lt,
    Le,
    Gt,
    Ge,
    Eq,
    Ne,
    Or,
    And,
    Shr,
    Shl,
    Sar,
    BitAnd,
    BitOr,
    BitXor,
    Add,
    Sub,
    Pow,
    Mul,
    Div,
    Rem,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SubDenomination {
    Wei,
    Gwei,
    Ether,
    Seconds,
    Minutes,
    Hours,
    Days,
    Weeks,
    Years,
}

#[derive(Debug, Clone)]
pub struct Lit {
    pub span: Span,
    pub symbol: Symbol,
    pub kind: LitKind,
}

#[derive(Debug, Clone)]
pub enum LitKind {
    Str(StrKind, Vec<u8>),
    Number(String),
    Rational(String),
    Address,
    Bool(bool),
    Err,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StrKind {
    Str,
    Unicode,
    Hex,
}

impl From<TokenLitKind> for StrKind {
    fn from(k: TokenLitKind) -> Self {
        match k {
            TokenLitKind::HexStr => StrKind::Hex,
            TokenLitKind::UnicodeStr => StrKind::Unicode,
            _ => StrKind::Str,
        }
    }
}
