/// Marker for an emitted (fatal) parse error.
#[derive(Debug, Clone, Copy)]
pub struct PErr;

pub type PResult<T> = Result<T, PErr>;

#[derive(Clone, PartialEq, Eq, Debug)]
pub enum ExpectedToken {
    Token(TokenKind),
    Keyword(Symbol),
    Ident,
    Literal,
    ElementaryType,
    Path,
    StrLit,
    Operator,
    VersionNumber,
}

impl fmt::Display for ExpectedToken {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ExpectedToken::Token(t) => write!(f, "`{t}`"),
            ExpectedToken::Keyword(k) => write!(f, "`{k}`"),
            ExpectedToken::Ident => f.write_str("identifier"),
            ExpectedToken::Literal => f.write_str("literal"),
            ExpectedToken::ElementaryType => f.write_str("elementary type name"),
            ExpectedToken::Path => f.write_str("path"),
            ExpectedToken::StrLit => f.write_str("string literal"),
            ExpectedToken::Operator => f.write_str("operator"),
            ExpectedToken::VersionNumber => f.write_str("version number"),
        }
    }
}

pub struct Parser<'a> {
    pub dcx: &'a DiagCtxt,
    tokens: Vec<Token>,
    idx: usize,
    pub token: Token,
    pub prev_token: Token,
    pub expected_tokens: Vec<ExpectedToken>,
    pub docs: Vec<DocComment>,
    pub in_contract: Option<ContractKind>,
    pub in_yul: bool,
    pub last_unexpected_token_span: Option<Span>,
    pub parse_yul_file: bool,
}

impl<'a> Parser<'a> {
    pub fn new(dcx: &'a DiagCtxt, mut tokens: Vec<Token>) -> Self {
        // EOF token span: span of the last real token.
        let n = tokens.len();
        if n >= 2 {
            let last = tokens[n - 2].span;
            tokens[n - 1].span = last;
        }
        let mut p = Parser {
            dcx,
            tokens,
            idx: 0,
            token: Token::DUMMY,
            prev_token: Token::DUMMY,
            expected_tokens: Vec::new(),
            docs: Vec::new(),
            in_contract: None,
            in_yul: false,
            last_unexpected_token_span: None,
            parse_yul_file: false,
        };
        p.token = p.next_raw_token();
        p
    }

    /// Returns the next non-doc-comment token, accumulating doc comments.
    fn next_raw_token(&mut self) -> Token {
        loop {
            let tok = if self.idx < self.tokens.len() {
                let t = self.tokens[self.idx];
                self.idx += 1;
                t
            } else {
                *self.tokens.last().unwrap()
            };
            if let TokenKind::DocComment(is_block, symbol) = tok.kind {
                self.docs.push(DocComment { is_block, span: tok.span, symbol });
                continue;
            }
            return tok;
        }
    }

    pub fn bump(&mut self) {
        let next = self.next_raw_token();
        self.prev_token = self.token;
        self.token = next;
        self.expected_tokens.clear();
    }

    /// Looks ahead `n` tokens (skipping doc comments). `look_ahead(0)` is the current token.
    pub fn look_ahead(&self, n: usize) -> Token {
        if n == 0 {
            return self.token;
        }
        let mut i = self.idx;
        let mut remaining = n;
        loop {
            if i >= self.tokens.len() {
                return *self.tokens.last().unwrap();
            }
            let t = self.tokens[i];
            i += 1;
            if matches!(t.kind, TokenKind::DocComment(..)) {
                continue;
            }
            remaining -= 1;
            if remaining == 0 {
                return t;
            }
        }
    }

    pub fn parse_doc_comments(&mut self) -> DocComments {
        DocComments(std::mem::take(&mut self.docs))
    }

    // ---- checks ----

    pub fn check(&mut self, tok: TokenKind) -> bool {
        let is = self.token.kind == tok;
        if !is {
            self.expected_tokens.push(ExpectedToken::Token(tok));
        }
        is
    }

    pub fn check_noexpect(&self, tok: TokenKind) -> bool {
        self.token.kind == tok
    }

    pub fn eat(&mut self, tok: TokenKind) -> bool {
        let is = self.check(tok);
        if is {
            self.bump();
        }
        is
    }

    pub fn eat_noexpect(&mut self, tok: TokenKind) -> bool {
        let is = self.token.kind == tok;
        if is {
            self.bump();
        }
        is
    }

    pub fn check_keyword(&mut self, kw: Symbol) -> bool {
        let is = self.token.is_keyword(kw);
        if !is {
            self.expected_tokens.push(ExpectedToken::Keyword(kw));
        }
        is
    }

    pub fn eat_keyword(&mut self, kw: Symbol) -> bool {
        let is = self.check_keyword(kw);
        if is {
            self.bump();
        }
        is
    }

    pub fn eat_keyword_noexpect(&mut self, kw: Symbol) -> bool {
        let is = self.token.is_keyword(kw);
        if is {
            self.bump();
        }
        is
    }

    pub fn check_ident(&mut self) -> bool {
        let is = self.token.is_non_reserved_ident();
        if !is {
            self.expected_tokens.push(ExpectedToken::Ident);
        }
        is
    }

    pub fn check_literal(&mut self) -> bool {
        let is = self.token.is_literal();
        if !is {
            self.expected_tokens.push(ExpectedToken::Literal);
        }
        is
    }

    pub fn check_elementary_type(&mut self) -> bool {
        let is = self.token.is_elementary_type();
        if !is {
            self.expected_tokens.push(ExpectedToken::ElementaryType);
        }
        is
    }

    pub fn check_path(&mut self) -> bool {
        let is = self.token.is_non_reserved_ident();
        if !is {
            self.expected_tokens.push(ExpectedToken::Path);
        }
        is
    }

    pub fn check_str_lit(&mut self) -> bool {
        let is = matches!(self.token.kind, TokenKind::Literal(crate::token::LitKind::Str, _));
        if !is {
            self.expected_tokens.push(ExpectedToken::StrLit);
        }
        is
    }

    pub fn expect(&mut self, tok: TokenKind) -> PResult<()> {
        if self.expected_tokens.is_empty() {
            if self.token.kind == tok {
                self.bump();
                Ok(())
            } else {
                Err(self.unexpected_try_recover(tok))
            }
        } else {
            self.expect_one_of(&[tok], &[])
        }
    }

    pub fn expect_keyword(&mut self, kw: Symbol) -> PResult<()> {
        if self.eat_keyword(kw) {
            Ok(())
        } else {
            Err(self.expected_one_of_not_found(&[], &[]))
        }
    }

    pub fn expect_one_of(&mut self, edible: &[TokenKind], inedible: &[TokenKind]) -> PResult<()> {
        if edible.contains(&self.token.kind) {
            self.bump();
            Ok(())
        } else if inedible.contains(&self.token.kind) {
            Ok(())
        } else {
            Err(self.expected_one_of_not_found(edible, inedible))
        }
    }

    fn unexpected_try_recover(&mut self, tok: TokenKind) -> PErr {
        let token_str = format!("{tok}");
        let this_token_str = self.token.full_description();
        let msg = format!("expected `{token_str}`, found {this_token_str}");
        let (prev_sp, sp) = if self.token.is_eof() {
            (self.prev_token.span, self.token.span)
        } else {
            (self.prev_token.span.shrink_to_hi(), self.token.span)
        };
        let mut err = Diag::new(Level::Error, msg).span(sp);
        let label = format!("expected `{token_str}`");
        let sp2 = if self.token.is_eof() { self.prev_token.span } else { prev_sp };
        if self.prev_token.span.is_dummy() || !self.dcx.source_map.is_multiline(Span::new(sp2.lo.min(sp.lo), sp2.hi.max(sp.lo))) {
            err = err.span_label(sp, label);
        } else {
            err = err.span_label(sp2, label);
            err = err.span_label(sp, "unexpected token");
        }
        self.dcx.emit(err);
        PErr
    }

    pub fn expected_one_of_not_found(&mut self, edible: &[TokenKind], inedible: &[TokenKind]) -> PErr {
        let mut expected: Vec<ExpectedToken> = edible
            .iter()
            .chain(inedible)
            .map(|t| ExpectedToken::Token(*t))
            .chain(self.expected_tokens.iter().cloned())
            .collect();
        expected.sort_by_cached_key(|x| x.to_string());
        expected.dedup();
        let expect = tokens_to_string(&expected);
        let actual = self.token.full_description();
        let (msg_exp, (label_sp, label_exp)) = if expected.len() > 1 {
            let fmt = format!("expected one of {expect}, found {actual}");
            let short_expect = if expected.len() > 6 { format!("{} possible tokens", expected.len()) } else { expect };
            (fmt, (self.prev_token.span.shrink_to_hi(), format!("expected one of {short_expect}")))
        } else if expected.is_empty() {
            (format!("unexpected token: {actual}"), (self.prev_token.span, "unexpected token after this".to_string()))
        } else {
            (format!("expected {expect}, found {actual}"), (self.prev_token.span.shrink_to_hi(), format!("expected {expect}")))
        };
        self.last_unexpected_token_span = Some(self.token.span);
        let mut err = Diag::new(Level::Error, msg_exp).span(self.token.span);
        let sp = if self.token.is_eof() { self.prev_token.span } else { label_sp };
        let between = Span::new(sp.lo.min(self.token.span.lo), sp.hi.max(self.token.span.hi));
        if self.prev_token.span.is_dummy() || !self.dcx.source_map.is_multiline(between) {
            err = err.span_label(self.token.span, label_exp);
        } else {
            err = err.span_label(sp, label_exp);
            err = err.span_label(self.token.span, "unexpected token");
        }
        self.dcx.emit(err);
        PErr
    }

    /// Emits "expected identifier, found X".
    pub fn expected_ident_found_err(&mut self) -> PErr {
        let msg = format!("expected identifier, found {}", self.token.full_description());
        self.dcx.emit(Diag::new(Level::Error, msg).span(self.token.span));
        PErr
    }

    /// Parses an identifier. Recovers on keywords by emitting an error and using the keyword.
    pub fn parse_ident(&mut self) -> PResult<Ident> {
        self.parse_ident_common(true)
    }

    pub fn parse_ident_any(&mut self) -> PResult<Ident> {
        self.parse_ident_common(false)
    }

    fn parse_ident_common(&mut self, recover: bool) -> PResult<Ident> {
        match self.token.kind {
            TokenKind::Ident(sym) => {
                if sym.is_used_keyword() {
                    if recover {
                        let _ = self.expected_ident_found_err();
                        let ident = Ident::new(sym, self.token.span);
                        self.bump();
                        return Ok(ident);
                    }
                    return Err(self.expected_ident_found_err());
                }
                let ident = Ident::new(sym, self.token.span);
                self.bump();
                Ok(ident)
            }
            _ => Err(self.expected_ident_found_err()),
        }
    }

    pub fn parse_ident_opt(&mut self) -> PResult<Option<Ident>> {
        if self.check_ident() {
            Ok(Some(self.parse_ident()?))
        } else {
            Ok(None)
        }
    }

    /// Parses a `.`-separated path of identifiers.
    pub fn parse_path(&mut self) -> PResult<Path> {
        let first = self.parse_ident()?;
        self.parse_path_with(first)
    }

    pub fn parse_path_with(&mut self, first: Ident) -> PResult<Path> {
        let mut segments = vec![first];
        while self.eat(TokenKind::Dot) {
            segments.push(self.parse_ident()?);
        }
        Ok(Path { segments })
    }

    /// Parses a path where the first segment may be any identifier (including keywords like `this`).
    pub fn parse_path_any(&mut self) -> PResult<Path> {
        let first = self.parse_ident_any()?;
        self.parse_path_with(first)
    }

    // ---- sequences ----

    /// Parses a comma-separated sequence delimited by `open`/`close`. Trailing commas are not
    /// allowed (an error is emitted but parsing continues).
    pub fn parse_delim_comma_seq<T>(
        &mut self,
        delim: Delimiter,
        allow_empty: bool,
        mut f: impl FnMut(&mut Self) -> PResult<T>,
    ) -> PResult<(Vec<T>, Span)> {
        let lo = self.token.span;
        self.expect(TokenKind::OpenDelim(delim))?;
        let mut v = Vec::new();
        let close = TokenKind::CloseDelim(delim);
        if allow_empty && self.check(close) {
            self.bump();
            return Ok((v, lo.to(self.prev_token.span)));
        }
        loop {
            v.push(f(self)?);
            if self.check(close) {
                self.bump();
                break;
            }
            self.expect(TokenKind::Comma)?;
            if self.check(close) {
                let span = self.prev_token.span;
                self.dcx.emit(Diag::new(Level::Error, "trailing `,` separator is not allowed").span(span));
                self.bump();
                break;
            }
        }
        Ok((v, lo.to(self.prev_token.span)))
    }

    /// Parses a comma-separated sequence until `close` (exclusive; not consumed), allowing a
    /// trailing comma to be reported.
    pub fn parse_comma_seq_until<T>(
        &mut self,
        close: TokenKind,
        allow_empty: bool,
        mut f: impl FnMut(&mut Self) -> PResult<T>,
    ) -> PResult<Vec<T>> {
        let mut v = Vec::new();
        if allow_empty && self.check(close) {
            return Ok(v);
        }
        loop {
            v.push(f(self)?);
            if self.check(close) {
                break;
            }
            self.expect(TokenKind::Comma)?;
            if self.check(close) {
                let span = self.prev_token.span;
                self.dcx.emit(Diag::new(Level::Error, "trailing `,` separator is not allowed").span(span));
                break;
            }
        }
        Ok(v)
    }

    pub fn emit_err(&self, span: Span, msg: impl Into<String>) {
        self.dcx.emit(Diag::new(Level::Error, msg).span(span));
    }

    pub fn emit_warn(&self, span: Span, msg: impl Into<String>) {
        self.dcx.emit(Diag::new(Level::Warning, msg).span(span));
    }

    pub fn is_contract_kind(&self) -> bool {
        matches!(self.token.kind, TokenKind::Ident(kw::Contract | kw::Abstract | kw::Interface | kw::Library))
    }
}

fn tokens_to_string(tokens: &[ExpectedToken]) -> String {
    let mut i = tokens.iter();
    let b = i.next().map_or_else(String::new, |t| t.to_string());
    i.enumerate().fold(b, |mut b, (i, a)| {
        if tokens.len() > 2 && i == tokens.len() - 2 {
            b.push_str(", or ");
        } else if tokens.len() == 2 && i == tokens.len() - 2 {
            b.push_str(" or ");
        } else {
            b.push_str(", ");
        }
        b.push_str(&a.to_string());
        b
    })
}
