use crate::token::{Delimiter, Token, TokenKind};
use std::fmt;

/// Marker for an emitted (fatal) parse error.
#[derive(Debug, Clone, Copy)]
pub struct PErr;

pub type PResult<T> = Result<T, PErr>;

#[derive(Clone, PartialEq, Eq, Debug)]
pub enum ExpectedToken {
    Token(TokenKind),
    Keyword(Symbol),
    Ident,
    Literal,
    ElementaryType,
    Path,
    StrLit,
    Operator,
    VersionNumber,
}

impl fmt::Display for ExpectedToken {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ExpectedToken::Token(t) => write!(f, "`{t}`"),
            ExpectedToken::Keyword(k) => write!(f, "`{k}`"),
            ExpectedToken::Ident => f.write_str("identifier"),
            ExpectedToken::Literal => f.write_str("literal"),
            ExpectedToken::ElementaryType => f.write_str("elementary type name"),
            ExpectedToken::Path => f.write_str("path"),
            ExpectedToken::StrLit => f.write_str("string literal"),
            ExpectedToken::Operator => f.write_str("operator"),
            ExpectedToken::VersionNumber => f.write_str("version number"),
        }
    }
}

pub struct Parser<'a> {
    pub dcx: &'a DiagCtxt,
    tokens: Vec<Token>,
    idx: usize,
    pub token: Token,
    pub prev_token: Token,
    pub expected_tokens: Vec<ExpectedToken>,
    pub docs: Vec<DocComment>,
    pub in_contract: Option<ContractKind>,
    pub in_yul: bool,
    pub last_unexpected_token_span: Option<Span>,
    pub parse_yul_file: bool,
}

impl<'a> Parser<'a> {
    pub fn new(dcx: &'a DiagCtxt, mut tokens: Vec<Token>) -> Self {
        // EOF token span: span of the last real token.
        let n = tokens.len();
        if n >= 2 {
            let last = tokens[n - 2].span;
            tokens[n - 1].span = last;
        }
        let mut p = Parser {
            dcx,
            tokens,
            idx: 0,
            token: Token::DUMMY,
            prev_token: Token::DUMMY,
            expected_tokens: Vec::new(),
            docs: Vec::new(),
            in_contract: None,
            in_yul: false,
            last_unexpected_token_span: None,
            parse_yul_file: false,
        };
        p.token = p.next_raw_token();
        p
    }

    /// Returns the next non-doc-comment token, accumulating doc comments.
    fn next_raw_token(&mut self) -> Token {
        loop {
            let tok = if self.idx < self.tokens.len() {
                let t = self.tokens[self.idx];
                self.idx += 1;
                t
            } else {
                *self.tokens.last().unwrap()
            };
            if let TokenKind::DocComment(is_block, symbol) = tok.kind {
                self.docs.push(DocComment { is_block, span: tok.span, symbol });
                continue;
            }
            return tok;
        }
    }

    pub fn bump(&mut self) {
        let next = self.next_raw_token();
        self.prev_token = self.token;
        self.token = next;
        self.expected_tokens.clear();
    }

    /// Looks ahead `n` tokens (skipping doc comments). `look_ahead(0)` is the current token.
    pub fn look_ahead(&self, n: usize) -> Token {
        if n == 0 {
            return self.token;
        }
        let mut i = self.idx;
        let mut remaining = n;
        loop {
            if i >= self.tokens.len() {
                return *self.tokens.last().unwrap();
            }
            let t = self.tokens[i];
            i += 1;
            if matches!(t.kind, TokenKind::DocComment(..)) {
                continue;
            }
            remaining -= 1;
            if remaining == 0 {
                return t;
            }
        }
    }

    pub fn parse_doc_comments(&mut self) -> DocComments {
        DocComments(std::mem::take(&mut self.docs))
    }

    // ---- checks ----

    pub fn check(&mut self, tok: TokenKind) -> bool {
        let is = self.token.kind == tok;
        if !is {
            self.expected_tokens.push(ExpectedToken::Token(tok));
        }
        is
    }

    pub fn check_noexpect(&self, tok: TokenKind) -> bool {
        self.token.kind == tok
    }

    pub fn eat(&mut self, tok: TokenKind) -> bool {
        let is = self.check(tok);
        if is {
            self.bump();
        }
        is
    }

    pub fn eat_noexpect(&mut self, tok: TokenKind) -> bool {
        let is = self.token.kind == tok;
        if is {
            self.bump();
        }
        is
    }

    pub fn check_keyword(&mut self, kw: Symbol) -> bool {
        let is = self.token.is_keyword(kw);
        if !is {
            self.expected_tokens.push(ExpectedToken::Keyword(kw));
        }
        is
    }

    pub fn eat_keyword(&mut self, kw: Symbol) -> bool {
        let is = self.check_keyword(kw);
        if is {
            self.bump();
        }
        is
    }

    pub fn eat_keyword_noexpect(&mut self, kw: Symbol) -> bool {
        let is = self.token.is_keyword(kw);
        if is {
            self.bump();
        }
        is
    }

    pub fn check_ident(&mut self) -> bool {
        let is = self.token.is_non_reserved_ident();
        if !is {
            self.expected_tokens.push(ExpectedToken::Ident);
        }
        is
    }

    pub fn check_literal(&mut self) -> bool {
        let is = self.token.is_literal();
        if !is {
            self.expected_tokens.push(ExpectedToken::Literal);
        }
        is
    }

    pub fn check_elementary_type(&mut self) -> bool {
        let is = self.token.is_elementary_type();
        if !is {
            self.expected_tokens.push(ExpectedToken::ElementaryType);
        }
        is
    }

    pub fn check_path(&mut self) -> bool {
        let is = self.token.is_non_reserved_ident();
        if !is {
            self.expected_tokens.push(ExpectedToken::Path);
        }
        is
    }

    pub fn check_str_lit(&mut self) -> bool {
        let is = matches!(self.token.kind, TokenKind::Literal(crate::token::LitKind::Str, _));
        if !is {
            self.expected_tokens.push(ExpectedToken::StrLit);
        }
        is
    }

    pub fn expect(&mut self, tok: TokenKind) -> PResult<()> {
        if self.expected_tokens.is_empty() {
            if self.token.kind == tok {
                self.bump();
                Ok(())
            } else {
                Err(self.unexpected_try_recover(tok))
            }
        } else {
            self.expect_one_of(&[tok], &[])
        }
    }

    pub fn expect_keyword(&mut self, kw: Symbol) -> PResult<()> {
        if self.eat_keyword(kw) {
            Ok(())
        } else {
