        let mut err = Diag::new(Level::Error, msg).span(sp);
        let label = format!("expected `{token_str}`");
        let sp2 = if self.token.is_eof() { self.prev_token.span } else { prev_sp };
        if self.prev_token.span.is_dummy() || !self.dcx.source_map.is_multiline(Span::new(sp2.lo.min(sp.lo), sp2.hi.max(sp.lo))) {
