        let sp = if self.token.is_eof() { self.prev_token.span } else { label_sp };
        let between = Span::new(sp.lo.min(self.token.span.lo), sp.hi.max(self.token.span.hi));
        if self.prev_token.span.is_dummy() || !self.dcx.source_map.is_multiline(between) {
