        } else {
            err = err.span_label(sp, label_exp);
            err = err.span_label(self.token.span, "unexpected token");
        }
        self.dcx.emit(err);
        PErr
    }

    /// Emits "expected identifier, found X".
    pub fn expected_ident_found_err(&mut self) -> PErr {
        let msg = format!("expected identifier, found {}", self.token.full_description());
        self.dcx.emit(Diag::new(Level::Error, msg).span(self.token.span));
        PErr
    }

    /// Parses an identifier. Recovers on keywords by emitting an error and using the keyword.
    pub fn parse_ident(&mut self) -> PResult<Ident> {
        self.parse_ident_common(true)
    }

    pub fn parse_ident_any(&mut self) -> PResult<Ident> {
        self.parse_ident_common(false)
    }

    fn parse_ident_common(&mut self, recover: bool) -> PResult<Ident> {
        match self.token.kind {
            TokenKind::Ident(sym) => {
                if sym.is_used_keyword() {
                    if recover {
                        let _ = self.expected_ident_found_err();
                        let ident = Ident::new(sym, self.token.span);
                        self.bump();
                        return Ok(ident);
                    }
                    return Err(self.expected_ident_found_err());
                }
                let ident = Ident::new(sym, self.token.span);
                self.bump();
                Ok(ident)
            }
            _ => Err(self.expected_ident_found_err()),
        }
    }

    pub fn parse_ident_opt(&mut self) -> PResult<Option<Ident>> {
        if self.check_ident() {
            Ok(Some(self.parse_ident()?))
        } else {
            Ok(None)
        }
    }

    /// Parses a `.`-separated path of identifiers.
    pub fn parse_path(&mut self) -> PResult<Path> {
        let first = self.parse_ident()?;
        self.parse_path_with(first)
    }

    pub fn parse_path_with(&mut self, first: Ident) -> PResult<Path> {
        let mut segments = vec![first];
