    /// Parses a comma-separated sequence delimited by `open`/`close`. Trailing commas are not
    /// allowed (an error is emitted but parsing continues).
    pub fn parse_delim_comma_seq<T>(
        &mut self,
        delim: Delimiter,
        allow_empty: bool,
        mut f: impl FnMut(&mut Self) -> PResult<T>,
    ) -> PResult<(Vec<T>, Span)> {
        let lo = self.token.span;
        self.expect(TokenKind::OpenDelim(delim))?;
        let mut v = Vec::new();
        let close = TokenKind::CloseDelim(delim);
        if allow_empty && self.check(close) {
            self.bump();
            return Ok((v, lo.to(self.prev_token.span)));
        }
        loop {
            v.push(f(self)?);
            if self.check(close) {
                self.bump();
                break;
            }
            self.expect(TokenKind::Comma)?;
            if self.check(close) {
                let span = self.prev_token.span;
                self.dcx.emit(Diag::new(Level::Error, "trailing `,` separator is not allowed").span(span));
                self.bump();
                break;
            }
        }
        Ok((v, lo.to(self.prev_token.span)))
    }

    /// Parses a comma-separated sequence until `close` (exclusive; not consumed), allowing a
    /// trailing comma to be reported.
    pub fn parse_comma_seq_until<T>(
        &mut self,
        close: TokenKind,
        allow_empty: bool,
        mut f: impl FnMut(&mut Self) -> PResult<T>,
    ) -> PResult<Vec<T>> {
        let mut v = Vec::new();
        if allow_empty && self.check(close) {
            return Ok(v);
        }
        loop {
            v.push(f(self)?);
            if self.check(close) {
                break;
            }
            self.expect(TokenKind::Comma)?;
            if self.check(close) {
                let span = self.prev_token.span;
                self.dcx.emit(Diag::new(Level::Error, "trailing `,` separator is not allowed").span(span));
                break;
            }
        }
        Ok(v)
    }

    pub fn emit_err(&self, span: Span, msg: impl Into<String>) {
        self.dcx.emit(Diag::new(Level::Error, msg).span(span));
    }

    pub fn emit_warn(&self, span: Span, msg: impl Into<String>) {
        self.dcx.emit(Diag::new(Level::Warning, msg).span(span));
    }

    pub fn is_contract_kind(&self) -> bool {
        matches!(self.token.kind, TokenKind::Ident(kw::Contract | kw::Abstract | kw::Interface | kw::Library))
    }
}

