//! Item parsing.

use super::{PResult, Parser};
use crate::ast::*;
use crate::diag::{Diag, Level};
use crate::span::{Span, Spanned};
use crate::symbol::kw;
use crate::token::{Delimiter, LitKind, TokenKind};

/// Flags for variable declaration parsing.
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum VarCtx {
    /// Contract or file-level state variable.
    State,
    /// Function parameter / return.
    FunctionParam,
    /// Error parameter.
    Error,
    /// Event parameter.
    Event,
    /// Struct field.
    Struct,
    /// Local statement variable.
    Statement,
    /// Try/catch returns.
    TryCatch,
    /// Function type parameters.
    FunctionTy,
}

impl<'a> Parser<'a> {
    pub fn parse_source_unit(&mut self) -> SourceUnit {
        let mut items = Vec::new();
        while !self.token.is_eof() {
            match self.parse_item() {
                Ok(item) => items.push(item),
                Err(_) => break,
            }
        }
        SourceUnit { items }
    }

    pub fn parse_item(&mut self) -> PResult<Item> {
        let docs = self.parse_doc_comments();
        let lo = self.token.span;
        let kind = self.parse_item_kind()?;
        let span = lo.to(self.prev_token.span);
        Ok(Item { docs, span, kind })
    }

    fn parse_item_kind(&mut self) -> PResult<ItemKind> {
        if self.is_function_like() {
            return self.parse_function().map(ItemKind::Function);
        }
        if self.check_keyword(kw::Struct) {
            return self.parse_struct().map(ItemKind::Struct);
        }
        if self.check_keyword(kw::Event) {
            return self.parse_event().map(ItemKind::Event);
        }
        if self.is_contract_kind() {
            return self.parse_contract().map(ItemKind::Contract);
        }
        if self.check_keyword(kw::Enum) {
            return self.parse_enum().map(ItemKind::Enum);
        }
        if self.check_keyword(kw::Pragma) {
            return self.parse_pragma().map(ItemKind::Pragma);
        }
        if self.check_keyword(kw::Import) {
            return self.parse_import().map(ItemKind::Import);
        }
        if self.check_keyword(kw::Using) {
            return self.parse_using().map(ItemKind::Using);
        }
        if self.check_keyword(kw::Type) {
            return self.parse_udvt().map(ItemKind::Udvt);
        }
        if self.token.is_keyword(kw::Error)
            && self.look_ahead(1).is_non_reserved_ident()
            && self.look_ahead(2).is_open_delim(Delimiter::Parenthesis)
        {
            return self.parse_error().map(ItemKind::Error);
        }
        if self.is_variable_declaration_start() {
            let var = self.parse_variable_definition(VarCtx::State)?;
            return Ok(ItemKind::Variable(var));
        }
        // Error.
        let (msg, note) = if self.in_contract.is_some() {
            (
                "expected contract item (function, variable, struct, or modifier definition)",
                "for a full list of valid contract items, see <https://docs.soliditylang.org/en/latest/grammar.html#a4.SolidityParser.contractBodyElement>",
            )
        } else {
            (
                "expected global item (pragma, import directive, contract, interface, library, struct, enum, constant, function, modifier, or error definition)",
                "for a full list of valid global items, see <https://docs.soliditylang.org/en/latest/grammar.html#a4.SolidityParser.sourceUnit>",
            )
        };
        let msg = format!("{msg}, found {}", self.token.full_description());
        self.dcx.emit(Diag::new(Level::Error, msg).span(self.token.span).note(note));
        Err(super::PErr)
    }

    fn is_function_like(&self) -> bool {
        match self.token.kind {
            TokenKind::Ident(kw::Function) => {
                // `function` followed by `(` is a function type variable, unless it's `function (`
                // directly. We handle `function (` as a function definition error later.
                let next = self.look_ahead(1);
                !(next.is_open_delim(Delimiter::Parenthesis) && self.function_type_lookahead())
            }
            TokenKind::Ident(kw::Constructor | kw::Fallback | kw::Receive | kw::Modifier) => true,
            _ => false,
        }
    }

    /// Determines whether `function (` starts a function type (variable declaration).
    /// We treat `function (` followed by params `)` and then attributes and an identifier as a
    /// type. This is a heuristic: a function definition requires a name.
    fn function_type_lookahead(&self) -> bool {
        // Find the matching `)`.
        let mut depth = 0usize;
        let mut i = 1;
        loop {
            let t = self.look_ahead(i);
            match t.kind {
                TokenKind::OpenDelim(_) => depth += 1,
                TokenKind::CloseDelim(_) => {
                    depth -= 1;
                    if depth == 0 {
                        break;
                    }
                }
                TokenKind::Eof => return false,
                _ => {}
            }
            i += 1;
            if i > 10000 {
                return false;
            }
        }
        // After `)`: skip attributes and returns; if we hit an identifier (name) before `{`/`;`,
        // it's a function type variable.
        i += 1;
        loop {
            let t = self.look_ahead(i);
            match t.kind {
                TokenKind::Ident(s)
                    if matches!(
                        s,
                        kw::Internal | kw::External | kw::Public | kw::Private | kw::Pure | kw::View | kw::Payable
                    ) =>
                {
                    i += 1;
                }
                TokenKind::Ident(kw::Returns) => {
                    // skip parenthesized
                    i += 1;
                    if !self.look_ahead(i).is_open_delim(Delimiter::Parenthesis) {
                        return false;
                    }
                    let mut depth = 0usize;
                    loop {
                        let t = self.look_ahead(i);
                        match t.kind {
                            TokenKind::OpenDelim(_) => depth += 1,
                            TokenKind::CloseDelim(_) => {
                                depth -= 1;
                                if depth == 0 {
                                    break;
                                }
                            }
                            TokenKind::Eof => return false,
                            _ => {}
                        }
                        i += 1;
                    }
                    i += 1;
                }
                TokenKind::Ident(s) if !s.is_used_keyword() => return true,
                TokenKind::Ident(kw::Constant | kw::Immutable | kw::Override | kw::Memory | kw::Storage | kw::Calldata) => {
                    return true
                }
                TokenKind::OpenDelim(Delimiter::Bracket) => return true,
                _ => return false,
            }
        }
    }

    fn is_variable_declaration_start(&self) -> bool {
        match self.token.kind {
            TokenKind::Ident(s) => s.is_elementary_type() || s == kw::Mapping || s == kw::Function || !s.is_used_keyword(),
            _ => false,
        }
    }

    // ---- contract ----

    fn parse_contract(&mut self) -> PResult<ItemContract> {
        let kind_lo = self.token.span;
        let kind = if self.eat_keyword(kw::Abstract) {
            self.expect_keyword(kw::Contract)?;
            ContractKind::AbstractContract
        } else if self.eat_keyword(kw::Contract) {
            ContractKind::Contract
        } else if self.eat_keyword(kw::Interface) {
            ContractKind::Interface
        } else if self.eat_keyword(kw::Library) {
            ContractKind::Library
        } else {
            unreachable!()
        };
        let kind_span = kind_lo.to(self.prev_token.span);
        let name = self.parse_ident()?;
        let mut layout = None;
        let mut bases = Vec::new();
        if self.eat_keyword(kw::Layout) {
            self.expect_keyword(kw::At)?;
            layout = Some(Box::new(self.parse_expr()?));
        }
        if self.eat_keyword(kw::Is) {
            loop {
                bases.push(self.parse_modifier()?);
                if !self.eat(TokenKind::Comma) {
                    break;
                }
            }
        }
        if layout.is_none() && self.eat_keyword(kw::Layout) {
            self.expect_keyword(kw::At)?;
            layout = Some(Box::new(self.parse_expr()?));
        }
        let outer = self.in_contract;
        self.in_contract = Some(kind);
        let body = self.parse_contract_body();
        self.in_contract = outer;
        let body = body?;
        if kind == ContractKind::Library && !bases.is_empty() {
            let span = bases.first().unwrap().name.span().to(bases.last().unwrap().name.span());
            self.emit_err(span, "library is not allowed to inherit");
        }
        Ok(ItemContract { kind, kind_span, name, layout, bases, body })
    }

    fn parse_contract_body(&mut self) -> PResult<Vec<Item>> {
        self.expect(TokenKind::OpenDelim(Delimiter::Brace))?;
        let mut items = Vec::new();
        while !self.eat(TokenKind::CloseDelim(Delimiter::Brace)) {
            let item = self.parse_item()?;
            match &item.kind {
                ItemKind::Pragma(_) => self.emit_err(item.span, "pragma directives are not allowed in contracts"),
                ItemKind::Import(_) => self.emit_err(item.span, "import directives are not allowed in contracts"),
                ItemKind::Contract(_) => self.emit_err(item.span, "contract definitions are not allowed in contracts"),
                _ => {}
            }
            items.push(item);
        }
        Ok(items)
    }

    /// Parses a modifier invocation / base: `Path` optionally followed by call arguments.
    pub fn parse_modifier(&mut self) -> PResult<Modifier> {
        let name = self.parse_path()?;
        let arguments = if self.token.is_open_delim(Delimiter::Parenthesis) {
            self.parse_call_args()?
        } else {
            CallArgs::empty(self.prev_token.span.shrink_to_hi())
        };
        Ok(Modifier { name, arguments })
    }

    // ---- function ----

    fn parse_function(&mut self) -> PResult<ItemFunction> {
        let lo = self.token.span;
        let kind = match self.token.kind {
            TokenKind::Ident(kw::Function) => FunctionKind::Function,
            TokenKind::Ident(kw::Constructor) => FunctionKind::Constructor,
            TokenKind::Ident(kw::Fallback) => FunctionKind::Fallback,
            TokenKind::Ident(kw::Receive) => FunctionKind::Receive,
            TokenKind::Ident(kw::Modifier) => FunctionKind::Modifier,
            _ => unreachable!(),
        };
        self.bump();
        let kind_span = self.prev_token.span;
        let header = self.parse_function_header(kind, lo)?;

        let (body, body_span) = if self.check(TokenKind::Semi) && kind != FunctionKind::Constructor {
            self.bump();
            (None, self.prev_token.span)
        } else {
            let block = self.parse_block()?;
            let span = block.span;
            (Some(block), span)
        };
        let span = lo.to(self.prev_token.span);
        let func = ItemFunction { kind, kind_span, header, body, body_span };
        self.check_function(&func, span);
        Ok(func)
    }

    fn parse_function_header(&mut self, kind: FunctionKind, lo: Span) -> PResult<FunctionHeader> {
        let mut header = FunctionHeader::default();
        if kind == FunctionKind::Function {
            // `function (` is a state variable declaration of function type, which is an error here.
            if self.token.is_open_delim(Delimiter::Parenthesis) {
                self.emit_err(self.token.span, "expected a state variable declaration");
                return Err(super::PErr);
            }
            header.name = Some(self.parse_ident()?);
        } else if kind == FunctionKind::Modifier {
            header.name = Some(self.parse_ident()?);
        }

        if kind == FunctionKind::Modifier && !self.token.is_open_delim(Delimiter::Parenthesis) {
            header.parameters = ParameterList { span: self.prev_token.span.shrink_to_hi(), vars: vec![] };
        } else {
            header.parameters = self.parse_parameter_list(VarCtx::FunctionParam)?;
        }

        let allow_returns = matches!(kind, FunctionKind::Function | FunctionKind::Fallback);
        loop {
            if let Some(vis) = self.parse_visibility_opt() {
                if let Some(prev) = header.visibility {
                    self.dcx.emit(
                        Diag::new(Level::Error, "visibility already specified")
                            .span(vis.span)
                            .span_label(prev.span, "previous definition"),
                    );
                } else {
                    header.visibility = Some(vis);
                }
            } else if let Some(sm) = self.parse_state_mutability_opt() {
                if let Some(prev) = header.state_mutability {
                    self.dcx.emit(
                        Diag::new(Level::Error, "state mutability already specified")
                            .span(sm.span)
                            .span_label(prev.span, "previous definition"),
                    );
                } else {
                    header.state_mutability = Some(sm);
                }
            } else if self.check_keyword(kw::Virtual) {
                let span = self.token.span;
                self.bump();
                if let Some(prev) = header.virtual_ {
                    self.dcx.emit(
                        Diag::new(Level::Error, "virtual already specified")
                            .span(span)
                            .span_label(prev, "previous definition"),
                    );
                } else {
                    header.virtual_ = Some(span);
                }
            } else if self.check_keyword(kw::Override) {
                let ov = self.parse_override()?;
                if let Some(prev) = &header.override_ {
                    self.dcx.emit(
                        Diag::new(Level::Error, "override already specified")
                            .span(ov.span)
                            .span_label(prev.span, "previous definition"),
                    );
                } else {
                    header.override_ = Some(ov);
                }
            } else if allow_returns && self.check_keyword(kw::Returns) {
                self.bump();
                let returns = self.parse_parameter_list(VarCtx::FunctionParam)?;
                header.returns = Some(returns);
                break;
            } else if self.token.is_non_reserved_ident() {
                header.modifiers.push(self.parse_modifier()?);
            } else {
                break;
            }
        }
        header.span = lo.to(self.prev_token.span);
        Ok(header)
    }

    pub fn parse_visibility_opt(&mut self) -> Option<Spanned<Visibility>> {
        let v = match self.token.kind {
            TokenKind::Ident(kw::Private) => Visibility::Private,
            TokenKind::Ident(kw::Internal) => Visibility::Internal,
            TokenKind::Ident(kw::Public) => Visibility::Public,
            TokenKind::Ident(kw::External) => Visibility::External,
            _ => {
                self.check_keyword(kw::Private);
                self.check_keyword(kw::Internal);
                self.check_keyword(kw::Public);
                self.check_keyword(kw::External);
                return None;
            }
        };
        let span = self.token.span;
        self.bump();
        Some(Spanned { span, data: v })
    }

    pub fn parse_state_mutability_opt(&mut self) -> Option<Spanned<StateMutability>> {
        let v = match self.token.kind {
            TokenKind::Ident(kw::Pure) => StateMutability::Pure,
            TokenKind::Ident(kw::View) => StateMutability::View,
            TokenKind::Ident(kw::Payable) => StateMutability::Payable,
            _ => {
                self.check_keyword(kw::Pure);
                self.check_keyword(kw::View);
                self.check_keyword(kw::Payable);
                return None;
            }
        };
        let span = self.token.span;
        self.bump();
        Some(Spanned { span, data: v })
    }

    fn parse_override(&mut self) -> PResult<Override> {
        let lo = self.token.span;
        self.expect_keyword(kw::Override)?;
        let mut paths = Vec::new();
        if self.token.is_open_delim(Delimiter::Parenthesis) {
            let (p, _) = self.parse_delim_comma_seq(Delimiter::Parenthesis, false, |this| this.parse_path())?;
            paths = p;
        }
        Ok(Override { span: lo.to(self.prev_token.span), paths })
    }

    /// Checks a parsed function for context errors (emitted at parse time).
    fn check_function(&mut self, func: &ItemFunction, span: Span) {
        let kind = func.kind;
        let header = &func.header;
        match self.in_contract {
            None => {
                // Free function.
                match kind {
                    FunctionKind::Function => {
                        if let Some(vis) = header.visibility {
                            self.dcx.emit(
                                Diag::new(Level::Error, "free functions cannot have visibility")
                                    .span(span)
                                    .help(format!("remove `{}` from the declaration", vis.data.to_str())),
                            );
                        }
                        if func.body.is_none() {
                            self.emit_err(span, "free functions must be implemented");
                        }
                    }
                    FunctionKind::Modifier => self.emit_err(span, "modifiers are not allowed in the global scope"),
                    FunctionKind::Constructor => self.emit_err(span, "constructors are not allowed in the global scope"),
                    FunctionKind::Fallback => self.emit_err(span, "fallbacks are not allowed in the global scope"),
                    FunctionKind::Receive => self.emit_err(span, "receives are not allowed in the global scope"),
                }
                if kind != FunctionKind::Function {
                    return;
                }
            }
            Some(ckind) => {
                match kind {
                    FunctionKind::Function => {
                        if header.visibility.is_none() {
                            self.emit_err(span, "no visibility specified");
                        }
                    }
                    FunctionKind::Constructor => {
                        if let Some(vis) = header.visibility {
                            if !matches!(vis.data, Visibility::Internal | Visibility::Public) {
                                self.emit_err(
                                    vis.span,
                                    format!("`{}` not allowed here; allowed values: internal, public", vis.data.to_str()),
                                );
                            }
                        }
                        if let Some(sm) = header.state_mutability {
                            if sm.data != StateMutability::Payable {
                                self.emit_err(
                                    sm.span,
                                    format!("`{}` not allowed here; allowed values: payable", sm.data.to_str()),
                                );
                            }
                        }
                        if let Some(v) = header.virtual_ {
                            self.emit_err(v, "`virtual` is not allowed here");
                        }
                        if let Some(o) = &header.override_ {
                            self.emit_err(o.span, "`override` is not allowed here");
                        }
                    }
                    FunctionKind::Fallback | FunctionKind::Receive => {
                        if let Some(vis) = header.visibility {
                            if vis.data != Visibility::External {
                                self.emit_err(
                                    vis.span,
                                    format!("`{}` not allowed here; allowed values: external", vis.data.to_str()),
                                );
                            }
                        }
                        if kind == FunctionKind::Receive {
                            if let Some(sm) = header.state_mutability {
                                if sm.data != StateMutability::Payable {
                                    self.emit_err(
                                        sm.span,
                                        format!("`{}` not allowed here; allowed values: payable", sm.data.to_str()),
                                    );
                                }
                            } else {
                                self.dcx.emit(
                                    Diag::new(Level::Error, "receive ether function must be payable")
                                        .span(span)
                                        .help("add `payable` state mutability"),
                                );
                            }
                            if !header.parameters.vars.is_empty() {
                                self.emit_err(header.parameters.span, "receive ether function cannot take parameters");
                            }
                            if ckind == ContractKind::Library {
                                self.emit_err(span, "libraries cannot have receive ether functions");
                            }
                        }
                        if header.visibility.is_none() {
                            self.emit_err(span, "no visibility specified");
                        }
                    }
                    FunctionKind::Modifier => {
                        if let Some(vis) = header.visibility {
                            self.emit_err(vis.span, "visibility is not allowed here");
                        }
                        if let Some(sm) = header.state_mutability {
                            self.emit_err(sm.span, "state mutability is not allowed here");
                        }
                        if let Some(body) = &func.body {
                            if !block_has_placeholder(body) {
                                self.emit_err(span, "modifier must have a `_;` placeholder statement");
                            }
                        }
                    }
                }
            }
        }
    }

    pub fn parse_parameter_list(&mut self, ctx: VarCtx) -> PResult<ParameterList> {
        let lo = self.token.span;
        self.expect(TokenKind::OpenDelim(Delimiter::Parenthesis))?;
        let close = TokenKind::CloseDelim(Delimiter::Parenthesis);
        let mut vars = Vec::new();
        let mut first = true;
        while !self.check(close) {
            if self.token.is_eof() {
                break;
            }
            if first {
                first = false;
            } else {
                self.expect(TokenKind::Comma)?;
            }
            if self.check(close) {
                let span = self.prev_token.span;
                self.emit_err(span, "trailing `,` separator is not allowed");
                break;
            }
            vars.push(self.parse_variable_definition(ctx)?);
        }
        self.eat(close);
        Ok(ParameterList { span: lo.to(self.prev_token.span), vars })
    }

    // ---- variables ----

    pub fn parse_variable_definition(&mut self, ctx: VarCtx) -> PResult<VariableDefinition> {
        let ty = self.parse_type()?;
        self.parse_variable_definition_with(ctx, ty)
    }

    pub fn parse_variable_definition_with(&mut self, ctx: VarCtx, ty: Type) -> PResult<VariableDefinition> {
        let lo = ty.span;
        let mut visibility: Option<Spanned<Visibility>> = None;
        let mut mutability: Option<Spanned<VarMut>> = None;
        let mut data_location: Option<Spanned<DataLocation>> = None;
        let mut override_: Option<Override> = None;
        let mut indexed: Option<Span> = None;
        loop {
            if let Some(vis) = self.parse_visibility_opt() {
                if visibility.is_some() {
                    self.emit_err(vis.span, "visibility already specified");
                } else {
                    visibility = Some(vis);
                }
            } else if let Some(m) = self.parse_var_mutability_opt() {
                if mutability.is_some() {
                    self.emit_err(m.span, "mutability already specified");
                } else {
                    mutability = Some(m);
                }
            } else if let Some(loc) = self.parse_data_location_opt() {
                if data_location.is_some() {
                    self.emit_err(loc.span, "data location already specified");
                } else {
                    data_location = Some(loc);
                }
            } else if self.check_keyword(kw::Indexed) {
                let span = self.token.span;
                self.bump();
                if indexed.is_some() {
                    self.emit_err(span, "`indexed` already specified");
                } else {
                    indexed = Some(span);
                }
            } else if self.check_keyword(kw::Override) {
                let ov = self.parse_override()?;
                if override_.is_some() {
                    self.emit_err(ov.span, "override already specified");
                } else {
                    override_ = Some(ov);
                }
            } else if self.check_keyword(kw::Virtual) {
                let span = self.token.span;
                self.bump();
                self.emit_err(span, "`virtual` is not allowed here");
            } else {
                break;
            }
        }

        let name = match ctx {
            VarCtx::State | VarCtx::Struct => Some(self.parse_ident()?),
            _ => self.parse_ident_opt()?,
        };

        let mut initializer = None;
        match ctx {
            VarCtx::State => {
                if self.eat(TokenKind::Eq) {
                    initializer = Some(Box::new(self.parse_expr()?));
                }
                self.expect(TokenKind::Semi)?;
            }
            VarCtx::Statement => {
                if self.eat(TokenKind::Eq) {
                    initializer = Some(Box::new(self.parse_expr()?));
                }
                self.expect(TokenKind::Semi)?;
            }
            _ => {}
        }

        let span = lo.to(self.prev_token.span);
        let var = VariableDefinition {
            span,
            ty,
            visibility,
            mutability,
            data_location,
            override_,
            indexed,
            name,
            initializer,
        };
        self.check_variable(&var, ctx);
        Ok(var)
    }

    fn check_variable(&mut self, var: &VariableDefinition, ctx: VarCtx) {
        let span = var.span;
        // visibility
        if let Some(vis) = var.visibility {
            match ctx {
                VarCtx::State if self.in_contract.is_some() => {
                    if vis.data == Visibility::External {
                        self.emit_err(vis.span, "`external` not allowed here; allowed values: private, internal, public");
                    }
                }
                _ => self.emit_err(vis.span, "visibility is not allowed here"),
            }
        }
        if let Some(m) = var.mutability {
            match ctx {
                VarCtx::State => {}
                _ => self.emit_err(m.span, "mutability is not allowed here"),
            }
        }
        if let Some(idx) = var.indexed {
            if ctx != VarCtx::Event {
                self.emit_err(idx, "`indexed` is not allowed here");
            }
        }
        if let Some(loc) = var.data_location {
            match ctx {
                VarCtx::Struct | VarCtx::Error | VarCtx::Event => {
                    self.emit_err(loc.span, "data locations are not allowed here");
                }
                _ => {}
            }
        }
        if ctx == VarCtx::State {
            match self.in_contract {
                None => {
                    if var.mutability.map(|m| m.data) != Some(VarMut::Constant) {
                        self.emit_err(span, "only constant variables are allowed at file level");
                    }
                }
                Some(ContractKind::Library) => {
                    if var.mutability.map(|m| m.data) != Some(VarMut::Constant) {
                        self.emit_err(span, "library cannot have non-constant state variable");
                    }
                }
                _ => {}
            }
            if var.mutability.map(|m| m.data) == Some(VarMut::Constant) && var.initializer.is_none() {
                self.emit_err(span, "constant variable must be initialized");
            }
        }
    }

    pub fn parse_var_mutability_opt(&mut self) -> Option<Spanned<VarMut>> {
        let v = match self.token.kind {
            TokenKind::Ident(kw::Constant) => VarMut::Constant,
            TokenKind::Ident(kw::Immutable) => VarMut::Immutable,
            _ => {
                self.check_keyword(kw::Constant);
                self.check_keyword(kw::Immutable);
                return None;
            }
        };
        let span = self.token.span;
        self.bump();
        Some(Spanned { span, data: v })
    }

    pub fn parse_data_location_opt(&mut self) -> Option<Spanned<DataLocation>> {
        let v = match self.token.kind {
            TokenKind::Ident(kw::Storage) => DataLocation::Storage,
            TokenKind::Ident(kw::Memory) => DataLocation::Memory,
            TokenKind::Ident(kw::Calldata) => DataLocation::Calldata,
            TokenKind::Ident(kw::Transient) => DataLocation::Transient,
            _ => {
                self.check_keyword(kw::Storage);
                self.check_keyword(kw::Memory);
                self.check_keyword(kw::Calldata);
                self.check_keyword(kw::Transient);
                return None;
            }
        };
        let span = self.token.span;
        self.bump();
        Some(Spanned { span, data: v })
    }

    // ---- struct / enum / udvt / error / event ----

    fn parse_struct(&mut self) -> PResult<ItemStruct> {
        let lo = self.token.span;
        self.expect_keyword(kw::Struct)?;
        let name = self.parse_ident()?;
        self.expect(TokenKind::OpenDelim(Delimiter::Brace))?;
        let close = TokenKind::CloseDelim(Delimiter::Brace);
        let mut fields = Vec::new();
        let mut first = true;
        let mut trailing = false;
        while !self.check(close) {
            if self.token.is_eof() {
                break;
            }
            if first {
                first = false;
            } else {
                self.expect(TokenKind::Semi)?;
            }
            if self.check(close) {
                trailing = true;
                break;
            }
            fields.push(self.parse_variable_definition(VarCtx::Struct)?);
        }
        if !trailing && !fields.is_empty() {
            // Required trailing `;`: emit but recover.
            let _ = self.expect(TokenKind::Semi);
        }
        self.eat(close);
        let span = lo.to(self.prev_token.span);
        if fields.is_empty() {
            self.emit_err(span, "structs must have at least one field");
        }
        Ok(ItemStruct { name, fields })
    }

    fn parse_enum(&mut self) -> PResult<ItemEnum> {
        let lo = self.token.span;
        self.expect_keyword(kw::Enum)?;
        let name = self.parse_ident()?;
        let (variants, _) = self.parse_delim_comma_seq(Delimiter::Brace, true, |this| this.parse_ident())?;
        let span = lo.to(self.prev_token.span);
        if variants.is_empty() {
            self.emit_err(span, "enum must have at least one variant");
        }
        Ok(ItemEnum { name, variants })
    }

    fn parse_udvt(&mut self) -> PResult<ItemUdvt> {
        self.expect_keyword(kw::Type)?;
        let name = self.parse_ident()?;
        self.expect_keyword(kw::Is)?;
        let ty = self.parse_type()?;
        self.expect(TokenKind::Semi)?;
        if !matches!(ty.kind, TypeKind::Elementary(e) if !matches!(e, ElementaryType::String | ElementaryType::Bytes)) {
            self.emit_err(ty.span, "the underlying type of UDVTs must be an elementary value type");
        }
        Ok(ItemUdvt { name, ty })
    }

    fn parse_error(&mut self) -> PResult<ItemError> {
        self.bump(); // `error`
        let name = self.parse_ident()?;
        let parameters = self.parse_parameter_list(VarCtx::Error)?;
        self.expect(TokenKind::Semi)?;
        Ok(ItemError { name, parameters })
    }

    fn parse_event(&mut self) -> PResult<ItemEvent> {
        self.expect_keyword(kw::Event)?;
        let name = self.parse_ident()?;
        let parameters = self.parse_parameter_list(VarCtx::Event)?;
        let anonymous = if self.check_keyword(kw::Anonymous) {
            let span = self.token.span;
            self.bump();
            Some(span)
        } else {
            None
        };
        self.expect(TokenKind::Semi)?;
        Ok(ItemEvent { name, parameters, anonymous })
    }

    // ---- pragma ----

    fn parse_pragma(&mut self) -> PResult<PragmaDirective> {
        let lo = self.token.span;
        self.expect_keyword(kw::Pragma)?;
        let tokens;
        if self.token.is_keyword(kw::Solidity) {
            let ident = Ident::new(kw::Solidity, self.token.span);
            self.bump();
            let reqs = self.parse_semver_req()?;
            tokens = PragmaTokens::Version(ident, reqs);
        } else if self.is_ident_or_strlit()
            && (self.look_ahead(1).kind == TokenKind::Semi
                || (is_ident_or_strlit_tok(self.look_ahead(1)) && self.look_ahead(2).kind == TokenKind::Semi))
        {
            let a = self.parse_ident_or_strlit()?;
            let b = if self.token.kind == TokenKind::Semi { None } else { Some(self.parse_ident_or_strlit()?) };
            tokens = PragmaTokens::Custom(a, b);
        } else {
            let mut toks = Vec::new();
            while !self.check(TokenKind::Semi) && !self.token.is_eof() {
                toks.push(self.token);
                self.bump();
            }
            if toks.is_empty() {
                self.emit_err(lo.to(self.prev_token.span), "expected at least one token in pragma directive");
            }
            tokens = PragmaTokens::Verbatim(toks);
        }
        self.expect(TokenKind::Semi)?;
        let span = lo.to(self.prev_token.span);
        // Validate known pragmas.
        let known = match &tokens {
            PragmaTokens::Version(..) => true,
            PragmaTokens::Custom(a, b) => {
                let a = a.value();
                match (a.as_str(), b) {
                    ("abicoder", Some(b)) => matches!(b.value().as_str(), "v1" | "v2"),
                    ("experimental", Some(b)) => matches!(
                        b.value().as_str(),
                        "ABIEncoderV2" | "SMTChecker" | "__test" | "__testOnlyAnalysis"
                    ),
                    _ => false,
                }
            }
            PragmaTokens::Verbatim(_) => false,
        };
        if !known {
            self.emit_err(span, "unknown pragma");
        }
        Ok(PragmaDirective { tokens })
    }

    fn is_ident_or_strlit(&self) -> bool {
        is_ident_or_strlit_tok(self.token)
    }

    fn parse_ident_or_strlit(&mut self) -> PResult<IdentOrStrLit> {
        if let TokenKind::Literal(LitKind::Str, sym) = self.token.kind {
            let span = self.token.span;
            self.bump();
            let raw = sym.as_str();
            let value = raw[1..raw.len() - 1].to_string();
            Ok(IdentOrStrLit::StrLit(StrLit { span, value }))
        } else {
            Ok(IdentOrStrLit::Ident(self.parse_ident_any()?))
        }
    }

    // ---- import ----

    fn parse_import(&mut self) -> PResult<ImportDirective> {
        self.expect_keyword(kw::Import)?;
        let items;
        let path;
        if self.check(TokenKind::BinOp(crate::token::BinOpToken::Star)) {
            self.bump();
            self.expect_keyword(kw::As)?;
            let alias = self.parse_ident()?;
            self.expect_keyword(kw::From)?;
            path = self.parse_str_lit()?;
            items = ImportItems::Glob(alias);
        } else if self.check(TokenKind::OpenDelim(Delimiter::Brace)) {
            let (aliases, _) = self.parse_delim_comma_seq(Delimiter::Brace, false, |this| {
                let name = this.parse_ident()?;
                let alias = if this.eat_keyword(kw::As) { Some(this.parse_ident()?) } else { None };
                Ok((name, alias))
            })?;
            self.expect_keyword(kw::From)?;
            path = self.parse_str_lit()?;
            items = ImportItems::Aliases(aliases);
        } else if self.check_str_lit() {
            path = self.parse_str_lit()?;
            let alias = if self.eat_keyword(kw::As) { Some(self.parse_ident()?) } else { None };
            items = ImportItems::Plain(alias);
        } else {
            return Err(self.expected_one_of_not_found(&[], &[]));
        }
        self.expect(TokenKind::Semi)?;
        Ok(ImportDirective { path, items })
    }

    pub fn parse_str_lit(&mut self) -> PResult<StrLit> {
        if let TokenKind::Literal(LitKind::Str, sym) = self.token.kind {
            let span = self.token.span;
            self.bump();
            let raw = sym.as_str();
            let value = crate::parser::lit::unescape_str(&raw[1..raw.len() - 1]);
            let value = String::from_utf8_lossy(&value).into_owned();
            Ok(StrLit { span, value })
        } else {
            self.check_str_lit();
            Err(self.expected_one_of_not_found(&[], &[]))
        }
    }

    // ---- using ----

    fn parse_using(&mut self) -> PResult<UsingDirective> {
        let lo = self.token.span;
        self.expect_keyword(kw::Using)?;
        let list = if self.check(TokenKind::OpenDelim(Delimiter::Brace)) {
            let (items, _) = self.parse_delim_comma_seq(Delimiter::Brace, false, |this| {
                let path = this.parse_path()?;
                let op = if this.eat_keyword(kw::As) { Some(this.parse_user_definable_operator()?) } else { None };
                Ok((path, op))
            })?;
            UsingList::Multiple(items)
        } else {
            UsingList::Single(self.parse_path()?)
        };
        self.expect_keyword(kw::For)?;
        let ty = if self.check(TokenKind::BinOp(crate::token::BinOpToken::Star)) {
            self.bump();
            None
        } else {
            Some(self.parse_type()?)
        };
        let global = self.eat_keyword(kw::Global);
        self.expect(TokenKind::Semi)?;
        let span = lo.to(self.prev_token.span);
        if ty.is_none() && self.in_contract.is_none() {
            self.emit_err(span, "the type has to be specified explicitly at file level (cannot use `*`)");
        }
        Ok(UsingDirective { list, ty, global })
    }

    fn parse_user_definable_operator(&mut self) -> PResult<UserDefinableOperator> {
        use crate::token::BinOpToken::*;
        let op = match self.token.kind {
            TokenKind::BinOp(And) => UserDefinableOperator::BitAnd,
            TokenKind::Tilde => UserDefinableOperator::BitNot,
            TokenKind::BinOp(Or) => UserDefinableOperator::BitOr,
            TokenKind::BinOp(Caret) => UserDefinableOperator::BitXor,
            TokenKind::BinOp(Plus) => UserDefinableOperator::Add,
            TokenKind::BinOp(Slash) => UserDefinableOperator::Div,
            TokenKind::BinOp(Percent) => UserDefinableOperator::Rem,
            TokenKind::BinOp(Star) => UserDefinableOperator::Mul,
            TokenKind::BinOp(Minus) => UserDefinableOperator::Sub,
            TokenKind::EqEq => UserDefinableOperator::Eq,
            TokenKind::Ge => UserDefinableOperator::Ge,
            TokenKind::Gt => UserDefinableOperator::Gt,
            TokenKind::Le => UserDefinableOperator::Le,
            TokenKind::Lt => UserDefinableOperator::Lt,
            TokenKind::Ne => UserDefinableOperator::Ne,
            _ => {
                for t in [
                    TokenKind::BinOp(And),
                    TokenKind::Tilde,
                    TokenKind::BinOp(Or),
                    TokenKind::BinOp(Caret),
                    TokenKind::BinOp(Plus),
                    TokenKind::BinOp(Slash),
                    TokenKind::BinOp(Percent),
                    TokenKind::BinOp(Star),
                    TokenKind::BinOp(Minus),
                    TokenKind::EqEq,
                    TokenKind::Ge,
                    TokenKind::Gt,
                    TokenKind::Le,
                    TokenKind::Lt,
                    TokenKind::Ne,
                ] {
                    self.check(t);
                }
                return Err(self.expected_one_of_not_found(&[], &[]));
            }
        };
        self.bump();
        Ok(op)
    }
}

fn is_ident_or_strlit_tok(t: crate::token::Token) -> bool {
    matches!(t.kind, TokenKind::Ident(_) | TokenKind::Literal(LitKind::Str, _))
}

fn block_has_placeholder(block: &Block) -> bool {
    block.stmts.iter().any(stmt_has_placeholder)
}

fn stmt_has_placeholder(stmt: &Stmt) -> bool {
    match &stmt.kind {
        StmtKind::Placeholder => true,
        StmtKind::Block(b) | StmtKind::UncheckedBlock(b) => block_has_placeholder(b),
        StmtKind::If(_, t, e) => stmt_has_placeholder(t) || e.as_ref().is_some_and(|e| stmt_has_placeholder(e)),
        StmtKind::While(_, b) | StmtKind::DoWhile(b, _) => stmt_has_placeholder(b),
        StmtKind::For { body, .. } => stmt_has_placeholder(body),
        StmtKind::Try(t) => block_has_placeholder(&t.block) || t.catch.iter().any(|c| block_has_placeholder(&c.block)),
        _ => false,
    }
}
