use super::item::VarCtx;
use super::{PErr, PResult, Parser};
use crate::ast::*;
use crate::symbol::{elementary_type_size, kw, Symbol};
use crate::token::{Delimiter, TokenKind};

impl<'a> Parser<'a> {
    /// Parses a type.
    pub fn parse_type(&mut self) -> PResult<Type> {
        let lo = self.token.span;
        let mut ty = if self.check_elementary_type() {
            let elem = self.parse_elementary_type()?;
            Type { span: lo.to(self.prev_token.span), kind: TypeKind::Elementary(elem) }
        } else if self.check_keyword(kw::Function) {
            let f = self.parse_function_type()?;
            Type { span: lo.to(self.prev_token.span), kind: TypeKind::Function(Box::new(f)) }
        } else if self.check_keyword(kw::Mapping) {
            let m = self.parse_mapping_type()?;
            Type { span: lo.to(self.prev_token.span), kind: TypeKind::Mapping(Box::new(m)) }
        } else if self.check_path() {
            let path = self.parse_path()?;
            Type { span: lo.to(self.prev_token.span), kind: TypeKind::Custom(path) }
        } else {
            return Err(self.expected_one_of_not_found(&[], &[]));
        };
        // Array suffixes.
        while self.check(TokenKind::OpenDelim(Delimiter::Bracket)) {
            self.bump();
            let size = if self.check(TokenKind::CloseDelim(Delimiter::Bracket)) {
                None
            } else {
                Some(Box::new(self.parse_expr()?))
            };
            self.expect(TokenKind::CloseDelim(Delimiter::Bracket))?;
            ty = Type { span: lo.to(self.prev_token.span), kind: TypeKind::Array(Box::new(ty), size) };
        }
        Ok(ty)
    }

    /// Parses an elementary type keyword, including the optional state mutability for `address`.
    pub fn parse_elementary_type(&mut self) -> PResult<ElementaryType> {
        let sym = match self.token.kind {
            TokenKind::Ident(s) if s.is_elementary_type() => s,
            _ => return Err(self.expected_one_of_not_found(&[], &[])),
        };
        let ty_span = self.token.span;
        self.bump();
        let mut ty = elementary_type_from_symbol(sym);
        if let Some(sm) = self.parse_state_mutability_opt() {
            match ty {
                ElementaryType::Address(_) => {
                    if sm.data == StateMutability::Payable {
                        ty = ElementaryType::Address(true);
                    } else {
                        self.emit_err(sm.span, "address types can only be payable or non-payable");
                    }
                }
                _ => {
                    self.emit_err(sm.span, "only address types can have state mutability");
                }
            }
        }
        let _ = ty_span;
        Ok(ty)
    }

    fn parse_function_type(&mut self) -> PResult<TypeFunction> {
        self.expect_keyword(kw::Function)?;
        let parameters = self.parse_parameter_list(VarCtx::FunctionTy)?;
        let mut visibility = None;
        let mut state_mutability = None;
        let mut returns = None;
        loop {
            if let Some(vis) = self.parse_visibility_opt() {
                if visibility.is_some() {
                    self.emit_err(vis.span, "visibility already specified");
                } else {
                    visibility = Some(vis);
                }
            } else if let Some(sm) = self.parse_state_mutability_opt() {
                if state_mutability.is_some() {
                    self.emit_err(sm.span, "state mutability already specified");
                } else {
                    state_mutability = Some(sm);
                }
            } else if self.check_keyword(kw::Returns) {
                self.bump();
                returns = Some(self.parse_parameter_list(VarCtx::FunctionTy)?);
                break;
            } else {
                break;
            }
        }
        Ok(TypeFunction { parameters, visibility, state_mutability, returns })
    }

    fn parse_mapping_type(&mut self) -> PResult<TypeMapping> {
        self.expect_keyword(kw::Mapping)?;
        self.expect(TokenKind::OpenDelim(Delimiter::Parenthesis))?;
        let key = self.parse_type()?;
        let key_name = self.parse_ident_opt()?;
        self.expect(TokenKind::FatArrow)?;
        let value = self.parse_type()?;
        let value_name = self.parse_ident_opt()?;
        self.expect(TokenKind::CloseDelim(Delimiter::Parenthesis))?;
        match &key.kind {
            TypeKind::Elementary(_) | TypeKind::Custom(_) => {}
            _ => {
                let _ = PErr;
            }
        }
        Ok(TypeMapping { key, key_name, value, value_name })
    }
}

pub fn elementary_type_from_symbol(sym: Symbol) -> ElementaryType {
    match sym {
        kw::Address => ElementaryType::Address(false),
        kw::Bool => ElementaryType::Bool,
        kw::String => ElementaryType::String,
        kw::Bytes => ElementaryType::Bytes,
        kw::Fixed => ElementaryType::Fixed(0, 0),
        kw::UFixed => ElementaryType::UFixed(0, 0),
        kw::Int => ElementaryType::Int(0),
        kw::UInt => ElementaryType::UInt(0),
        _ => match elementary_type_size(sym) {
            Some((0, n)) => ElementaryType::UInt(n),
            Some((1, n)) => ElementaryType::Int(n),
            Some((2, n)) => ElementaryType::FixedBytes(n as u8),
            _ => unreachable!("not an elementary type: {sym}"),
        },
    }
}
EOF
