//! Literal helpers.

use crate::ast::LitKind;
use crate::token::LitKind as TLitKind;

/// Parses an integer literal text (decimal or hex, with underscores) into a decimal string.
pub fn parse_integer(text: &str) -> String {
    let clean: String = text.chars().filter(|c| *c != '_').collect();
    if let Some(hex) = clean.strip_prefix("0x") {
        big_from_radix(hex, 16)
    } else {
        // strip leading zeros
        let s = clean.trim_start_matches('0');
        if s.is_empty() { "0".to_string() } else { s.to_string() }
    }
}

/// Simple big decimal conversion from a radix-16 string.
fn big_from_radix(digits: &str, radix: u32) -> String {
    // decimal digits little-endian
    let mut dec: Vec<u8> = vec![0];
    for c in digits.chars() {
        let d = c.to_digit(radix).unwrap_or(0);
        // dec = dec * radix + d
        let mut carry = d;
        for x in dec.iter_mut() {
            let v = (*x as u32) * radix + carry;
            *x = (v % 10) as u8;
            carry = v / 10;
        }
        while carry > 0 {
            dec.push((carry % 10) as u8);
            carry /= 10;
        }
    }
    while dec.len() > 1 && *dec.last().unwrap() == 0 {
        dec.pop();
    }
    dec.iter().rev().map(|d| (b'0' + d) as char).collect()
}

/// Parses a rational literal. If it denotes an integer (e.g. `1e18`, `1.0`), returns Number.
pub fn parse_rational(text: &str) -> LitKind {
    let clean: String = text.chars().filter(|c| *c != '_').collect();
    let (mantissa, exp) = match clean.find(['e', 'E']) {
        Some(i) => (&clean[..i], clean[i + 1..].parse::<i64>().unwrap_or(0)),
        None => (&clean[..], 0i64),
    };
    let (int_part, frac_part) = match mantissa.find('.') {
        Some(i) => (&mantissa[..i], &mantissa[i + 1..]),
        None => (mantissa, ""),
    };
    let frac_part = frac_part.trim_end_matches('0');
    let mut digits = format!("{int_part}{frac_part}");
    let mut exp = exp - frac_part.len() as i64;
    let digits_trim = digits.trim_start_matches('0').to_string();
    digits = if digits_trim.is_empty() { "0".to_string() } else { digits_trim };
    if digits == "0" {
        return LitKind::Number("0".to_string());
    }
    if exp >= 0 {
        while exp > 0 {
            digits.push('0');
            exp -= 1;
        }
        LitKind::Number(digits)
    } else {
        LitKind::Rational(clean)
    }
}

/// Returns the bytes represented by a string literal token (including prefix and quotes).
pub fn str_lit_bytes(kind: TLitKind, raw: &str) -> Vec<u8> {
    let body = match kind {
        TLitKind::HexStr => &raw[3..],
        TLitKind::UnicodeStr => &raw[7..],
        _ => raw,
    };
    let inner = &body[1..body.len().saturating_sub(1)];
    match kind {
        TLitKind::HexStr => {
            let hex: String = inner.chars().filter(|c| c.is_ascii_hexdigit()).collect();
            (0..hex.len() / 2).map(|i| u8::from_str_radix(&hex[i * 2..i * 2 + 2], 16).unwrap_or(0)).collect()
        }
        _ => unescape_str(inner),
    }
}

/// Unescapes a string literal body.
pub fn unescape_str(s: &str) -> Vec<u8> {
    let mut out = Vec::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c != '\\' {
            let mut buf = [0u8; 4];
            out.extend_from_slice(c.encode_utf8(&mut buf).as_bytes());
            continue;
        }
        let Some(e) = chars.next() else { break };
        match e {
            'n' => out.push(b'\n'),
            'r' => out.push(b'\r'),
            't' => out.push(b'\t'),
            '\\' => out.push(b'\\'),
            '\'' => out.push(b'\''),
            '"' => out.push(b'"'),
            '\n' => {}
            'x' => {
                let mut v = 0u8;
                for _ in 0..2 {
                    if let Some(d) = chars.peek().and_then(|c| c.to_digit(16)) {
                        v = v * 16 + d as u8;
                        chars.next();
                    }
                }
                out.push(v);
            }
            'u' => {
                let mut v = 0u32;
                for _ in 0..4 {
                    if let Some(d) = chars.peek().and_then(|c| c.to_digit(16)) {
                        v = v * 16 + d;
                        chars.next();
                    }
                }
                if let Some(ch) = char::from_u32(v) {
                    let mut buf = [0u8; 4];
                    out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                }
            }
            other => {
                let mut buf = [0u8; 4];
                out.extend_from_slice(other.encode_utf8(&mut buf).as_bytes());
            }
        }
    }
    out
}
