//! Expression parsing.

use super::{PResult, Parser};
use crate::ast::*;
use crate::diag::{Diag, Level};
use crate::span::Spanned;
use crate::symbol::kw;
use crate::token::{BinOpToken, Delimiter, LitKind as TLitKind, TokenKind};

const PREC_LOWEST: u8 = 1;

fn binop_prec(kind: TokenKind) -> Option<(BinOpKind, u8)> {
    use BinOpToken::*;
    Some(match kind {
        TokenKind::OrOr => (BinOpKind::Or, 2),
        TokenKind::AndAnd => (BinOpKind::And, 3),
        TokenKind::EqEq => (BinOpKind::Eq, 4),
        TokenKind::Ne => (BinOpKind::Ne, 4),
        TokenKind::Lt => (BinOpKind::Lt, 5),
        TokenKind::Gt => (BinOpKind::Gt, 5),
        TokenKind::Le => (BinOpKind::Le, 5),
        TokenKind::Ge => (BinOpKind::Ge, 5),
        TokenKind::BinOp(Or) => (BinOpKind::BitOr, 6),
        TokenKind::BinOp(Caret) => (BinOpKind::BitXor, 7),
        TokenKind::BinOp(And) => (BinOpKind::BitAnd, 8),
        TokenKind::BinOp(Shl) => (BinOpKind::Shl, 9),
        TokenKind::BinOp(Shr) => (BinOpKind::Shr, 9),
        TokenKind::BinOp(Sar) => (BinOpKind::Sar, 9),
        TokenKind::BinOp(Plus) => (BinOpKind::Add, 10),
        TokenKind::BinOp(Minus) => (BinOpKind::Sub, 10),
        TokenKind::BinOp(Star) => (BinOpKind::Mul, 11),
        TokenKind::BinOp(Slash) => (BinOpKind::Div, 11),
        TokenKind::BinOp(Percent) => (BinOpKind::Rem, 11),
        TokenKind::BinOp(StarStar) => (BinOpKind::Pow, 12),
        _ => return None,
    })
}

fn assign_op(kind: TokenKind) -> Option<Option<BinOpKind>> {
    use BinOpToken::*;
    Some(match kind {
        TokenKind::Eq => None,
        TokenKind::BinOpEq(op) => Some(match op {
            Plus => BinOpKind::Add,
            Minus => BinOpKind::Sub,
            Star => BinOpKind::Mul,
            Slash => BinOpKind::Div,
            Percent => BinOpKind::Rem,
            Caret => BinOpKind::BitXor,
            And => BinOpKind::BitAnd,
            Or => BinOpKind::BitOr,
            Shl => BinOpKind::Shl,
            Shr => BinOpKind::Shr,
            Sar => BinOpKind::Sar,
            StarStar => return None,
        }),
        _ => return None,
    })
}

fn unop(kind: TokenKind) -> Option<UnOpKind> {
    Some(match kind {
        TokenKind::PlusPlus => UnOpKind::PreInc,
        TokenKind::MinusMinus => UnOpKind::PreDec,
        TokenKind::Not => UnOpKind::Not,
        TokenKind::BinOp(BinOpToken::Minus) => UnOpKind::Neg,
        TokenKind::Tilde => UnOpKind::BitNot,
        _ => return None,
    })
}

impl<'a> Parser<'a> {
    pub fn parse_expr(&mut self) -> PResult<Expr> {
        let lhs = self.parse_binary_expr(PREC_LOWEST)?;
        self.parse_expr_rest(lhs)
    }

    /// Continues parsing an expression given an already-parsed primary (with postfix applied).
    pub fn parse_expr_with(&mut self, lhs: Expr) -> PResult<Expr> {
        let lhs = self.parse_binary_expr_with(lhs, PREC_LOWEST)?;
        self.parse_expr_rest(lhs)
    }

    fn parse_expr_rest(&mut self, lhs: Expr) -> PResult<Expr> {
        let lo = lhs.span;
        if self.eat(TokenKind::Question) {
            let then = self.parse_expr()?;
            self.expect(TokenKind::Colon)?;
            let els = self.parse_expr()?;
            let span = lo.to(self.prev_token.span);
            return Ok(Expr { span, kind: ExprKind::Ternary(Box::new(lhs), Box::new(then), Box::new(els)) });
        }
        if let Some(op) = assign_op(self.token.kind) {
            self.bump();
            let rhs = self.parse_expr()?;
            let span = lo.to(self.prev_token.span);
            return Ok(Expr { span, kind: ExprKind::Assign(Box::new(lhs), op, Box::new(rhs)) });
        }
        Ok(lhs)
    }

    fn parse_binary_expr(&mut self, min_prec: u8) -> PResult<Expr> {
        let lhs = self.parse_unary_expr()?;
        self.parse_binary_expr_with(lhs, min_prec)
    }

    fn parse_binary_expr_with(&mut self, mut lhs: Expr, min_prec: u8) -> PResult<Expr> {
        loop {
            let Some((op, prec)) = binop_prec(self.token.kind) else { break };
            if prec < min_prec {
                break;
            }
            let op_span = self.token.span;
            self.bump();
            let rhs = if op == BinOpKind::Pow { self.parse_binary_expr(prec)? } else { self.parse_binary_expr(prec + 1)? };
            let span = lhs.span.to(rhs.span);
            lhs = Expr {
                span,
                kind: ExprKind::Binary(Box::new(lhs), Spanned { span: op_span, data: op }, Box::new(rhs)),
            };
        }
        Ok(lhs)
    }

    fn parse_unary_expr(&mut self) -> PResult<Expr> {
        let lo = self.token.span;
        if let Some(op) = unop(self.token.kind) {
            self.bump();
            let expr = self.parse_unary_expr()?;
            let span = lo.to(self.prev_token.span);
            return Ok(Expr { span, kind: ExprKind::Unary(Spanned { span: lo, data: op }, Box::new(expr)) });
        }
        if self.check_keyword(kw::Delete) {
            self.bump();
            let expr = self.parse_unary_expr()?;
            let span = lo.to(self.prev_token.span);
            return Ok(Expr { span, kind: ExprKind::Delete(Box::new(expr)) });
        }
        if self.check(TokenKind::BinOp(BinOpToken::Plus)) {
            self.emit_err(self.token.span, "unary plus is not supported");
            self.bump();
            return self.parse_unary_expr();
        }
        let primary = self.parse_primary_expr()?;
        self.parse_postfix_expr(primary)
    }

    pub fn parse_postfix_expr(&mut self, mut expr: Expr) -> PResult<Expr> {
        let lo = expr.span;
        loop {
            if self.check(TokenKind::OpenDelim(Delimiter::Bracket)) {
                self.bump();
                let close = TokenKind::CloseDelim(Delimiter::Bracket);
                let mut start = None;
                let mut is_slice = false;
                let mut end = None;
                if self.check(TokenKind::Colon) {
                    self.bump();
                    is_slice = true;
                } else if !self.check(close) {
                    start = Some(Box::new(self.parse_expr()?));
                    if self.eat(TokenKind::Colon) {
                        is_slice = true;
                    }
                }
                if is_slice && !self.check(close) {
                    end = Some(Box::new(self.parse_expr()?));
                }
                self.expect(close)?;
                let span = lo.to(self.prev_token.span);
                expr = Expr {
                    span,
                    kind: if is_slice {
                        ExprKind::Slice(Box::new(expr), start, end)
                    } else {
                        ExprKind::Index(Box::new(expr), start)
                    },
                };
            } else if self.check(TokenKind::Dot) {
                self.bump();
                let member = self.parse_ident_any()?;
                let span = lo.to(self.prev_token.span);
                expr = Expr { span, kind: ExprKind::Member(Box::new(expr), member) };
            } else if self.check(TokenKind::OpenDelim(Delimiter::Parenthesis)) {
                let args = self.parse_call_args()?;
                let span = lo.to(self.prev_token.span);
                expr = Expr { span, kind: ExprKind::Call(Box::new(expr), args) };
            } else if self.check(TokenKind::OpenDelim(Delimiter::Brace)) {
                if !(self.look_ahead(1).is_non_reserved_ident() && self.look_ahead(2).kind == TokenKind::Colon) {
                    break;
                }
                let (args, _) = self.parse_named_args()?;
                let span = lo.to(self.prev_token.span);
                expr = Expr { span, kind: ExprKind::CallOptions(Box::new(expr), args) };
                if !self.token.is_open_delim(Delimiter::Parenthesis) {
                    self.emit_err(span, "call options must be part of a call expression");
                }
            } else if matches!(self.token.kind, TokenKind::PlusPlus | TokenKind::MinusMinus) {
                let op = if self.token.kind == TokenKind::PlusPlus { UnOpKind::PostInc } else { UnOpKind::PostDec };
                let op_span = self.token.span;
                self.bump();
                let span = lo.to(self.prev_token.span);
                expr = Expr { span, kind: ExprKind::Unary(Spanned { span: op_span, data: op }, Box::new(expr)) };
                break;
            } else {
                break;
            }
        }
        Ok(expr)
    }

    pub fn parse_call_args(&mut self) -> PResult<CallArgs> {
        let lo = self.token.span;
        self.expect(TokenKind::OpenDelim(Delimiter::Parenthesis))?;
        let kind = if self.token.is_open_delim(Delimiter::Brace) {
            let (args, _) = self.parse_named_args()?;
            CallArgsKind::Named(args)
        } else {
            let close = TokenKind::CloseDelim(Delimiter::Parenthesis);
            let mut v = Vec::new();
            let mut first = true;
            while !self.check(close) {
                if self.token.is_eof() {
                    break;
                }
                if first {
                    first = false;
                } else {
                    self.expect(TokenKind::Comma)?;
                }
                if self.check(close) {
                    let span = self.prev_token.span;
                    self.emit_err(span, "trailing `,` separator is not allowed");
                    break;
                }
                v.push(Box::new(self.parse_expr()?));
            }
            CallArgsKind::Unnamed(v)
        };
        self.eat(TokenKind::CloseDelim(Delimiter::Parenthesis));
        Ok(CallArgs { span: lo.to(self.prev_token.span), kind })
    }

    fn parse_named_args(&mut self) -> PResult<(Vec<NamedArg>, crate::span::Span)> {
        self.parse_delim_comma_seq(Delimiter::Brace, true, |this| {
            let name = this.parse_ident()?;
            this.expect(TokenKind::Colon)?;
            let value = Box::new(this.parse_expr()?);
            Ok(NamedArg { name, value })
        })
    }

    fn parse_primary_expr(&mut self) -> PResult<Expr> {
        let lo = self.token.span;
        if self.check_literal() {
            let lit = self.parse_lit()?;
            let subdenomination = self.parse_subdenomination_opt(&lit);
            let span = lo.to(self.prev_token.span);
            return Ok(Expr { span, kind: ExprKind::Lit(Box::new(lit), subdenomination) });
        }
        if self.check_ident() {
            let ident = self.parse_ident()?;
            return Ok(Expr { span: ident.span, kind: ExprKind::Ident(ident) });
        }
        if self.check_elementary_type() {
            let elem = self.parse_elementary_type()?;
            let span = lo.to(self.prev_token.span);
            if elem == ElementaryType::Address(true) {
                // `address payable` in expressions
                if self.token.is_open_delim(Delimiter::Parenthesis) {
                    self.emit_err(span, "`address payable` cannot be used in an expression");
                }
            }
            return Ok(Expr { span, kind: ExprKind::Type(Type { span, kind: TypeKind::Elementary(elem) }) });
        }
        if self.check(TokenKind::OpenDelim(Delimiter::Parenthesis)) {
            let exprs = self.parse_tuple_exprs()?;
            let span = lo.to(self.prev_token.span);
            return Ok(Expr { span, kind: ExprKind::Tuple(exprs) });
        }
        if self.check(TokenKind::OpenDelim(Delimiter::Bracket)) {
            self.bump();
            let close = TokenKind::CloseDelim(Delimiter::Bracket);
            let mut v = Vec::new();
            let mut trailing = false;
            if !self.check(close) {
                loop {
                    v.push(Box::new(self.parse_expr()?));
                    if self.check(close) {
                        break;
                    }
                    self.expect(TokenKind::Comma)?;
                    if self.check(close) {
                        trailing = true;
                        break;
                    }
                }
            }
            self.expect(close)?;
            let span = lo.to(self.prev_token.span);
            if trailing {
                self.emit_err(span, "array expression components cannot be empty");
            }
            return Ok(Expr { span, kind: ExprKind::Array(v) });
        }
        if self.check_keyword(kw::New) {
            self.bump();
            let ty = self.parse_type()?;
            let span = lo.to(self.prev_token.span);
            return Ok(Expr { span, kind: ExprKind::New(ty) });
        }
        if self.check_keyword(kw::Payable) {
            self.bump();
            let args = self.parse_call_args()?;
            let span = lo.to(self.prev_token.span);
            let ok = matches!(&args.kind, CallArgsKind::Unnamed(v) if v.len() == 1);
            if !ok {
                self.emit_err(args.span, "expected exactly one unnamed argument");
            }
            return Ok(Expr { span, kind: ExprKind::Payable(args) });
        }
        if self.check_keyword(kw::Type) {
            self.bump();
            self.expect(TokenKind::OpenDelim(Delimiter::Parenthesis))?;
            let ty = self.parse_type()?;
            self.expect(TokenKind::CloseDelim(Delimiter::Parenthesis))?;
            let span = lo.to(self.prev_token.span);
            return Ok(Expr { span, kind: ExprKind::TypeCall(ty) });
        }
        if self.check_keyword(kw::Delete) {
            self.bump();
            let expr = self.parse_unary_expr()?;
            let span = lo.to(self.prev_token.span);
            return Ok(Expr { span, kind: ExprKind::Delete(Box::new(expr)) });
        }
        if self.check(TokenKind::BinOp(BinOpToken::Plus)) {
            self.emit_err(self.token.span, "unary plus is not supported");
            self.bump();
            return self.parse_unary_expr();
        }
        Err(self.expected_one_of_not_found(&[], &[]))
    }

    /// Parses `( a, b, , c )` after having checked `(`. Consumes both parens.
    fn parse_tuple_exprs(&mut self) -> PResult<Vec<Option<Box<Expr>>>> {
        self.expect(TokenKind::OpenDelim(Delimiter::Parenthesis))?;
        let close = TokenKind::CloseDelim(Delimiter::Parenthesis);
        let mut v = Vec::new();
        if self.check(close) {
            self.bump();
            return Ok(v);
        }
        loop {
            if self.check(TokenKind::Comma) {
                v.push(None);
            } else if self.check(close) {
                v.push(None);
                self.bump();
                break;
            } else {
                v.push(Some(Box::new(self.parse_expr()?)));
                if self.check(close) {
                    self.bump();
                    break;
                }
            }
            self.expect(TokenKind::Comma)?;
        }
        Ok(v)
    }

    fn parse_subdenomination_opt(&mut self, lit: &Lit) -> Option<Spanned<SubDenomination>> {
        let sub = match self.token.kind {
            TokenKind::Ident(kw::Wei) => SubDenomination::Wei,
            TokenKind::Ident(kw::Gwei) => SubDenomination::Gwei,
            TokenKind::Ident(kw::Ether) => SubDenomination::Ether,
            TokenKind::Ident(kw::Seconds) => SubDenomination::Seconds,
            TokenKind::Ident(kw::Minutes) => SubDenomination::Minutes,
            TokenKind::Ident(kw::Hours) => SubDenomination::Hours,
            TokenKind::Ident(kw::Days) => SubDenomination::Days,
            TokenKind::Ident(kw::Weeks) => SubDenomination::Weeks,
            TokenKind::Ident(kw::Years) => SubDenomination::Years,
            _ => return None,
        };
        let span = self.token.span;
        self.bump();
        match &lit.kind {
            LitKind::Number(_) | LitKind::Rational(_) => {
                if lit.symbol.as_str().starts_with("0x") {
                    self.emit_err(lit.span.to(span), "hexadecimal numbers cannot be used with unit denominations");
                } else if sub == SubDenomination::Years {
                    self.emit_err(lit.span.to(span), "using \"years\" as a unit denomination is deprecated");
                }
            }
            LitKind::Err => {}
            _ => {
                self.dcx.emit(
                    Diag::new(Level::Error, "sub-denominations are only allowed on number and rational literals")
                        .span(lit.span.to(span)),
                );
            }
        }
        Some(Spanned { span, data: sub })
    }

    /// Parses a literal (possibly multiple concatenated string literals).
    pub fn parse_lit(&mut self) -> PResult<Lit> {
        let lo = self.token.span;
        match self.token.kind {
            TokenKind::Ident(kw::True) | TokenKind::Ident(kw::False) => {
                let v = self.token.kind == TokenKind::Ident(kw::True);
                let sym = if v { kw::True } else { kw::False };
                self.bump();
                Ok(Lit { span: lo, symbol: sym, kind: LitKind::Bool(v) })
            }
            TokenKind::Literal(kind, sym) => {
                self.bump();
                match kind {
                    TLitKind::Integer => {
                        let text = sym.as_str();
                        let value = super::lit::parse_integer(text);
                        let is_address = text.starts_with("0x") && text.len() == 42;
                        let _ = is_address;
                        Ok(Lit { span: lo, symbol: sym, kind: LitKind::Number(value) })
                    }
                    TLitKind::Rational => {
                        let text = sym.as_str();
                        Ok(Lit { span: lo, symbol: sym, kind: super::lit::parse_rational(text) })
                    }
                    TLitKind::Str | TLitKind::HexStr | TLitKind::UnicodeStr => {
                        let str_kind: StrKind = kind.into();
                        let mut bytes = super::lit::str_lit_bytes(kind, sym.as_str());
                        let mut parts = vec![sym];
                        // Concatenate consecutive literals of the same kind.
                        while let TokenKind::Literal(k2, s2) = self.token.kind {
                            if k2 != kind {
                                break;
                            }
                            bytes.extend(super::lit::str_lit_bytes(k2, s2.as_str()));
                            parts.push(s2);
                            self.bump();
                        }
                        let span = lo.to(self.prev_token.span);
                        let symbol = if parts.len() == 1 {
                            sym
                        } else {
                            crate::symbol::Symbol::intern(&parts.iter().map(|s| s.as_str()).collect::<Vec<_>>().join(" "))
                        };
                        Ok(Lit { span, symbol, kind: LitKind::Str(str_kind, bytes) })
                    }
                    TLitKind::Err => Ok(Lit { span: lo, symbol: sym, kind: LitKind::Err }),
                }
            }
            _ => Err(self.expected_one_of_not_found(&[], &[])),
        }
    }
}
