//! Statement parsing.

use super::item::VarCtx;
use super::{PErr, PResult, Parser};
use crate::ast::*;
use crate::diag::{Diag, Level};
use crate::symbol::kw;
use crate::token::{Delimiter, LitKind as TLitKind, TokenKind};

impl<'a> Parser<'a> {
    pub fn parse_block(&mut self) -> PResult<Block> {
        let lo = self.token.span;
        self.expect(TokenKind::OpenDelim(Delimiter::Brace))?;
        let mut stmts = Vec::new();
        while !self.eat(TokenKind::CloseDelim(Delimiter::Brace)) {
            if self.token.is_eof() {
                // Report using the standard machinery.
                return Err(self.expected_one_of_not_found(&[], &[]));
            }
            stmts.push(self.parse_stmt()?);
        }
        Ok(Block { span: lo.to(self.prev_token.span), stmts })
    }

    pub fn parse_stmt(&mut self) -> PResult<Stmt> {
        let docs = self.parse_doc_comments();
        let lo = self.token.span;
        let kind = self.parse_stmt_kind()?;
        let span = lo.to(self.prev_token.span);
        Ok(Stmt { docs, span, kind })
    }

    fn parse_stmt_kind(&mut self) -> PResult<StmtKind> {
        if self.check(TokenKind::OpenDelim(Delimiter::Brace)) {
            return Ok(StmtKind::Block(self.parse_block()?));
        }
        if self.check_keyword(kw::Unchecked) {
            self.bump();
            return Ok(StmtKind::UncheckedBlock(self.parse_block()?));
        }
        if self.check_keyword(kw::If) {
            self.bump();
            self.expect(TokenKind::OpenDelim(Delimiter::Parenthesis))?;
            let cond = self.parse_expr()?;
            self.expect(TokenKind::CloseDelim(Delimiter::Parenthesis))?;
            let then = self.parse_stmt_no_decl()?;
            let els = if self.eat_keyword(kw::Else) { Some(Box::new(self.parse_stmt_no_decl()?)) } else { None };
            return Ok(StmtKind::If(Box::new(cond), Box::new(then), els));
        }
        if self.check_keyword(kw::While) {
            self.bump();
            self.expect(TokenKind::OpenDelim(Delimiter::Parenthesis))?;
            let cond = self.parse_expr()?;
            self.expect(TokenKind::CloseDelim(Delimiter::Parenthesis))?;
            let body = self.parse_stmt_no_decl()?;
            return Ok(StmtKind::While(Box::new(cond), Box::new(body)));
        }
        if self.check_keyword(kw::Do) {
            self.bump();
            let body = self.parse_stmt_no_decl()?;
            self.expect_keyword(kw::While)?;
            self.expect(TokenKind::OpenDelim(Delimiter::Parenthesis))?;
            let cond = self.parse_expr()?;
            self.expect(TokenKind::CloseDelim(Delimiter::Parenthesis))?;
            self.expect(TokenKind::Semi)?;
            return Ok(StmtKind::DoWhile(Box::new(body), Box::new(cond)));
        }
        if self.check_keyword(kw::For) {
            self.bump();
            self.expect(TokenKind::OpenDelim(Delimiter::Parenthesis))?;
            let init = if self.check(TokenKind::Semi) {
                self.bump();
                None
            } else {
                let lo = self.token.span;
                let kind = self.parse_simple_stmt_kind()?;
                let span = lo.to(self.prev_token.span);
                Some(Box::new(Stmt { docs: DocComments::default(), span, kind }))
            };
            let cond = if self.check(TokenKind::Semi) { None } else { Some(Box::new(self.parse_expr()?)) };
            self.expect(TokenKind::Semi)?;
            let next = if self.check(TokenKind::CloseDelim(Delimiter::Parenthesis)) {
                None
            } else {
                Some(Box::new(self.parse_expr()?))
            };
            self.expect(TokenKind::CloseDelim(Delimiter::Parenthesis))?;
            let body = self.parse_stmt_no_decl()?;
            return Ok(StmtKind::For { init, cond, next, body: Box::new(body) });
        }
        if self.check_keyword(kw::Assembly) {
            return self.parse_assembly_stmt().map(StmtKind::Assembly);
        }
        if self.check_keyword(kw::Try) {
            self.bump();
            let expr = self.parse_expr()?;
            let returns = if self.check_keyword(kw::Returns) {
                self.bump();
                Some(self.parse_parameter_list(VarCtx::TryCatch)?)
            } else {
                None
            };
            let block = self.parse_block()?;
            let mut catch = Vec::new();
            loop {
                if !self.check_keyword(kw::Catch) {
                    if catch.is_empty() {
                        return Err(self.expected_one_of_not_found(&[], &[]));
                    }
                    break;
                }
                self.bump();
                let name = self.parse_ident_opt()?;
                let args = if self.token.is_open_delim(Delimiter::Parenthesis) {
                    self.parse_parameter_list(VarCtx::TryCatch)?
                } else {
                    ParameterList { span: self.prev_token.span.shrink_to_hi(), vars: vec![] }
                };
                let block = self.parse_block()?;
                catch.push(CatchClause { name, args, block });
            }
            return Ok(StmtKind::Try(Box::new(StmtTry { expr: Box::new(expr), returns, block, catch })));
        }
        if self.check_keyword(kw::Return) {
            self.bump();
            let expr = if self.check(TokenKind::Semi) { None } else { Some(Box::new(self.parse_expr()?)) };
            self.expect(TokenKind::Semi)?;
            return Ok(StmtKind::Return(expr));
        }
        if self.check_keyword(kw::Break) {
            self.bump();
            self.expect(TokenKind::Semi)?;
            return Ok(StmtKind::Break);
        }
        if self.check_keyword(kw::Continue) {
            self.bump();
            self.expect(TokenKind::Semi)?;
            return Ok(StmtKind::Continue);
        }
        if self.check_keyword(kw::Emit) {
            self.bump();
            let path = self.parse_path()?;
            let args = self.parse_call_args()?;
            self.expect(TokenKind::Semi)?;
            return Ok(StmtKind::Emit(path, args));
        }
        if self.check_keyword(kw::Revert) && self.look_ahead(1).is_non_reserved_ident() {
            self.bump();
            let path = self.parse_path()?;
            let args = self.parse_call_args()?;
            self.expect(TokenKind::Semi)?;
            return Ok(StmtKind::Revert(path, args));
        }
        if self.check_keyword(kw::Throw) {
            let span = self.token.span;
            self.bump();
            self.emit_err(span, "`throw` statements have been removed; use `revert`, `require`, or `assert` instead");
            self.expect(TokenKind::Semi)?;
            return Ok(StmtKind::Expr(Box::new(Expr {
                span,
                kind: ExprKind::Ident(Ident::new(kw::Throw, span)),
            })));
        }
        if self.check_keyword(kw::Underscore) && self.look_ahead(1).kind == TokenKind::Semi {
            let span = self.token.span;
            self.bump();
            self.bump();
            if self.in_function_kind != Some(FunctionKind::Modifier) {
                self.emit_err(span, "placeholder statements can only be used in modifiers");
            }
            return Ok(StmtKind::Placeholder);
        }
        self.parse_simple_stmt_kind()
    }

    /// Parses a statement that is not allowed to be a variable declaration (e.g. `if` bodies).
    fn parse_stmt_no_decl(&mut self) -> PResult<Stmt> {
        let stmt = self.parse_stmt()?;
        if matches!(stmt.kind, StmtKind::DeclSingle(_) | StmtKind::DeclMulti(..)) {
            self.emit_err(stmt.span, "variable declarations can only be used inside blocks");
        }
        Ok(stmt)
    }

    /// Parses a variable declaration or expression statement (including the trailing `;`).
    fn parse_simple_stmt_kind(&mut self) -> PResult<StmtKind> {
        if self.check(TokenKind::OpenDelim(Delimiter::Parenthesis)) {
            let lo = self.token.span;
            self.bump();
            let close = TokenKind::CloseDelim(Delimiter::Parenthesis);
            let mut empty = 0usize;
            while self.eat(TokenKind::Comma) {
                empty += 1;
            }
            // Parse the first element.
            let first = self.parse_expr_or_var_decl_element(true)?;
            match first {
                ElementResult::VarDecl(var) => {
                    let mut vars: Vec<Option<VariableDefinition>> = (0..empty).map(|_| None).collect();
                    vars.push(Some(var));
                    while !self.check(close) {
                        self.expect(TokenKind::Comma)?;
                        if self.check(TokenKind::Comma) || self.check(close) {
                            vars.push(None);
                        } else {
                            let ty = self.parse_type()?;
                            let var = self.parse_variable_definition_with(VarCtx::TryCatch, ty)?;
                            vars.push(Some(var));
                        }
                    }
                    self.bump(); // `)`
                    self.expect(TokenKind::Eq)?;
                    let expr = self.parse_expr()?;
                    self.expect(TokenKind::Semi)?;
                    Ok(StmtKind::DeclMulti(vars, Box::new(expr)))
                }
                ElementResult::Expr(expr) => {
                    let mut elems: Vec<Option<Box<Expr>>> = (0..empty).map(|_| None).collect();
                    elems.push(Some(Box::new(expr)));
                    while !self.check(close) {
                        self.expect(TokenKind::Comma)?;
                        if self.check(TokenKind::Comma) || self.check(close) {
                            elems.push(None);
                        } else {
                            elems.push(Some(Box::new(self.parse_expr()?)));
                        }
                    }
                    self.bump();
                    let span = lo.to(self.prev_token.span);
                    let tuple = Expr { span, kind: ExprKind::Tuple(elems) };
                    let tuple = self.parse_postfix_expr(tuple)?;
                    let expr = self.parse_expr_with(tuple)?;
                    self.expect(TokenKind::Semi)?;
                    Ok(StmtKind::Expr(Box::new(expr)))
                }
            }
        } else {
            match self.parse_expr_or_var_decl_element(false)? {
                ElementResult::VarDecl(var) => Ok(StmtKind::DeclSingle(var)),
                ElementResult::Expr(expr) => {
                    let expr = self.parse_expr_with(expr)?;
                    self.expect(TokenKind::Semi)?;
                    Ok(StmtKind::Expr(Box::new(expr)))
                }
            }
        }
    }

    /// Parses an expression; if it is followed by a variable-declaration continuation and the
    /// expression is type-like, parses a variable declaration instead.
    fn parse_expr_or_var_decl_element(&mut self, in_tuple: bool) -> PResult<ElementResult> {
        // `mapping` and `function` types are unambiguous.
        if self.token.is_keyword(kw::Mapping)
            || (self.token.is_keyword(kw::Function) && self.look_ahead(1).is_open_delim(Delimiter::Parenthesis))
        {
            let ty = self.parse_type()?;
            let ctx = if in_tuple { VarCtx::TryCatch } else { VarCtx::Statement };
            let var = self.parse_variable_definition_with(ctx, ty)?;
            return Ok(ElementResult::VarDecl(var));
        }
        let expr = self.parse_unary_expr_pub()?;
        if self.is_var_decl_follow() {
            if let Some(ty) = expr_to_type(&expr) {
                let ctx = if in_tuple { VarCtx::TryCatch } else { VarCtx::Statement };
                let var = self.parse_variable_definition_with(ctx, ty)?;
                return Ok(ElementResult::VarDecl(var));
            }
        }
        Ok(ElementResult::Expr(expr))
    }

    fn is_var_decl_follow(&self) -> bool {
        match self.token.kind {
            TokenKind::Ident(s) => {
                !s.is_used_keyword()
                    || matches!(
                        s,
                        kw::Memory
                            | kw::Storage
                            | kw::Calldata
                            | kw::Constant
                            | kw::Immutable
                            | kw::Public
                            | kw::Private
                            | kw::Internal
                            | kw::External
                    )
            }
            _ => false,
        }
    }

    pub fn parse_unary_expr_pub(&mut self) -> PResult<Expr> {
        // Parse a full binary expression starting from a unary; this leaves `?`/assignment to the caller.
        let lhs = self.parse_unary_only()?;
        Ok(lhs)
    }

    fn parse_unary_only(&mut self) -> PResult<Expr> {
        // Reuse expression parser: parse binary expression with lowest precedence, which starts with
        // a unary expression. Since binary operators are matched without recording, this is fine.
        self.parse_binary_expr_pub()
    }

    // ---- assembly ----

    fn parse_assembly_stmt(&mut self) -> PResult<StmtAssembly> {
        self.expect_keyword(kw::Assembly)?;
        let dialect = if let TokenKind::Literal(TLitKind::Str, _) = self.token.kind {
            Some(self.parse_str_lit()?)
        } else {
            None
        };
        let mut flags = Vec::new();
        if self.token.is_open_delim(Delimiter::Parenthesis) {
            let (f, _) = self.parse_delim_comma_seq(Delimiter::Parenthesis, false, |this| this.parse_str_lit())?;
            flags = f;
        }
        for flag in &flags {
            if flag.value != "memory-safe" {
                self.emit_warn(flag.span, "unknown inline assembly flag");
            }
        }
        let block = self.parse_yul_block()?;
        Ok(StmtAssembly { dialect, flags, block })
    }
}

enum ElementResult {
    VarDecl(VariableDefinition),
    Expr(Expr),
}

/// Converts a type-like expression (`a.b[1][]`, `uint[]`) into a type.
pub fn expr_to_type(expr: &Expr) -> Option<Type> {
    match &expr.kind {
        ExprKind::Ident(ident) => Some(Type { span: expr.span, kind: TypeKind::Custom(Path { segments: vec![*ident] }) }),
        ExprKind::Member(inner, member) => {
            let inner_ty = expr_to_type(inner)?;
            match inner_ty.kind {
                TypeKind::Custom(mut path) => {
                    path.segments.push(*member);
                    Some(Type { span: expr.span, kind: TypeKind::Custom(path) })
                }
                _ => None,
            }
        }
        ExprKind::Index(inner, size) => {
            let inner_ty = expr_to_type(inner)?;
            let size = size.as_ref().map(|s| Box::new(clone_expr(s)));
            Some(Type { span: expr.span, kind: TypeKind::Array(Box::new(inner_ty), size) })
        }
        ExprKind::Type(ty) => Some(ty.clone()),
        _ => None,
    }
}

/// Deep-clones an expression (used when converting index expressions to array types).
pub fn clone_expr(e: &Expr) -> Expr {
    // We implement a structural clone via Debug-less manual recursion.
    Expr { span: e.span, kind: clone_expr_kind(&e.kind) }
}

fn clone_box(e: &Expr) -> Box<Expr> {
    Box::new(clone_expr(e))
}

fn clone_args(a: &CallArgs) -> CallArgs {
    CallArgs {
        span: a.span,
        kind: match &a.kind {
            CallArgsKind::Unnamed(v) => CallArgsKind::Unnamed(v.iter().map(|e| clone_box(e)).collect()),
            CallArgsKind::Named(v) => {
                CallArgsKind::Named(v.iter().map(|n| NamedArg { name: n.name, value: clone_box(&n.value) }).collect())
            }
        },
    }
}

fn clone_expr_kind(k: &ExprKind) -> ExprKind {
    match k {
        ExprKind::Array(v) => ExprKind::Array(v.iter().map(|e| clone_box(e)).collect()),
        ExprKind::Assign(a, op, b) => ExprKind::Assign(clone_box(a), *op, clone_box(b)),
        ExprKind::Binary(a, op, b) => ExprKind::Binary(clone_box(a), *op, clone_box(b)),
        ExprKind::Call(a, args) => ExprKind::Call(clone_box(a), clone_args(args)),
        ExprKind::CallOptions(a, v) => {
            ExprKind::CallOptions(clone_box(a), v.iter().map(|n| NamedArg { name: n.name, value: clone_box(&n.value) }).collect())
        }
        ExprKind::Delete(a) => ExprKind::Delete(clone_box(a)),
        ExprKind::Ident(i) => ExprKind::Ident(*i),
        ExprKind::Index(a, b) => ExprKind::Index(clone_box(a), b.as_ref().map(|e| clone_box(e))),
        ExprKind::Slice(a, b, c) => {
            ExprKind::Slice(clone_box(a), b.as_ref().map(|e| clone_box(e)), c.as_ref().map(|e| clone_box(e)))
        }
        ExprKind::Lit(l, s) => ExprKind::Lit(l.clone(), *s),
        ExprKind::Member(a, i) => ExprKind::Member(clone_box(a), *i),
        ExprKind::New(t) => ExprKind::New(t.clone()),
        ExprKind::Payable(args) => ExprKind::Payable(clone_args(args)),
        ExprKind::Ternary(a, b, c) => ExprKind::Ternary(clone_box(a), clone_box(b), clone_box(c)),
        ExprKind::Tuple(v) => ExprKind::Tuple(v.iter().map(|e| e.as_ref().map(|e| clone_box(e))).collect()),
        ExprKind::TypeCall(t) => ExprKind::TypeCall(t.clone()),
        ExprKind::Type(t) => ExprKind::Type(t.clone()),
        ExprKind::Unary(op, a) => ExprKind::Unary(*op, clone_box(a)),
    }
}

