//! Yul (inline assembly) parsing.

use super::{PResult, Parser};
use crate::ast::{Ident, Path};
use crate::diag::{Diag, Level};
use crate::symbol::kw;
use crate::token::{Delimiter, TokenKind};
use crate::yul::*;

impl<'a> Parser<'a> {
    pub fn parse_yul_block(&mut self) -> PResult<Block> {
        let prev = self.in_yul;
        self.in_yul = true;
        let res = self.parse_yul_block_inner();
        self.in_yul = prev;
        res
    }

    fn parse_yul_block_inner(&mut self) -> PResult<Block> {
        let lo = self.token.span;
        self.expect(TokenKind::OpenDelim(Delimiter::Brace))?;
        let mut stmts = Vec::new();
        while !self.eat(TokenKind::CloseDelim(Delimiter::Brace)) {
            if self.token.is_eof() {
                break;
            }
            stmts.push(self.parse_yul_stmt()?);
        }
        Ok(Block { span: lo.to(self.prev_token.span), stmts })
    }

    fn yul_is_ident(&self) -> bool {
        match self.token.kind {
            TokenKind::Ident(s) => !s.is_used_keyword() && !s.is_yul_keyword() && !s.is_yul_builtin(),
            _ => false,
        }
    }

    fn yul_check_ident(&mut self) -> bool {
        let is = self.yul_is_ident();
        if !is {
            self.expected_tokens.push(super::ExpectedToken::Ident);
        }
        is
    }

    fn yul_parse_ident(&mut self) -> PResult<Ident> {
        match self.token.kind {
            TokenKind::Ident(s) if self.yul_is_ident() => {
                let ident = Ident::new(s, self.token.span);
                self.bump();
                Ok(ident)
            }
            _ => Err(self.expected_ident_found_err()),
        }
    }

    fn yul_parse_path(&mut self) -> PResult<Path> {
        let first = self.yul_parse_ident()?;
        let mut segments = vec![first];
        while self.eat(TokenKind::Dot) {
            segments.push(self.yul_parse_ident()?);
        }
        Ok(Path { segments })
    }

    fn yul_check_path(&mut self) -> bool {
        let is = match self.token.kind {
            TokenKind::Ident(s) => {
                if s.is_yul_builtin() || s == kw::Address || s == kw::Return || s == kw::Byte {
                    // builtins are only valid as calls
                    self.look_ahead(1).is_open_delim(Delimiter::Parenthesis) || !s.is_used_keyword()
                } else {
                    !s.is_used_keyword() && !s.is_yul_keyword()
                }
            }
            _ => false,
        };
        if !is {
            self.expected_tokens.push(super::ExpectedToken::Path);
        }
        is
    }

    fn parse_yul_stmt(&mut self) -> PResult<Stmt> {
        let lo = self.token.span;
        let kind = self.parse_yul_stmt_kind()?;
        Ok(Stmt { span: lo.to(self.prev_token.span), kind })
    }

    fn parse_yul_stmt_kind(&mut self) -> PResult<StmtKind> {
        if self.check(TokenKind::OpenDelim(Delimiter::Brace)) {
            return Ok(StmtKind::Block(self.parse_yul_block_inner()?));
        }
        if self.check_keyword(kw::Let) {
            self.bump();
            let mut names = vec![self.yul_parse_ident()?];
            while self.eat(TokenKind::Comma) {
                names.push(self.yul_parse_ident()?);
            }
            let init = if self.eat(TokenKind::Walrus) { Some(self.parse_yul_expr()?) } else { None };
            return Ok(StmtKind::VarDecl(names, init));
        }
        if self.check_keyword(kw::If) {
            self.bump();
            let cond = self.parse_yul_expr()?;
            let body = self.parse_yul_block_inner()?;
            return Ok(StmtKind::If(cond, body));
        }
        if self.check_keyword(kw::Switch) {
            let lo = self.token.span;
            self.bump();
            let selector = self.parse_yul_expr()?;
            let mut cases = Vec::new();
            let mut default_case = None;
            loop {
                if self.check_keyword(kw::Case) {
                    self.bump();
                    let constant = if self.check_literal() {
                        self.parse_lit()?
                    } else {
                        return Err(self.expected_one_of_not_found(&[], &[]));
                    };
                    let body = self.parse_yul_block_inner()?;
                    cases.push(SwitchCase { constant, body });
                } else if self.check_keyword(kw::Default) {
                    self.bump();
                    default_case = Some(self.parse_yul_block_inner()?);
                    break;
                } else {
                    break;
                }
            }
            if cases.is_empty() && default_case.is_none() {
