            self.bump();
            return Ok(StmtKind::Break);
        }
        if self.check_keyword(kw::Continue) {
            self.bump();
            return Ok(StmtKind::Continue);
        }
        if self.check_keyword(kw::Leave) {
            self.bump();
            return Ok(StmtKind::Leave);
        }
        if self.check_keyword(kw::Function) {
            self.bump();
            let name = self.yul_parse_ident()?;
            let (parameters, _) =
                self.parse_delim_comma_seq(Delimiter::Parenthesis, true, |this| this.yul_parse_ident())?;
