            // Path, call, or assignment.
            if self.yul_is_builtin_call() || (self.yul_is_ident() && self.look_ahead(1).is_open_delim(Delimiter::Parenthesis)) {
                let call = self.parse_yul_call()?;
                return Ok(StmtKind::Expr(call));
            }
            let path = self.yul_parse_path()?;
            if self.check(TokenKind::OpenDelim(Delimiter::Parenthesis)) {
                // call with a path name (invalid, but parse)
                let name = path.last();
                let call = self.parse_yul_call_with(name)?;
                return Ok(StmtKind::Expr(call));
            }
            if self.check(TokenKind::Comma) {
                let mut paths = vec![path];
                while self.eat(TokenKind::Comma) {
                    paths.push(self.yul_parse_path()?);
                }
                self.expect(TokenKind::Walrus)?;
                let call = self.parse_yul_call()?;
                return Ok(StmtKind::AssignMulti(paths, call));
            }
            self.expect(TokenKind::Walrus)?;
            let expr = self.parse_yul_expr()?;
            return Ok(StmtKind::AssignSingle(path, expr));
        }
        Err(self.expected_one_of_not_found(&[], &[]))
    }

    fn yul_is_builtin_call(&self) -> bool {
        match self.token.kind {
            TokenKind::Ident(s) => {
                (s.is_yul_builtin() || s == kw::Address || s == kw::Return || s == kw::Byte)
                    && self.look_ahead(1).is_open_delim(Delimiter::Parenthesis)
            }
            _ => false,
        }
    }

    fn parse_yul_call(&mut self) -> PResult<ExprCall> {
        let name = match self.token.kind {
            TokenKind::Ident(s) if self.yul_is_builtin_call() => {
                let i = Ident::new(s, self.token.span);
                self.bump();
                i
            }
            _ => self.yul_parse_ident()?,
        };
        self.parse_yul_call_with(name)
    }

    fn parse_yul_call_with(&mut self, name: Ident) -> PResult<ExprCall> {
        let (arguments, _) = self.parse_delim_comma_seq(Delimiter::Parenthesis, true, |this| this.parse_yul_expr())?;
        Ok(ExprCall { name, arguments })
    }

    pub fn parse_yul_expr(&mut self) -> PResult<Expr> {
        let lo = self.token.span;
        if self.check_literal() {
            let lit = self.parse_lit()?;
            return Ok(Expr { span: lo.to(self.prev_token.span), kind: ExprKind::Lit(lit) });
        }
        if self.yul_check_path() {
            if self.yul_is_builtin_call() || self.look_ahead(1).is_open_delim(Delimiter::Parenthesis) {
                let call = self.parse_yul_call()?;
                return Ok(Expr { span: lo.to(self.prev_token.span), kind: ExprKind::Call(call) });
            }
            let path = self.yul_parse_path()?;
            return Ok(Expr { span: lo.to(self.prev_token.span), kind: ExprKind::Path(path) });
        }
        Err(self.expected_one_of_not_found(&[], &[]))
    }
}

