//! Yul AST.

use crate::ast::{Ident, Lit, Path};
use crate::span::Span;

#[derive(Debug)]
pub struct Block {
    pub span: Span,
    pub stmts: Vec<Stmt>,
}

#[derive(Debug)]
pub struct Stmt {
    pub span: Span,
    pub kind: StmtKind,
}

#[derive(Debug)]
pub enum StmtKind {
    Block(Block),
    AssignSingle(Path, Expr),
    AssignMulti(Vec<Path>, ExprCall),
    Expr(ExprCall),
    If(Expr, Block),
    For { init: Block, cond: Expr, step: Block, body: Block },
    Switch(StmtSwitch),
    Leave,
    Break,
    Continue,
    FunctionDef(Function),
    VarDecl(Vec<Ident>, Option<Expr>),
}

#[derive(Debug)]
pub struct StmtSwitch {
    pub selector: Expr,
    pub cases: Vec<SwitchCase>,
    pub default_case: Option<Block>,
}

#[derive(Debug)]
pub struct SwitchCase {
    pub constant: Lit,
    pub body: Block,
}

#[derive(Debug)]
pub struct Function {
    pub name: Ident,
    pub parameters: Vec<Ident>,
    pub returns: Vec<Ident>,
    pub body: Block,
}

#[derive(Debug)]
pub struct Expr {
    pub span: Span,
    pub kind: ExprKind,
}

#[derive(Debug)]
pub enum ExprKind {
    Path(Path),
    Call(ExprCall),
    Lit(Lit),
}

#[derive(Debug)]
pub struct ExprCall {
    pub name: Ident,
    pub arguments: Vec<Expr>,
}
