//! `pragma solidity` version requirement parsing.

use super::{PResult, Parser};
use crate::ast::*;
use crate::span::Span;
use crate::symbol::kw;
use crate::token::{BinOpToken, LitKind, TokenKind};

impl<'a> Parser<'a> {
    /// Parses the version requirement after `pragma solidity`. `ident_span` is the span of `solidity`.
    pub fn parse_semver_req(&mut self, ident_span: Span, pragma_lo: Span) -> PResult<Vec<VersionReq>> {
        if self.token.kind == TokenKind::Semi {
            self.emit_err(ident_span.to(self.token.span), "empty version requirement");
            return Ok(vec![]);
        }
        let mut reqs = Vec::new();
        let mut consumed_semi = false;
        loop {
            let lo = self.token.span;
            let op = self.parse_version_op_opt();
            let (v1, semi) = self.parse_version_number();
            consumed_semi |= semi;
            if self.eat(TokenKind::BinOp(BinOpToken::Minus)) {
                let (v2, semi) = self.parse_version_number();
                consumed_semi |= semi;
                reqs.push(VersionReq::Range(lo.to(self.prev_token.span), v1, v2));
                if self.check(TokenKind::OrOr) {
                    self.bump();
                    reqs.push(VersionReq::Or);
                    continue;
                }
                if consumed_semi || !self.check(TokenKind::Semi) {
                    self.emit_err(pragma_lo.to(self.prev_token.span), "ranges can only be combined using the || operator");
                    if !consumed_semi {
                        self.expect(TokenKind::Semi)?;
                    }
                    return Ok(reqs);
                }
                break;
            }
            reqs.push(VersionReq::Op(lo.to(self.prev_token.span), op.unwrap_or(VersionOp::Exact), v1));
            if consumed_semi {
                return Ok(reqs);
            }
            if self.check(TokenKind::OrOr) {
                self.bump();
                reqs.push(VersionReq::Or);
                continue;
            }
            if self.check(TokenKind::Semi) {
                break;
            }
            if self.token.is_eof() {
                return Err(self.expected_one_of_not_found(&[], &[]));
            }
            // Another requirement (implicit AND).
        }
        self.expect(TokenKind::Semi)?;
        Ok(reqs)
    }

    fn parse_version_op_opt(&mut self) -> Option<VersionOp> {
        let op = match self.token.kind {
            TokenKind::BinOp(BinOpToken::Caret) => VersionOp::Caret,
            TokenKind::Tilde => VersionOp::Tilde,
            TokenKind::Eq => VersionOp::Exact,
            TokenKind::Lt => VersionOp::Lt,
            TokenKind::Le => VersionOp::Le,
            TokenKind::Gt => VersionOp::Gt,
            TokenKind::Ge => VersionOp::Ge,
            _ => return None,
        };
        self.bump();
        Some(op)
    }

    /// Parses a version number from tokens. Returns the version and whether a `;` was consumed
    /// as part of error recovery.
    fn parse_version_number(&mut self) -> (Version, bool) {
        let lo = self.token.span;
        let mut comps: Vec<Option<u64>> = Vec::new();
        let mut consumed_semi = false;
        let mut push_num = |this: &mut Self, s: &str, span: Span, comps: &mut Vec<Option<u64>>| {
            match s.parse::<u64>() {
                Ok(n) => comps.push(Some(n)),
                Err(_) => {
                    this.emit_err(span, "version number too large");
                    comps.push(Some(0));
                }
            }
        };
        let mut ok = true;
        match self.token.kind {
            TokenKind::Literal(LitKind::Integer, sym) => {
                let s = sym.as_str();
                if s.starts_with("0x") {
                    ok = false;
                } else {
                    push_num(self, s, self.token.span, &mut comps);
                    self.bump();
                }
            }
            TokenKind::Literal(LitKind::Rational, sym) => {
                let s = sym.as_str();
                if s.starts_with('.') || s.contains(['e', 'E']) {
                    ok = false;
                } else {
                    let span = self.token.span;
                    let mut parts = s.split('.');
                    if let Some(a) = parts.next() {
                        push_num(self, a, span, &mut comps);
                    }
                    if let Some(b) = parts.next() {
                        push_num(self, b, span, &mut comps);
                    }
                    self.bump();
                }
            }
            TokenKind::Ident(s) if s.as_str() == "x" || s.as_str() == "X" => {
                comps.push(None);
                self.bump();
            }
            TokenKind::BinOp(BinOpToken::Star) => {
                comps.push(None);
                self.bump();
            }
            _ => ok = false,
        }
        if !ok {
            let span = self.token.span;
            self.emit_err(span, "expected version number");
            let is_semi = self.token.kind == TokenKind::Semi;
            let skip_first = matches!(self.token.kind, TokenKind::Ident(_) | TokenKind::Literal(..));
            let next_is_eof = self.look_ahead(1).is_eof();
            if !self.token.is_eof() {
                let trailing = if skip_first && span.len() > 1 { span.with_lo(span.lo + 1) } else { span };
                if !(skip_first && span.len() <= 1) && !(next_is_eof && !is_semi) {
                    self.emit_err(trailing, "unexpected trailing characters");
                }
                self.bump();
                consumed_semi = is_semi;
            }
            return (Version { span: lo.to(self.prev_token.span), major: 0, minor: None, patch: None }, consumed_semi);
        }
        // Additional components: `.N` rationals or `.` followed by integer/wildcard.
        loop {
            match self.token.kind {
                TokenKind::Literal(LitKind::Rational, sym) if sym.as_str().starts_with('.') && comps.len() < 3 => {
                    let s = &sym.as_str()[1..];
                    if s.contains(['e', 'E']) {
                        break;
                    }
                    let span = self.token.span;
                    push_num(self, s, span, &mut comps);
                    self.bump();
                }
                TokenKind::Dot if comps.len() < 3 => {
                    let next = self.look_ahead(1);
                    match next.kind {
                        TokenKind::Literal(LitKind::Integer, sym) if !sym.as_str().starts_with("0x") => {
                            self.bump();
                            let span = self.token.span;
                            push_num(self, sym.as_str(), span, &mut comps);
                            self.bump();
                        }
                        TokenKind::Ident(s) if s.as_str() == "x" || s.as_str() == "X" => {
                            self.bump();
                            self.bump();
                            comps.push(None);
                        }
                        TokenKind::BinOp(BinOpToken::Star) => {
                            self.bump();
                            self.bump();
                            comps.push(None);
                        }
                        _ => {
                            self.bump();
                            let span = self.token.span;
                            self.emit_err(span, "expected version number");
                            break;
                        }
                    }
                }
                _ => break,
            }
        }
        let version = Version {
            span: lo.to(self.prev_token.span),
            major: comps.first().copied().flatten().unwrap_or(0),
            minor: comps.get(1).copied().flatten(),
            patch: comps.get(2).copied().flatten(),
        };
        (version, consumed_semi)
    }
}

