pub const UNSTABLE_HELP: &str = "List of all unstable flags.
WARNING: these are completely unstable, and may change at any time!

Options:
      -Zui-testing
          Enables UI testing mode

      -Ztrack-diagnostics
          Prints a note for every diagnostic that is emitted with the creation and emission location.

          This is enabled by default on debug builds.

      -Zparse-yul
          Enables parsing Yul files for testing

      -Zno-resolve-imports
          Disables import resolution

      -Zdump=<KIND[=PATHS...]>
          Print additional information about the compiler's internal state.

          Valid kinds are `ast` and `hir`.

      -Zast-stats
          Print AST stats

      -Zspan-visitor
          Run the span visitor after parsing

      -Zprint-max-storage-sizes
          Print contracts' max storage sizes

      -Ztypeck
          Type check the program. WIP

      -Zhelp
          Print help";

#[derive(Debug, Default, Clone)]
pub struct Unstable {
    pub ui_testing: bool,
    pub track_diagnostics: bool,
    pub parse_yul: bool,
    pub no_resolve_imports: bool,
    pub dump: Option<(String, Vec<String>)>,
    pub ast_stats: bool,
    pub span_visitor: bool,
    pub print_max_storage_sizes: bool,
    pub typeck: bool,
}

/// Parses `-Z` flags. Returns Err(message) on failure (message already formatted as clap would).
pub fn parse_unstable(flags: &[String]) -> Result<Unstable, String> {
    let mut u = Unstable::default();
    let mut seen_dump = false;
    for flag in flags {
        let (name, value) = match flag.split_once('=') {
            Some((n, v)) => (n, Some(v)),
            None => (flag.as_str(), None),
        };
        let no_value = |name: &str| -> Result<(), String> {
            if value.is_some() {
                return Err(format!(
                    "error:  unexpected value '{}' for '-Z{}' found; no more were expected\n\nUsage: solar [OPTIONS]\n\nFor more information, try '-Zhelp'.",
                    value.unwrap(),
                    name
                ));
            }
            Ok(())
        };
        match name {
            "help" => {
                return Err(format!("error: {UNSTABLE_HELP}\n\nUsage: solar [OPTIONS] [INPUT]...\n\nFor more information, try '--help'."));
            }
            "ui-testing" => {
                no_value(name)?;
                u.ui_testing = true
            }
            "track-diagnostics" => {
                no_value(name)?;
                u.track_diagnostics = true
            }
            "parse-yul" => {
                no_value(name)?;
                u.parse_yul = true
            }
            "no-resolve-imports" => {
                no_value(name)?;
                u.no_resolve_imports = true
            }
            "ast-stats" => {
                no_value(name)?;
                u.ast_stats = true
            }
            "span-visitor" => {
                no_value(name)?;
                u.span_visitor = true
            }
            "print-max-storage-sizes" => {
                no_value(name)?;
                u.print_max_storage_sizes = true
            }
            "typeck" => {
                no_value(name)?;
                u.typeck = true
            }
            "dump" => {
                if seen_dump {
                    return Err(
                        "error:  the argument '-Zdump=<KIND[=PATHS...]>' cannot be used multiple times\n\nUsage: solar [OPTIONS]\n\nFor more information, try '-Zhelp'."
                            .to_string(),
                    );
                }
                seen_dump = true;
                let Some(value) = value else {
                    return Err(
                        "error:  a value is required for '-Zdump=<KIND[=PATHS...]>' but none was supplied\n\nFor more information, try '-Zhelp'."
                            .to_string(),
                    );
                };
                let mut parts = value.split('=');
                let kind = parts.next().unwrap_or("");
                if kind != "ast" && kind != "hir" {
                    return Err(format!(
                        "error:  invalid value '{value}' for '-Zdump=<KIND[=PATHS...]>': Matching variant not found\n\nFor more information, try '-Zhelp'."
                    ));
                }
                let paths: Vec<String> = parts.next().map(|p| p.split(',').map(|s| s.to_string()).collect()).unwrap_or_default();
                u.dump = Some((kind.to_string(), paths));
            }
            _ => {
                return Err(format!(
                    "error:  unexpected argument '-Z{flag}' found\n\nUsage: solar [OPTIONS]\n\nFor more information, try '-Zhelp'."
                ));
            }
        }
    }
    Ok(u)
}
EOF
echo ok"}

