#[derive(Debug, Clone)]
pub struct Remapping {
    pub context: Option<String>,
    pub prefix: String,
    pub path: String,
}

fn parse_remapping(s: &str) -> Option<Remapping> {
    let (prefix_part, path) = s.split_once('=')?;
    let (context, prefix) = match prefix_part.split_once(':') {
        Some((c, p)) => (Some(c.to_string()), p.to_string()),
        None => (None, prefix_part.to_string()),
    };
    if prefix.is_empty() {
        return None;
    }
    Some(Remapping { context, prefix, path: path.to_string() })
}

fn is_terminal(fd: i32) -> bool {
    extern "C" {
        fn isatty(fd: i32) -> i32;
    }
    unsafe { isatty(fd) == 1 }
}

fn main() {
    let code = run();
    std::process::exit(code);
}

fn run() -> i32 {
    let cmd = cli::command();
    let matches = match cmd.try_get_matches() {
        Ok(m) => m,
        Err(e) => {
            let _ = e.print();
            return e.exit_code();
        }
    };

    let unstable_flags: Vec<String> =
        matches.get_many::<String>("unstable").map(|v| v.cloned().collect()).unwrap_or_default();
    let unstable = match cli::parse_unstable(&unstable_flags) {
        Ok(u) => u,
        Err(msg) => {
            let is_help = unstable_flags.iter().any(|f| f == "help");
            if is_help {
                eprintln!("{msg}");
                return 0;
            }
            eprintln!("{msg}\n\nUsage: solar [OPTIONS] [INPUT]...\n\nFor more information, try '--help'.");
            return 2;
        }
    };

    let mut inputs = Vec::new();
    let mut remappings = Vec::new();
    if let Some(vals) = matches.get_many::<String>("input") {
        for v in vals {
            if v.contains('=') {
                if let Some(r) = parse_remapping(v) {
                    remappings.push(r);
                    continue;
                }
            }
            inputs.push(v.clone());
        }
    }

    let color = match matches.get_one::<String>("color").map(|s| s.as_str()) {
        Some("always") => ColorChoice::Always,
        Some("never") => ColorChoice::Never,
        _ => ColorChoice::Auto,
    };
    let error_format = match matches.get_one::<String>("error_format").map(|s| s.as_str()) {
        Some("json") => ErrorFormat::Json,
        Some("rustc-json") => ErrorFormat::RustcJson,
        _ => ErrorFormat::Human,
    };
    let error_format_human = match matches.get_one::<String>("error_format_human").map(|s| s.as_str()) {
        Some("ascii") => HumanStyle::Ascii,
        Some("short") => HumanStyle::Short,
        _ => HumanStyle::Unicode,
    };

    let opts = Opts {
        inputs,
        remappings,
        threads: *matches.get_one::<usize>("threads").unwrap_or(&1),
        evm_version: matches.get_one::<String>("evm_version").cloned().unwrap_or_default(),
        stop_after: matches.get_one::<String>("stop_after").cloned(),
        out_dir: matches.get_one::<String>("out_dir").map(PathBuf::from),
        emit: matches.get_many::<String>("emit").map(|v| v.cloned().collect()).unwrap_or_default(),
        unstable,
        base_path: matches.get_one::<String>("base_path").map(PathBuf::from),
        include_paths: matches.get_many::<String>("include_path").map(|v| v.map(PathBuf::from).collect()).unwrap_or_default(),
        allow_paths: matches.get_many::<String>("allow_paths").map(|v| v.map(PathBuf::from).collect()).unwrap_or_default(),
        color,
        verbose: matches.get_flag("verbose"),
        pretty_json: matches.get_flag("pretty_json"),
        pretty_json_err: matches.get_flag("pretty_json_err"),
        error_format,
        error_format_human,
        diagnostic_width: matches.get_one::<usize>("diagnostic_width").copied(),
        no_warnings: matches.get_flag("no_warnings"),
    };

    let use_color = match opts.color {
        ColorChoice::Always => true,
        ColorChoice::Never => false,
        ColorChoice::Auto => is_terminal(2) && std::env::var_os("NO_COLOR").is_none(),
    };

    let source_map = Rc::new(SourceMap::new());
    let dcx = DiagCtxt::new(
        source_map.clone(),
        EmitterConfig {
            format: opts.error_format,
            style: opts.error_format_human,
            color: use_color,
            pretty_json: opts.pretty_json_err,
            width: opts.diagnostic_width,
            ui_testing: opts.unstable.ui_testing,
        },
        opts.no_warnings,
    );

    let result = compile(&opts, &dcx, &source_map);
    let had_errors = dcx.print_error_count();
    if had_errors || result.is_err() {
        if result.is_err() && !had_errors {
            return 0;
        }
        return 1;
    }
    0
}

/// Compilation pipeline.
fn compile(opts: &Opts, dcx: &DiagCtxt, sm: &SourceMap) -> Result<(), ()> {
    if opts.inputs.is_empty() {
        dcx.emit(
            Diag::new(Level::Error, "no files found")
                .note("if you wish to use the standard input, please specify `-` explicitly"),
        );
        return Err(());
    }

    let mut resolver = sema::files::FileResolver::new(opts);
    let mut sources = sema::files::ParsedSources::default();

    // Load input files.
    let mut had_stdin = false;
    let mut initial: Vec<Rc<SourceFile>> = Vec::new();
    for input in &opts.inputs {
        if input == "-" {
            if had_stdin {
                continue;
            }
            had_stdin = true;
            match resolver.load_stdin(sm) {
                Ok(f) => initial.push(f),
                Err(e) => {
                    dcx.emit(Diag::new(Level::Error, e));
                    return Err(());
                }
            }
        } else {
            match resolver.load_input(sm, Path::new(input)) {
                Ok(Some(f)) => initial.push(f),
                Ok(None) => {}
                Err(e) => {
                    dcx.emit(Diag::new(Level::Error, e));
                    return Err(());
                }
            }
        }
    }
    if dcx.has_errors() {
        return Err(());
    }

    // Parse all files, resolving imports recursively.
    let mut queue: Vec<Rc<SourceFile>> = initial;
    let mut idx = 0;
    while idx < queue.len() {
        let file = queue[idx].clone();
        idx += 1;
        let ast = parse_file(dcx, &file, opts);
        let mut imports = Vec::new();
        if let Some(ast) = &ast {
            if !opts.unstable.no_resolve_imports {
                for item in &ast.items {
                    if let ast::ItemKind::Import(import) = &item.kind {
                        match resolver.resolve_import(sm, &file, &import.path.value) {
                            Ok(f) => {
                                if !queue.iter().any(|q| Rc::ptr_eq(q, &f)) {
                                    queue.push(f.clone());
                                }
                                imports.push((item.span, f));
                            }
                            Err(e) => {
                                dcx.emit(Diag::new(Level::Error, e).span(import.path.span));
                            }
                        }
                    }
                }
            }
        }
        sources.push(sema::files::Source { file, ast, imports });
    }

    if opts.unstable.ast_stats {
        for s in &sources.sources {
            if let Some(ast) = &s.ast {
                sema::ast_stats::print_ast_stats(ast);
            }
        }
    }
    if let Some((kind, paths)) = &opts.unstable.dump {
        if kind == "ast" {
            sema::dump::dump_ast(&sources, paths, sm);
        }
    }

    if dcx.has_errors() {
        return Err(());
    }
    if opts.stop_after.is_some() {
        return Ok(());
    }

    // AST validation.
    for s in &sources.sources {
        if let Some(ast) = &s.ast {
            sema::ast_passes::validate(dcx, ast);
        }
    }
    if dcx.has_errors() {
        return Err(());
    }

    // Lowering + resolution.
    let hir = sema::lower::lower(dcx, &sources);
    if let Some((kind, _)) = &opts.unstable.dump {
        if kind == "hir" && !dcx.has_errors() {
            sema::dump::dump_hir(&hir, sm);
        }
    }
    if dcx.has_errors() {
        return Err(());
    }

    // Analysis.
    sema::analysis::analyze(dcx, &hir);
    if dcx.has_errors() {
        return Err(());
    }

    if opts.unstable.print_max_storage_sizes {
        sema::analysis::print_max_storage_sizes(dcx, &hir);
    }

    // Emit.
    if !opts.emit.is_empty() {
        let output = abi::emit(&hir, &opts.emit, sm);
        let text = if opts.pretty_json {
            serde_json::to_string_pretty(&output).unwrap()
        } else {
            serde_json::to_string(&output).unwrap()
        };
        if let Some(dir) = &opts.out_dir {
            let path = dir.join("combined.json");
            if let Err(e) = std::fs::write(&path, format!("{text}\n")) {
                dcx.emit(Diag::new(Level::Error, format!("failed to write to output: {e}")));
                return Err(());
            }
        } else {
            use std::io::Write;
            let stdout = std::io::stdout();
            let mut lock = stdout.lock();
            let _ = lock.write_all(text.as_bytes());
            let _ = lock.flush();
        }
    }
    Ok(())
}

fn parse_file(dcx: &DiagCtxt, file: &Rc<SourceFile>, _opts: &Opts) -> Option<ast::SourceUnit> {
    let tokens = lexer::Lexer::new(dcx, &file.src, file.start_pos).into_tokens();
    let mut parser = parser::Parser::new(dcx, tokens);
    let unit = parser.parse_source_unit();
    Some(unit)
}

