            return rel.to_path_buf();
        }
        abs.to_path_buf()
    }

    pub fn load_stdin(&mut self, sm: &SourceMap) -> Result<Rc<SourceFile>, String> {
        use std::io::Read;
        let mut buf = Vec::new();
        std::io::stdin().read_to_end(&mut buf).map_err(|e| format!("couldn't read stdin: {e}"))?;
        let src = String::from_utf8(buf).map_err(|_| "couldn't read stdin: stream did not contain valid UTF-8".to_string())?;
        if let Some(f) = sm.get_by_name(&FileName::Stdin) {
            return Ok(f);
        }
        Ok(sm.new_source_file(FileName::Stdin, src))
    }

    fn read_file(&self, path: &Path, display: &str) -> Result<String, String> {
        let bytes = std::fs::read(path).map_err(|e| format!("couldn't read {display}: {e}"))?;
        String::from_utf8(bytes).map_err(|_| format!("couldn't read {display}: stream did not contain valid UTF-8"))
    }

    fn load_abs(&mut self, sm: &SourceMap, abs: &Path, display: &str) -> Result<Rc<SourceFile>, String> {
        let canonical = std::fs::canonicalize(abs).unwrap_or_else(|_| abs.to_path_buf());
        if let Some(f) = self.loaded.get(&canonical) {
            return Ok(f.clone());
        }
        let src = self.read_file(abs, display)?;
        let name = self.display_name(abs);
        let file = sm.new_source_file(FileName::Real(name), src);
        self.loaded.insert(canonical, file.clone());
        Ok(file)
    }

    /// Loads a command-line input file. Returns `Ok(None)` if the input is a duplicate.
    pub fn load_input(&mut self, sm: &SourceMap, path: &Path) -> Result<Option<Rc<SourceFile>>, String> {
        let norm = normalize(path);
        let display = norm.display().to_string();
        if norm.is_absolute() {
            if !norm.exists() {
                return Err(format!("file {display} not found"));
            }
            return self.load_abs(sm, &norm, &display).map(Some);
        }
        if norm.starts_with("..") {
            return Err(format!("file {display} not found"));
        }
        let candidate = self.base_path.join(&norm);
        if candidate.exists() {
            return self.load_abs(sm, &candidate, &display).map(Some);
        }
        for inc in &self.opts.include_paths {
            let inc = if inc.is_absolute() { normalize(inc) } else { normalize(&self.cwd.join(inc)) };
            let c = inc.join(&norm);
            if c.exists() {
                return self.load_abs(sm, &c, &display).map(Some);
            }
        }
        Err(format!("file {display} not found"))
    }

    fn apply_remappings(&self, source_unit_name: &str, path: &str) -> String {
        let mut best: Option<&crate::Remapping> = None;
        let mut best_ctx_len = 0usize;
        let mut best_prefix_len = 0usize;
        for r in &self.opts.remappings {
            if let Some(ctx) = &r.context {
                if !source_unit_name.starts_with(ctx.as_str()) {
                    continue;
                }
                if ctx.len() < best_ctx_len {
                    continue;
                }
            } else if best_ctx_len > 0 {
                continue;
            }
            if !path.starts_with(&r.prefix) {
                continue;
            }
            let ctx_len = r.context.as_ref().map_or(0, |c| c.len());
            if ctx_len > best_ctx_len || (ctx_len == best_ctx_len && r.prefix.len() >= best_prefix_len) {
                best = Some(r);
                best_ctx_len = ctx_len;
                best_prefix_len = r.prefix.len();
            }
        }
        match best {
            Some(r) => format!("{}{}", r.path, &path[r.prefix.len()..]),
            None => path.to_string(),
        }
    }

    pub fn resolve_import(&mut self, sm: &SourceMap, from: &Rc<SourceFile>, path: &str) -> Result<Rc<SourceFile>, String> {
        let from_name = match &from.file_name_path() {
            Some(p) => p.clone(),
            None => PathBuf::new(),
        };
        let source_unit_name = from_name.display().to_string();
        let resolved: PathBuf = if path.starts_with("./") || path.starts_with("../") {
            let parent = from_name.parent().map(|p| p.to_path_buf()).unwrap_or_default();
            normalize(&parent.join(path))
        } else {
            let remapped = self.apply_remappings(&source_unit_name, path);
            normalize(Path::new(&remapped))
        };
        let display = resolved.display().to_string();
        if resolved.is_absolute() {
            if !resolved.exists() {
                return Err(format!("file {display} not found"));
            }
            return self.load_abs(sm, &resolved, &display);
        }
        if resolved.starts_with("..") {
            return Err(format!("file {display} not found"));
        }
        let candidate = self.base_path.join(&resolved);
        if candidate.exists() {
            return self.load_abs(sm, &candidate, &display);
        }
        for inc in &self.opts.include_paths {
            let inc = if inc.is_absolute() { normalize(inc) } else { normalize(&self.cwd.join(inc)) };
            let c = inc.join(&resolved);
            if c.exists() {
                return self.load_abs(sm, &c, &display);
            }
        }
        Err(format!("file {display} not found"))
    }
}

impl SourceFile {
    pub fn file_name_path(&self) -> Option<PathBuf> {
        match &self.name {
            FileName::Real(p) => Some(p.clone()),
            _ => None,
        }
    }
}
