use super::hir::{ItemId, Res};
use crate::symbol::{kw, Symbol};
use std::collections::HashMap;

#[derive(Default, Clone)]
pub struct Scope {
    pub names: HashMap<Symbol, Vec<Res>>,
    /// Declaration order (for deterministic iteration).
    pub order: Vec<Symbol>,
}

impl Scope {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn get(&self, name: Symbol) -> Option<&Vec<Res>> {
        self.names.get(&name)
    }

    /// Declares `res` under `name`. Returns `Err(existing)` on a non-overloadable conflict.
    pub fn declare(&mut self, name: Symbol, res: Res, hir_kind: impl Fn(Res) -> ResKind) -> Result<(), Res> {
        if let Some(existing) = self.names.get_mut(&name) {
            if existing.contains(&res) {
                return Ok(());
            }
            let new_kind = hir_kind(res);
            for &e in existing.iter() {
                let ek = hir_kind(e);
                let ok = match (new_kind, ek) {
                    (ResKind::Function, ResKind::Function) => true,
                    (ResKind::Modifier, ResKind::Modifier) => true,
                    (ResKind::Event, ResKind::Event) => true,
                    _ => false,
                };
                if !ok {
                    return Err(e);
                }
            }
            existing.push(res);
            Ok(())
        } else {
            self.names.insert(name, vec![res]);
            self.order.push(name);
            Ok(())
        }
    }

    pub fn declare_unchecked(&mut self, name: Symbol, res: Res) {
        let e = self.names.entry(name).or_insert_with(|| {
            Vec::new()
        });
        if e.is_empty() {
            self.order.push(name);
        }
        if !e.contains(&res) {
            e.push(res);
        }
    }

    pub fn iter(&self) -> impl Iterator<Item = (Symbol, &Vec<Res>)> {
        self.order.iter().map(move |s| (*s, &self.names[s]))
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ResKind {
    Function,
    Modifier,
    Event,
    Other,
}

