//! AST -> HIR lowering with name resolution.

use super::files::ParsedSources;
use super::hir::*;
use super::scope::{builtin_scope, ResKind, Scope};
use crate::ast::{self, ContractKind, FunctionKind, Ident, StateMutability, Visibility};
use crate::diag::{Diag, DiagCtxt, Level};
use crate::span::Span;
use crate::symbol::{kw, Symbol};
use std::collections::{HashMap, HashSet};

pub struct LowerCtx<'a, 'd> {
    pub dcx: &'d DiagCtxt,
    pub hir: Hir<'a>,
    pub builtins: Scope,
    pub source_scopes: Vec<Scope>,
    pub contract_scopes: Vec<Scope>,
    /// Exported names per source (own items + imported).
    pub source_exports: Vec<Scope>,
    /// Names already reported as duplicates (contract id, symbol) to avoid double reports.
    reported_dups: HashSet<(usize, Symbol)>,
}

pub fn lower<'a>(dcx: &DiagCtxt, sources: &'a ParsedSources) -> Hir<'a> {
    let order = topo_order(sources);
    let mut cx = LowerCtx {
        dcx,
        hir: Hir {
            sources: Vec::new(),
            contracts: Vec::new(),
            functions: Vec::new(),
            structs: Vec::new(),
            enums: Vec::new(),
            udvts: Vec::new(),
            events: Vec::new(),
            errors: Vec::new(),
            variables: Vec::new(),
        },
        builtins: builtin_scope(),
        source_scopes: Vec::new(),
        contract_scopes: Vec::new(),
        source_exports: Vec::new(),
        reported_dups: HashSet::new(),
    };
    // Map from parsed source index to hir source id.
    let mut id_map: HashMap<usize, SourceId> = HashMap::new();
    for (new_id, &old) in order.iter().enumerate() {
        id_map.insert(old, new_id);
    }
    // Collect.
    for &old in &order {
        let s = &sources.sources[old];
        let sid = cx.hir.sources.len();
        let imports: Vec<(Span, SourceId)> = s
            .imports
            .iter()
            .filter_map(|(span, f)| sources.index_of(f).and_then(|i| id_map.get(&i)).map(|&i| (*span, i)))
            .collect();
        cx.hir.sources.push(Source { file: s.file.clone(), ast: s.ast.as_ref(), items: Vec::new(), imports });
        if let Some(ast) = &s.ast {
            let mut items = Vec::new();
            for item in &ast.items {
                if let Some(id) = cx.collect_item(sid, None, item) {
                    items.push(id);
                }
            }
            cx.hir.sources[sid].items = items;
        }
    }
    // Source scopes.
    cx.source_scopes = vec![Scope::new(); cx.hir.sources.len()];
    cx.source_exports = vec![Scope::new(); cx.hir.sources.len()];
    for sid in 0..cx.hir.sources.len() {
        cx.build_source_scope(sid);
    }
    // Contracts.
    cx.contract_scopes = vec![Scope::new(); cx.hir.contracts.len()];
    for cid in 0..cx.hir.contracts.len() {
        cx.lower_contract_header(cid);
    }
    // Resolve types and bodies.
    cx.resolve_all();
    // Post checks.
    super::checks::post_resolution_checks(&mut cx);
    cx.hir
}

/// DFS post-order of the import graph.
fn topo_order(sources: &ParsedSources) -> Vec<usize> {
    let n = sources.sources.len();
    let mut visited = vec![false; n];
    let mut order = Vec::new();
    fn visit(sources: &ParsedSources, i: usize, visited: &mut Vec<bool>, order: &mut Vec<usize>) {
        if visited[i] {
            return;
        }
        visited[i] = true;
        for (_, f) in &sources.sources[i].imports {
            if let Some(j) = sources.index_of(f) {
                visit(sources, j, visited, order);
            }
        }
        order.push(i);
    }
    for i in 0..n {
        visit(sources, i, &mut visited, &mut order);
    }
    order
}

impl<'a, 'd> LowerCtx<'a, 'd> {
    fn res_kind(&self, res: Res) -> ResKind {
        match res {
            Res::Item(ItemId::Function(f)) => {
                if self.hir.functions[f].kind == FunctionKind::Modifier {
                    ResKind::Modifier
                } else {
                    ResKind::Function
                }
            }
            Res::Item(ItemId::Event(_)) => ResKind::Event,
            _ => ResKind::Other,
        }
    }

    fn emit_already_declared(&self, name: Ident, prev_span: Span) {
        self.dcx.emit(
            Diag::new(Level::Error, format!("identifier `{}` already declared", name.name))
                .span(name.span)
                .span_note(prev_span, "previous declaration declared here"),
        );
    }

    fn res_span(&self, res: Res) -> Span {
        match res {
            Res::Item(id) => match id {
                ItemId::Variable(v) => self.hir.variables[v].name.map(|n| n.span).unwrap_or(self.hir.variables[v].span),
                ItemId::Function(f) => self.hir.functions[f].name.map(|n| n.span).unwrap_or(self.hir.functions[f].span),
                _ => self.hir.item_name(id).map(|n| n.span).unwrap_or(self.hir.item_span(id)),
            },
            _ => Span::DUMMY,
        }
    }

    // ---- collection ----

    fn collect_item(&mut self, sid: SourceId, contract: Option<ContractId>, item: &'a ast::Item) -> Option<ItemId> {
        match &item.kind {
            ast::ItemKind::Pragma(_) | ast::ItemKind::Import(_) | ast::ItemKind::Using(_) => None,
            ast::ItemKind::Contract(c) => {
                let cid = self.hir.contracts.len();
                self.hir.contracts.push(Contract {
                    source: sid,
                    span: item.span,
                    name: c.name,
                    kind: c.kind,
                    ast: c,
                    bases: Vec::new(),
                    linearized_bases: Vec::new(),
                    ctor: None,
                    fallback: None,
                    receive: None,
                    items: Vec::new(),
                });
                let mut items = Vec::new();
                for sub in &c.body {
                    if let Some(id) = self.collect_item(sid, Some(cid), sub) {
                        items.push(id);
                    }
                }
                self.hir.contracts[cid].items = items;
                Some(ItemId::Contract(cid))
            }
            ast::ItemKind::Function(f) => {
                let fid = self.hir.functions.len();
                let visibility = f.header.visibility.map(|v| v.data).unwrap_or(match f.kind {
                    FunctionKind::Modifier => Visibility::Internal,
                    FunctionKind::Constructor => Visibility::Public,
                    _ if contract.is_none() => Visibility::Internal,
                    _ => Visibility::Public,
                });
                let state_mutability = f.header.state_mutability.map(|s| s.data).unwrap_or(StateMutability::NonPayable);
                self.hir.functions.push(Function {
                    source: sid,
                    contract,
                    span: item.span,
                    name: f.header.name,
                    kind: f.kind,
                    visibility,
                    state_mutability,
                    marked_virtual: f.header.virtual_.is_some(),
                    override_: f.header.override_.as_ref().map(|o| o.span),
                    overrides: Vec::new(),
                    parameters: Vec::new(),
                    returns: Vec::new(),
                    has_body: f.body.is_some(),
                    ast: Some(f),
                    gettee: None,
                    modifiers: Vec::new(),
                });
                let params: Vec<VariableId> = f
                    .header
                    .parameters
                    .vars
                    .iter()
                    .map(|v| self.collect_var(sid, contract, Some(fid), v, VarKind::FunctionParam))
                    .collect();
                let returns: Vec<VariableId> = f
                    .header
                    .returns
                    .as_ref()
                    .map(|r| {
                        r.vars.iter().map(|v| self.collect_var(sid, contract, Some(fid), v, VarKind::FunctionReturn)).collect()
                    })
                    .unwrap_or_default();
                self.hir.functions[fid].parameters = params;
                self.hir.functions[fid].returns = returns;
                Some(ItemId::Function(fid))
            }
            ast::ItemKind::Variable(v) => {
                let kind = if v.mutability.map(|m| m.data) == Some(ast::VarMut::Constant) && contract.is_none() {
                    VarKind::Constant
                } else {
                    VarKind::State
                };
                let vid = self.collect_var(sid, contract, None, v, kind);
                Some(ItemId::Variable(vid))
            }
            ast::ItemKind::Struct(s) => {
                let id = self.hir.structs.len();
                self.hir.structs.push(Struct { source: sid, contract, span: item.span, name: s.name, fields: Vec::new(), ast: s });
                let fields: Vec<VariableId> =
                    s.fields.iter().map(|v| self.collect_var(sid, contract, None, v, VarKind::Struct)).collect();
                self.hir.structs[id].fields = fields;
                Some(ItemId::Struct(id))
            }
            ast::ItemKind::Enum(e) => {
                let id = self.hir.enums.len();
                self.hir.enums.push(Enum { source: sid, contract, span: item.span, name: e.name, variants: e.variants.clone() });
                Some(ItemId::Enum(id))
            }
            ast::ItemKind::Udvt(u) => {
                let id = self.hir.udvts.len();
                let ty = Type { span: u.ty.span, kind: TypeKind::Err };
                self.hir.udvts.push(Udvt { source: sid, contract, span: item.span, name: u.name, ty });
                Some(ItemId::Udvt(id))
            }
            ast::ItemKind::Error(e) => {
                let id = self.hir.errors.len();
                self.hir.errors.push(Error { source: sid, contract, span: item.span, name: e.name, parameters: Vec::new() });
                let params: Vec<VariableId> =
                    e.parameters.vars.iter().map(|v| self.collect_var(sid, contract, None, v, VarKind::Error)).collect();
                self.hir.errors[id].parameters = params;
                Some(ItemId::Error(id))
            }
            ast::ItemKind::Event(e) => {
                let id = self.hir.events.len();
                self.hir.events.push(Event {
                    source: sid,
                    contract,
                    span: item.span,
                    name: e.name,
                    parameters: Vec::new(),
                    anonymous: e.anonymous.is_some(),
                });
                let params: Vec<VariableId> =
                    e.parameters.vars.iter().map(|v| self.collect_var(sid, contract, None, v, VarKind::Event)).collect();
                self.hir.events[id].parameters = params;
                Some(ItemId::Event(id))
            }
        }
    }

    pub fn collect_var(
        &mut self,
        sid: SourceId,
        contract: Option<ContractId>,
        function: Option<FunctionId>,
        v: &'a ast::VariableDefinition,
        kind: VarKind,
    ) -> VariableId {
        let id = self.hir.variables.len();
        self.hir.variables.push(Variable {
            source: sid,
            contract,
            function,
            span: v.span,
            kind,
            ty: Type { span: v.ty.span, kind: TypeKind::Err },
            name: v.name,
            visibility: v.visibility.map(|x| x.data),
            mutability: v.mutability.map(|x| x.data),
            data_location: v.data_location.map(|x| x.data),
            override_: v.override_.as_ref().map(|o| o.span),
            overrides: Vec::new(),
            indexed: v.indexed.is_some(),
            has_initializer: v.initializer.is_some(),
            ast: Some(v),
            getter: None,
        });
        id
    }

    // ---- source scopes ----

    fn build_source_scope(&mut self, sid: SourceId) {
        let mut scope = Scope::new();
        // Own items.
        let items = self.hir.sources[sid].items.clone();
        for id in items {
            if let Some(name) = self.hir.item_name(id) {
                let res = Res::Item(id);
                let kind_fn = |r: Res| self.res_kind(r);
                if let Err(prev) = scope.declare(name.name, res, kind_fn) {
                    let prev_span = self.res_span(prev);
                    self.emit_already_declared(name, prev_span);
                }
            }
        }
        // Imports.
        let Some(ast) = self.hir.sources[sid].ast else {
            self.source_scopes[sid] = scope.clone();
            self.source_exports[sid] = scope;
            return;
        };
        let imports = self.hir.sources[sid].imports.clone();
        let mut import_idx = 0;
        for item in &ast.items {
            let ast::ItemKind::Import(import) = &item.kind else { continue };
            // Find the resolved source for this import item.
            let target = imports.iter().find(|(span, _)| *span == item.span).map(|(_, s)| *s);
            import_idx += 1;
            let _ = import_idx;
            let Some(target) = target else { continue };
            match &import.items {
                ast::ImportItems::Plain(None) => {
                    let exports = self.source_exports[target].clone();
                    for (name, resl) in exports.iter() {
                        for &res in resl {
                            let kind_fn = |r: Res| self.res_kind(r);
                            if let Err(prev) = scope.declare(name, res, kind_fn) {
                                let prev_span = self.res_span(prev);
                                self.dcx.emit(
                                    Diag::new(Level::Error, format!("identifier `{name}` already declared"))
                                        .span(item.span)
                                        .span_note(prev_span, "previous declaration declared here"),
                                );
                            }
                        }
                    }
                }
                ast::ImportItems::Plain(Some(alias)) | ast::ImportItems::Glob(alias) => {
                    let kind_fn = |r: Res| self.res_kind(r);
                    if let Err(prev) = scope.declare(alias.name, Res::Namespace(target), kind_fn) {
                        let prev_span = self.res_span(prev);
                        self.emit_already_declared(*alias, prev_span);
                    }
                }
                ast::ImportItems::Aliases(aliases) => {
                    for (name, alias) in aliases {
                        let exports = &self.source_exports[target];
                        let Some(resl) = exports.get(name.name).cloned() else {
                            let file = self.hir.sources[sid].file.name.display();
                            self.dcx.emit(
                                Diag::new(Level::Error, format!("declaration `{}` not found in {}", name.name, file))
                                    .span(name.span),
                            );
                            continue;
                        };
                        let bind = alias.unwrap_or(*name);
                        for res in resl {
                            let kind_fn = |r: Res| self.res_kind(r);
                            if let Err(prev) = scope.declare(bind.name, res, kind_fn) {
                                let prev_span = self.res_span(prev);
                                self.emit_already_declared(bind, prev_span);
                            }
                        }
                    }
                }
            }
        }
        self.source_scopes[sid] = scope.clone();
        self.source_exports[sid] = scope;
    }

    // ---- contracts ----

    fn lower_contract_header(&mut self, cid: ContractId) {
        let contract_ast = self.hir.contracts[cid].ast;
        let items = self.hir.contracts[cid].items.clone();
        // 1. Own declarations.
        let mut own = Scope::new();
        own.declare_unchecked(kw::This, Res::This(cid));
        own.declare_unchecked(kw::Super, Res::Super(cid));
        for &id in &items {
            if let ItemId::Function(fid) = id {
                let f = &self.hir.functions[fid];
                let slot = match f.kind {
                    FunctionKind::Constructor => Some(("constructor", 0)),
                    FunctionKind::Fallback => Some(("fallback", 1)),
                    FunctionKind::Receive => Some(("receive", 2)),
                    _ => None,
                };
                if let Some((desc, which)) = slot {
                    let existing = match which {
                        0 => self.hir.contracts[cid].ctor,
                        1 => self.hir.contracts[cid].fallback,
                        _ => self.hir.contracts[cid].receive,
                    };
                    if let Some(prev) = existing {
                        let prev_span = self.hir.functions[prev].span;
                        self.dcx.emit(
                            Diag::new(Level::Error, format!("{desc} function already declared"))
                                .span(f.span)
                                .span_note(prev_span, "previous declaration here"),
                        );
                    } else {
                        match which {
                            0 => self.hir.contracts[cid].ctor = Some(fid),
                            1 => self.hir.contracts[cid].fallback = Some(fid),
                            _ => self.hir.contracts[cid].receive = Some(fid),
                        }
                    }
                    continue;
                }
            }
            if let Some(name) = self.hir.item_name(id) {
                let kind_fn = |r: Res| self.res_kind(r);
                if let Err(prev) = own.declare(name.name, Res::Item(id), kind_fn) {
                    let prev_span = match prev {
                        Res::This(_) | Res::Super(_) => Span::DUMMY,
                        _ => self.res_span(prev),
                    };
                    self.emit_already_declared(name, prev_span);
                    self.reported_dups.insert((cid, name.name));
                }
            }
        }
        // 2. Bases.
        let source = self.hir.contracts[cid].source;
        let mut bases = Vec::new();
        for base in &contract_ast.bases {
            let res = self.resolve_type_path_in(&base.name, source, None);
            match res {
                Some(Res::Item(ItemId::Contract(b))) => {
                    if b == cid {
                        self.dcx.emit(
                            Diag::new(Level::Error, "contracts cannot inherit from themselves").span(base.name.span()),
                        );
                    } else if b > cid {
                        self.dcx.emit(
                            Diag::new(Level::Error, "definition of base has to precede definition of derived contract")
                                .span(self.hir.contracts[cid].name.span),
                        );
                    } else {
                        bases.push(b);
                    }
                }
                Some(Res::Item(_)) => {
                    // Not a contract.
                    self.dcx.emit(Diag::new(Level::Error, "name has to refer to a valid user-defined type").span(base.name.span()));
                }
                Some(Res::Builtin(_)) | Some(Res::This(_)) | Some(Res::Super(_)) => {
                    self.dcx.emit(Diag::new(Level::Error, "expected item, found builtin").span(base.name.span()));
                }
                _ => {}
            }
        }
        self.hir.contracts[cid].bases = bases.clone();
        // 3. Linearize.
        let lin = match super::linearize::linearize(cid, &bases, &self.hir) {
            Some(l) => l,
            None => {
                self.dcx.emit(
                    Diag::new(Level::Error, "linearization of inheritance graph impossible")
                        .span(self.hir.contracts[cid].name.span),
                );
                let mut l = vec![cid];
                l.extend(bases.iter().copied());
                l
            }
        };
        self.hir.contracts[cid].linearized_bases = lin.clone();
        // 4. Scope: inherited (most base first) then own.
        let mut scope = Scope::new();
        scope.declare_unchecked(kw::This, Res::This(cid));
        scope.declare_unchecked(kw::Super, Res::Super(cid));
        for &b in lin.iter().rev() {
            if b == cid {
                continue;
            }
            let base_items = self.hir.contracts[b].items.clone();
            for id in base_items {
                if let ItemId::Function(fid) = id {
                    if !matches!(self.hir.functions[fid].kind, FunctionKind::Function | FunctionKind::Modifier) {
                        continue;
                    }
                }
                if let Some(name) = self.hir.item_name(id) {
                    scope.declare_unchecked(name.name, Res::Item(id));
                }
            }
        }
        for &id in &items {
            if let ItemId::Function(fid) = id {
                if !matches!(self.hir.functions[fid].kind, FunctionKind::Function | FunctionKind::Modifier) {
                    continue;
                }
            }
            if let Some(name) = self.hir.item_name(id) {
                let kind_fn = |r: Res| self.res_kind(r);
                if let Err(prev) = scope.declare(name.name, Res::Item(id), kind_fn) {
                    if !self.reported_dups.contains(&(cid, name.name)) {
                        // Only report conflicts with inherited items.
                        let prev_contract = match prev {
                            Res::Item(p) => self.hir.item_contract(p),
                            _ => None,
                        };
                        if prev_contract != Some(cid) {
                            let prev_span = self.res_span(prev);
                            self.emit_already_declared(name, prev_span);
                        }
                    }
                }
            }
        }
        self.contract_scopes[cid] = scope;
    }

    // ---- lookup ----

    /// Looks up a name starting from the innermost scope.
    pub fn lookup(&self, name: Symbol, locals: &[Scope], contract: Option<ContractId>, source: SourceId) -> Option<Vec<Res>> {
        for s in locals.iter().rev() {
            if let Some(r) = s.get(name) {
                return Some(r.clone());
            }
        }
        if let Some(cid) = contract {
            if let Some(r) = self.contract_scopes[cid].get(name) {
                return Some(r.clone());
            }
        }
        if let Some(r) = self.source_scopes[source].get(name) {
            return Some(r.clone());
        }
        if let Some(r) = self.builtins.get(name) {
            return Some(r.clone());
        }
        None
    }

    fn emit_unresolved(&self, ident: Ident) {
        self.dcx.emit(Diag::new(Level::Error, format!("unresolved symbol `{}`", ident.name)).span(ident.span));
    }

    /// Resolves a path in type position. Emits errors. Returns the final resolution.
    pub fn resolve_type_path_in(&self, path: &ast::Path, source: SourceId, contract: Option<ContractId>) -> Option<Res> {
        self.resolve_type_path(path, &[], contract, source)
    }

    pub fn resolve_type_path(&self, path: &ast::Path, locals: &[Scope], contract: Option<ContractId>, source: SourceId) -> Option<Res> {
        let first = path.segments[0];
        let Some(resl) = self.lookup(first.name, locals, contract, source) else {
            self.emit_unresolved(first);
            return None;
        };
        let mut res = resl[0];
        for (i, seg) in path.segments.iter().enumerate().skip(1) {
            let prev = path.segments[i - 1];
            match res {
                Res::Item(ItemId::Contract(c)) => {
                    let Some(r) = self.contract_scopes[c].get(seg.name) else {
                        self.emit_unresolved(*seg);
                        return None;
                    };
                    res = r[0];
                }
                Res::Namespace(s) => {
                    let Some(r) = self.source_exports[s].get(seg.name) else {
                        self.emit_unresolved(*seg);
                        return None;
                    };
                    res = r[0];
                }
                Res::Item(id) => {
                    self.dcx.emit(
                        Diag::new(
                            Level::Error,
                            format!("`{}` is a {}, which cannot be indexed in type paths", prev.name, id.description()),
                        )
                        .span(prev.span),
                    );
                    return None;
                }
                Res::Builtin(_) | Res::This(_) | Res::Super(_) => {
                    self.dcx.emit(Diag::new(Level::Error, "expected item, found builtin").span(path.span()));
                    return None;
                }
                Res::Err => return None,
            }
        }
        if matches!(res, Res::Builtin(_) | Res::This(_) | Res::Super(_)) {
            self.dcx.emit(Diag::new(Level::Error, "expected item, found builtin").span(path.span()));
            return None;
        }
        Some(res)
    }

    // ---- resolution of items ----

    fn resolve_all(&mut self) {
        // Structs.
        for sid in 0..self.hir.structs.len() {
            let (source, contract) = (self.hir.structs[sid].source, self.hir.structs[sid].contract);
            let fields = self.hir.structs[sid].fields.clone();
            for vid in fields {
                self.resolve_var_type(vid, &[], contract, source);
            }
        }
        // UDVTs.
        for uid in 0..self.hir.udvts.len() {
            let src_ast = self.hir.sources[self.hir.udvts[uid].source].ast;
            let _ = src_ast;
            let ty = self.find_udvt_ast(uid).map(|u| u.ty.clone());
            if let Some(ty) = ty {
                let (source, contract) = (self.hir.udvts[uid].source, self.hir.udvts[uid].contract);
                let t = self.resolve_type(&ty, &[], contract, source);
                self.hir.udvts[uid].ty = t;
            }
        }
        // Errors.
        for eid in 0..self.hir.errors.len() {
            let (source, contract) = (self.hir.errors[eid].source, self.hir.errors[eid].contract);
            let params = self.hir.errors[eid].parameters.clone();
            for vid in params {
                self.resolve_var_type(vid, &[], contract, source);
            }
        }
        // Events.
        for eid in 0..self.hir.events.len() {
            let (source, contract) = (self.hir.events[eid].source, self.hir.events[eid].contract);
            let params = self.hir.events[eid].parameters.clone();
            for vid in params {
                self.resolve_var_type(vid, &[], contract, source);
            }
        }
        // Variables (state & constants).
        let n_vars = self.hir.variables.len();
        for vid in 0..n_vars {
            if !matches!(self.hir.variables[vid].kind, VarKind::State | VarKind::Constant) {
                continue;
            }
            let (source, contract) = (self.hir.variables[vid].source, self.hir.variables[vid].contract);
            self.resolve_var_type(vid, &[], contract, source);
            // override list
            if let Some(v) = self.hir.variables[vid].ast {
                if let Some(ov) = &v.override_ {
                    let ids = self.resolve_override_list(ov, contract, source, vid);
                    self.hir.variables[vid].overrides = ids;
                }
                if let Some(init) = &v.initializer {
                    let mut rs = Resolver { cx: self, locals: Vec::new(), contract, source, function: None };
                    rs.resolve_expr(init);
                }
            }
        }
        // Functions.
        for fid in 0..self.hir.functions.len() {
            self.resolve_function(fid);
        }
    }

    fn find_udvt_ast(&self, uid: UdvtId) -> Option<&'a ast::ItemUdvt> {
        let u = &self.hir.udvts[uid];
        let src = self.hir.sources[u.source].ast?;
        fn find<'a>(items: &'a [ast::Item], name: Ident) -> Option<&'a ast::ItemUdvt> {
            for it in items {
                match &it.kind {
                    ast::ItemKind::Udvt(u) if u.name.span == name.span => return Some(u),
                    ast::ItemKind::Contract(c) => {
                        if let Some(r) = find(&c.body, name) {
                            return Some(r);
                        }
                    }
                    _ => {}
                }
            }
            None
        }
        find(&src.items, u.name)
    }

    fn resolve_override_list(&mut self, ov: &ast::Override, contract: Option<ContractId>, source: SourceId, _vid: usize) -> Vec<ContractId> {
        let mut ids = Vec::new();
        for p in &ov.paths {
            if let Some(Res::Item(ItemId::Contract(c))) = self.resolve_type_path(p, &[], contract, source) {
                ids.push(c);
            }
        }
        ids
    }

    pub fn resolve_var_type(&mut self, vid: VariableId, locals: &[Scope], contract: Option<ContractId>, source: SourceId) {
        let Some(v) = self.hir.variables[vid].ast else { return };
        let ty = self.resolve_type(&v.ty, locals, contract, source);
        self.hir.variables[vid].ty = ty;
    }

    pub fn resolve_type(&mut self, ty: &ast::Type, locals: &[Scope], contract: Option<ContractId>, source: SourceId) -> Type {
        let kind = match &ty.kind {
            ast::TypeKind::Elementary(e) => TypeKind::Elementary(*e),
            ast::TypeKind::Array(inner, size) => {
                let inner = self.resolve_type(inner, locals, contract, source);
                let size = match size {
                    Some(e) => {
                        let mut rs = Resolver { cx: self, locals: locals.to_vec(), contract, source, function: None };
                        rs.resolve_expr(e);
                        Some(ArraySize::Unknown)
                    }
                    None => None,
                };
                TypeKind::Array(Box::new(inner), size)
            }
            ast::TypeKind::Function(f) => {
                let mut params = Vec::new();
                for v in &f.parameters.vars {
                    params.push(self.resolve_type(&v.ty, locals, contract, source));
                }
                let mut returns = Vec::new();
                if let Some(r) = &f.returns {
                    for v in &r.vars {
                        returns.push(self.resolve_type(&v.ty, locals, contract, source));
                    }
                }
                TypeKind::Function(Box::new(FunctionType {
                    parameters: params,
                    returns,
                    visibility: f.visibility.map(|v| v.data).unwrap_or(Visibility::Internal),
                    state_mutability: f.state_mutability.map(|s| s.data).unwrap_or(StateMutability::NonPayable),
                }))
            }
            ast::TypeKind::Mapping(m) => {
                let k = self.resolve_type(&m.key, locals, contract, source);
                let v = self.resolve_type(&m.value, locals, contract, source);
                TypeKind::Mapping(Box::new(k), Box::new(v))
            }
            ast::TypeKind::Custom(path) => match self.resolve_type_path(path, locals, contract, source) {
                Some(Res::Item(id)) => TypeKind::Custom(id),
                _ => TypeKind::Err,
            },
        };
        Type { span: ty.span, kind }
    }

    fn resolve_function(&mut self, fid: FunctionId) {
        let Some(f_ast) = self.hir.functions[fid].ast else { return };
        let (source, contract) = (self.hir.functions[fid].source, self.hir.functions[fid].contract);
        let mut scope = Scope::new();
        // Parameters and returns.
        let params = self.hir.functions[fid].parameters.clone();
        let returns = self.hir.functions[fid].returns.clone();
        for &vid in params.iter().chain(returns.iter()) {
            self.resolve_var_type(vid, &[], contract, source);
            if let Some(name) = self.hir.variables[vid].name {
                let kind_fn = |r: Res| self.res_kind(r);
                if let Err(prev) = scope.declare(name.name, Res::Item(ItemId::Variable(vid)), kind_fn) {
                    let prev_span = self.res_span(prev);
                    self.emit_already_declared(name, prev_span);
                }
            }
        }
        // Modifiers.
        let mut mods = Vec::new();
        for m in &f_ast.header.modifiers {
            let r = self.resolve_type_path(&m.name, &[], contract, source);
            {
                let mut rs = Resolver { cx: self, locals: vec![scope.clone()], contract, source, function: Some(fid) };
                rs.resolve_call_args(&m.arguments);
            }
            mods.push(r.unwrap_or(Res::Err));
        }
        self.hir.functions[fid].modifiers = mods;
        // Override list.
        if let Some(ov) = &f_ast.header.override_ {
            let ids = self.resolve_override_list(ov, contract, source, 0);
            self.hir.functions[fid].overrides = ids;
        }
        // Body.
        if let Some(body) = &f_ast.body {
            let mut rs = Resolver { cx: self, locals: vec![scope], contract, source, function: Some(fid) };
            rs.resolve_block_stmts(body);
        }
    }
}

/// Expression/statement resolver with local scopes.
pub struct Resolver<'c, 'a, 'd> {
    pub cx: &'c mut LowerCtx<'a, 'd>,
    pub locals: Vec<Scope>,
    pub contract: Option<ContractId>,
    pub source: SourceId,
    pub function: Option<FunctionId>,
}

impl<'c, 'a, 'd> Resolver<'c, 'a, 'd> {
    fn declare_local(&mut self, v: &'a ast::VariableDefinition, kind: VarKind) -> VariableId {
        let vid = self.cx.collect_var(self.source, self.contract, self.function, v, kind);
        // Declare name first, then resolve type.
        if let Some(name) = v.name {
            let scope = self.locals.last_mut().unwrap();
            let existing = scope.get(name.name).cloned();
            if let Some(existing) = existing {
                let prev = existing[0];
                let prev_span = self.cx.res_span(prev);
                self.cx.emit_already_declared(name, prev_span);
            } else {
                scope.declare_unchecked(name.name, Res::Item(ItemId::Variable(vid)));
            }
        }
        let locals = self.locals.clone();
        self.cx.resolve_var_type(vid, &locals, self.contract, self.source);
        vid
    }

    pub fn resolve_block_stmts(&mut self, block: &'a ast::Block) {
        for stmt in &block.stmts {
            self.resolve_stmt(stmt);
        }
    }

    fn with_scope(&mut self, f: impl FnOnce(&mut Self)) {
        self.locals.push(Scope::new());
        f(self);
        self.locals.pop();
    }

    fn resolve_stmt(&mut self, stmt: &'a ast::Stmt) {
        use ast::StmtKind::*;
        match &stmt.kind {
            Assembly(_) => {}
            DeclSingle(v) => {
                if let Some(init) = &v.initializer {
                    self.resolve_expr(init);
                }
                self.declare_local(v, VarKind::Statement);
            }
            DeclMulti(vars, expr) => {
                self.resolve_expr(expr);
                for v in vars.iter().flatten() {
                    self.declare_local(v, VarKind::Statement);
                }
            }
            Block(b) => self.with_scope(|s| s.resolve_block_stmts(b)),
            UncheckedBlock(b) => self.with_scope(|s| s.resolve_block_stmts(b)),
            Break | Continue | Placeholder => {}
            DoWhile(body, cond) => {
                self.with_scope(|s| s.resolve_stmt(body));
                self.resolve_expr(cond);
            }
            Emit(path, args) | Revert(path, args) => {
                self.resolve_path_expr(path);
                self.resolve_call_args(args);
            }
            Expr(e) => self.resolve_expr(e),
            For { init, cond, next, body } => {
                self.with_scope(|s| {
                    if let Some(init) = init {
                        s.resolve_stmt(init);
                    }
                    if let Some(cond) = cond {
                        s.resolve_expr(cond);
                    }
                    if let Some(next) = next {
                        s.resolve_expr(next);
                    }
                    s.with_scope(|s| s.resolve_stmt(body));
                });
            }
            If(cond, then, els) => {
                self.resolve_expr(cond);
                self.with_scope(|s| s.resolve_stmt(then));
                if let Some(els) = els {
                    self.with_scope(|s| s.resolve_stmt(els));
                }
            }
            Return(e) => {
                if let Some(e) = e {
                    self.resolve_expr(e);
                }
            }
            Try(t) => {
                self.resolve_expr(&t.expr);
                self.with_scope(|s| {
                    if let Some(r) = &t.returns {
                        for v in &r.vars {
                            s.declare_local(v, VarKind::TryCatch);
                        }
                    }
                    s.resolve_block_stmts(&t.block);
                });
                for c in &t.catch {
                    self.with_scope(|s| {
                        for v in &c.args.vars {
                            s.declare_local(v, VarKind::TryCatch);
                        }
                        s.resolve_block_stmts(&c.block);
                    });
                }
            }
            While(cond, body) => {
                self.resolve_expr(cond);
                self.with_scope(|s| s.resolve_stmt(body));
            }
        }
    }

    fn resolve_path_expr(&mut self, path: &ast::Path) {
        let first = path.segments[0];
        if self.cx.lookup(first.name, &self.locals, self.contract, self.source).is_none() {
            self.cx.emit_unresolved(first);
        }
    }

    pub fn resolve_call_args(&mut self, args: &'a ast::CallArgs) {
        match &args.kind {
            ast::CallArgsKind::Unnamed(v) => {
                for e in v {
                    self.resolve_expr(e);
                }
            }
            ast::CallArgsKind::Named(v) => {
                for a in v {
                    self.resolve_expr(&a.value);
                }
            }
        }
    }

    fn resolve_ty_in_expr(&mut self, ty: &ast::Type) {
        let locals = self.locals.clone();
        self.cx.resolve_type(ty, &locals, self.contract, self.source);
    }

    pub fn resolve_expr(&mut self, expr: &'a ast::Expr) {
        use ast::ExprKind::*;
        match &expr.kind {
            Array(v) => {
                for e in v {
                    self.resolve_expr(e);
                }
            }
            Assign(a, _, b) | Binary(a, _, b) => {
                self.resolve_expr(a);
                self.resolve_expr(b);
            }
            Call(callee, args) => {
                self.resolve_expr(callee);
                self.resolve_call_args(args);
            }
            CallOptions(callee, args) => {
                self.resolve_expr(callee);
                for a in args {
                    self.resolve_expr(&a.value);
                }
            }
            Delete(e) => self.resolve_expr(e),
            Ident(ident) => {
                if self.cx.lookup(ident.name, &self.locals, self.contract, self.source).is_none() {
                    self.cx.emit_unresolved(*ident);
                }
            }
            Index(a, b) => {
                self.resolve_expr(a);
                if let Some(b) = b {
                    self.resolve_expr(b);
                }
            }
            Slice(a, b, c) => {
                self.resolve_expr(a);
                if let Some(b) = b {
                    self.resolve_expr(b);
                }
                if let Some(c) = c {
                    self.resolve_expr(c);
                }
            }
            Lit(..) => {}
            Member(e, _) => self.resolve_expr(e),
            New(ty) => self.resolve_ty_in_expr(ty),
            Payable(args) => self.resolve_call_args(args),
            Ternary(a, b, c) => {
                self.resolve_expr(a);
                self.resolve_expr(b);
                self.resolve_expr(c);
            }
            Tuple(v) => {
                for e in v.iter().flatten() {
                    self.resolve_expr(e);
                }
            }
            TypeCall(ty) => self.resolve_ty_in_expr(ty),
            Type(ty) => self.resolve_ty_in_expr(ty),
            Unary(_, e) => self.resolve_expr(e),
        }
    }
}

