//! C3 linearization of contract inheritance.

use super::hir::{ContractId, Hir};

/// Returns the linearized bases (most derived first), or `None` if impossible.
pub fn linearize(cid: ContractId, bases: &[ContractId], hir: &Hir) -> Option<Vec<ContractId>> {
    // Solidity: `contract C is A, B` means B is "most derived" base; merge lists in reverse order.
    let mut lists: Vec<Vec<ContractId>> = Vec::new();
    for &b in bases.iter().rev() {
        lists.push(hir.contracts[b].linearized_bases.clone());
    }
    lists.push(bases.iter().rev().copied().collect());
    let mut result = vec![cid];
    loop {
        lists.retain(|l| !l.is_empty());
        if lists.is_empty() {
            break;
        }
        // Find a head that is not in the tail of any list.
        let mut found = None;
        for l in &lists {
            let head = l[0];
            if !lists.iter().any(|other| other[1..].contains(&head)) {
                found = Some(head);
                break;
            }
        }
        let head = found?;
        result.push(head);
        for l in lists.iter_mut() {
            if l[0] == head {
                l.remove(0);
            }
        }
    }
    Some(result)
}
