    pub fn to_u128(&self) -> Option<u128> {
        if self.0[2] == 0 && self.0[3] == 0 { Some(self.0[0] as u128 | ((self.0[1] as u128) << 64)) } else { None }
    }
    pub fn bits(&self) -> u32 {
        for i in (0..4).rev() {
            if self.0[i] != 0 {
                return (i as u32) * 64 + (64 - self.0[i].leading_zeros());
            }
        }
        0
    }

    pub fn overflowing_add(self, other: U256) -> (U256, bool) {
        let mut r = [0u64; 4];
        let mut carry = 0u64;
        for i in 0..4 {
            let (s1, c1) = self.0[i].overflowing_add(other.0[i]);
            let (s2, c2) = s1.overflowing_add(carry);
            r[i] = s2;
            carry = (c1 as u64) + (c2 as u64);
        }
        (U256(r), carry != 0)
    }
    pub fn checked_add(self, other: U256) -> Option<U256> {
        let (r, o) = self.overflowing_add(other);
        if o { None } else { Some(r) }
    }
    pub fn wrapping_add(self, other: U256) -> U256 {
        self.overflowing_add(other).0
    }
    pub fn overflowing_sub(self, other: U256) -> (U256, bool) {
        let mut r = [0u64; 4];
        let mut borrow = 0u64;
        for i in 0..4 {
            let (s1, b1) = self.0[i].overflowing_sub(other.0[i]);
            let (s2, b2) = s1.overflowing_sub(borrow);
            r[i] = s2;
            borrow = (b1 as u64) + (b2 as u64);
        }
        (U256(r), borrow != 0)
    }
    pub fn checked_sub(self, other: U256) -> Option<U256> {
        let (r, o) = self.overflowing_sub(other);
        if o { None } else { Some(r) }
    }
    pub fn wrapping_sub(self, other: U256) -> U256 {
        self.overflowing_sub(other).0
    }
    pub fn wrapping_neg(self) -> U256 {
        U256::ZERO.wrapping_sub(self)
    }
    pub fn checked_mul(self, other: U256) -> Option<U256> {
        let mut r = [0u128; 8];
        for i in 0..4 {
            for j in 0..4 {
                let p = (self.0[i] as u128) * (other.0[j] as u128);
                if p == 0 {
                    continue;
                }
                if i + j >= 4 {
                    return None;
                }
                let mut k = i + j;
                let mut carry = p;
                while carry != 0 {
                    if k >= 8 {
                        return None;
                    }
                    let s = r[k] + (carry & 0xFFFF_FFFF_FFFF_FFFF);
                    r[k] = s & 0xFFFF_FFFF_FFFF_FFFF;
                    carry = (carry >> 64) + (s >> 64);
                    k += 1;
                }
            }
        }
        for i in 4..8 {
            if r[i] != 0 {
                return None;
            }
        }
        Some(U256([r[0] as u64, r[1] as u64, r[2] as u64, r[3] as u64]))
    }
    pub fn wrapping_mul(self, other: U256) -> U256 {
        let mut r = [0u128; 4];
        for i in 0..4 {
            for j in 0..4 {
                if i + j >= 4 {
                    continue;
                }
                let p = (self.0[i] as u128) * (other.0[j] as u128);
                let mut k = i + j;
                let mut carry = p;
                while carry != 0 && k < 4 {
                    let s = r[k] + (carry & 0xFFFF_FFFF_FFFF_FFFF);
                    r[k] = s & 0xFFFF_FFFF_FFFF_FFFF;
                    carry = (carry >> 64) + (s >> 64);
                    k += 1;
                }
            }
        }
        U256([r[0] as u64, r[1] as u64, r[2] as u64, r[3] as u64])
    }
    pub fn mul_small(self, m: u64) -> Option<U256> {
        self.checked_mul(U256::from_u64(m))
    }
    pub fn checked_pow(self, mut exp: U256) -> Option<U256> {
        let mut result = U256::ONE;
        let mut base = self;
        if exp.is_zero() {
            return Some(result);
        }
        if base.is_zero() {
            return Some(U256::ZERO);
        }
        if base == U256::ONE {
            return Some(U256::ONE);
        }
        loop {
            if exp.0[0] & 1 == 1 {
                result = result.checked_mul(base)?;
            }
            exp = exp.shr(1);
            if exp.is_zero() {
                break;
            }
            base = base.checked_mul(base)?;
        }
        Some(result)
    }
    pub fn shl(self, n: u32) -> U256 {
        if n >= 256 {
            return U256::ZERO;
        }
        let limb = (n / 64) as usize;
        let bit = n % 64;
        let mut r = [0u64; 4];
        for i in (0..4).rev() {
            if i >= limb {
                let src = i - limb;
                r[i] = self.0[src] << bit;
                if bit != 0 && src > 0 {
                    r[i] |= self.0[src - 1] >> (64 - bit);
                }
            }
        }
        U256(r)
    }
    pub fn shr(self, n: u32) -> U256 {
        if n >= 256 {
            return U256::ZERO;
        }
        let limb = (n / 64) as usize;
        let bit = n % 64;
        let mut r = [0u64; 4];
        for i in 0..4 {
            if i + limb < 4 {
                let src = i + limb;
                r[i] = self.0[src] >> bit;
                if bit != 0 && src + 1 < 4 {
                    r[i] |= self.0[src + 1] << (64 - bit);
                }
            }
        }
        U256(r)
    }
    pub fn bitand(self, o: U256) -> U256 {
        U256([self.0[0] & o.0[0], self.0[1] & o.0[1], self.0[2] & o.0[2], self.0[3] & o.0[3]])
    }
    pub fn bitor(self, o: U256) -> U256 {
        U256([self.0[0] | o.0[0], self.0[1] | o.0[1], self.0[2] | o.0[2], self.0[3] | o.0[3]])
    }
    pub fn bitxor(self, o: U256) -> U256 {
        U256([self.0[0] ^ o.0[0], self.0[1] ^ o.0[1], self.0[2] ^ o.0[2], self.0[3] ^ o.0[3]])
    }
    pub fn not(self) -> U256 {
        U256([!self.0[0], !self.0[1], !self.0[2], !self.0[3]])
    }

    /// Division with remainder (by a U256).
    pub fn div_rem(self, divisor: U256) -> Option<(U256, U256)> {
        if divisor.is_zero() {
            return None;
        }
        if self < divisor {
            return Some((U256::ZERO, self));
        }
        if let (Some(a), Some(b)) = (self.to_u128(), divisor.to_u128()) {
            return Some((U256::from_u128(a / b), U256::from_u128(a % b)));
        }
        // Long division bit by bit.
        let mut quotient = U256::ZERO;
        let mut rem = U256::ZERO;
        let bits = self.bits();
        for i in (0..bits).rev() {
            rem = rem.shl(1);
            if (self.0[(i / 64) as usize] >> (i % 64)) & 1 == 1 {
                rem.0[0] |= 1;
            }
            if rem >= divisor {
                rem = rem.wrapping_sub(divisor);
                quotient.0[(i / 64) as usize] |= 1 << (i % 64);
            }
        }
        Some((quotient, rem))
    }

    pub fn from_dec_str(s: &str) -> Option<U256> {
        let mut r = U256::ZERO;
        for c in s.bytes() {
            if !c.is_ascii_digit() {
                return None;
            }
            r = r.mul_small(10)?;
            r = r.checked_add(U256::from_u64((c - b'0') as u64))?;
        }
        Some(r)
    }

    pub fn from_hex_str(s: &str) -> Option<U256> {
        let mut r = U256::ZERO;
        for c in s.chars() {
            let d = c.to_digit(16)?;
            if r.bits() > 252 {
                return None;
            }
            r = r.shl(4);
            r.0[0] |= d as u64;
        }
        Some(r)
    }

    pub fn to_dec_string(&self) -> String {
        if self.is_zero() {
            return "0".to_string();
        }
        let mut digits = Vec::new();
        let mut v = *self;
        let ten = U256::from_u64(10);
        while !v.is_zero() {
            let (q, r) = v.div_rem(ten).unwrap();
            digits.push((b'0' + r.0[0] as u8) as char);
            v = q;
        }
        digits.iter().rev().collect()
    }
}

impl PartialOrd for U256 {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}
impl Ord for U256 {
    fn cmp(&self, other: &Self) -> Ordering {
        for i in (0..4).rev() {
            match self.0[i].cmp(&other.0[i]) {
                Ordering::Equal => continue,
                o => return o,
            }
        }
        Ordering::Equal
    }
}
