//! Post-resolution checks performed in the lowering stage.

use super::hir::*;
use super::lower::LowerCtx;
use crate::ast::{self, DataLocation, ElementaryType, FunctionKind, Visibility};
use crate::diag::{Diag, Level};
use crate::span::Span;
use crate::u256::U256;

pub fn post_resolution_checks(cx: &mut LowerCtx<'_, '_>) {
    // Evaluate array sizes and check variables.
    let n = cx.hir.variables.len();
    for vid in 0..n {
        check_type_validity(cx, vid);
        eval_var_array_sizes(cx, vid);
        check_data_location(cx, vid);
    }
    // UDVT underlying types.
    check_recursive_structs(cx);
}

fn type_path_span(ty: &ast::Type) -> Span {
    match &ty.kind {
        ast::TypeKind::Custom(p) => p.span(),
        _ => ty.span,
    }
}

/// Emits "name has to refer to a valid user-defined type" for custom types that don't refer to types.
fn check_type_validity(cx: &mut LowerCtx<'_, '_>, vid: VariableId) {
    let Some(v_ast) = cx.hir.variables[vid].ast else { return };
    let ty = cx.hir.variables[vid].ty.clone();
    check_type_validity_rec(cx, &ty, &v_ast.ty);
}

fn check_type_validity_rec(cx: &mut LowerCtx<'_, '_>, ty: &Type, ast_ty: &ast::Type) {
    match (&ty.kind, &ast_ty.kind) {
        (TypeKind::Custom(id), ast::TypeKind::Custom(_)) => {
            if !cx.hir.is_type_item(*id) {
                cx.dcx.emit(
                    Diag::new(Level::Error, "name has to refer to a valid user-defined type").span(type_path_span(ast_ty)),
                );
            }
        }
        (TypeKind::Array(inner, _), ast::TypeKind::Array(ainner, _)) => check_type_validity_rec(cx, inner, ainner),
        (TypeKind::Mapping(k, v), ast::TypeKind::Mapping(m)) => {
            check_type_validity_rec(cx, k, &m.key);
            check_type_validity_rec(cx, v, &m.value);
        }
        (TypeKind::Function(f), ast::TypeKind::Function(af)) => {
            for (t, at) in f.parameters.iter().zip(af.parameters.vars.iter()) {
                check_type_validity_rec(cx, t, &at.ty);
            }
            if let Some(r) = &af.returns {
                for (t, at) in f.returns.iter().zip(r.vars.iter()) {
                    check_type_validity_rec(cx, t, &at.ty);
                }
            }
        }
        _ => {}
    }
}

// ---- constant evaluation ----

pub struct EvalError {
    pub msg: String,
}

pub struct ConstEval<'c, 'a, 'd> {
    pub cx: &'c LowerCtx<'a, 'd>,
    pub contract: Option<ContractId>,
    pub source: SourceId,
    pub depth: usize,
}

impl<'c, 'a, 'd> ConstEval<'c, 'a, 'd> {
    pub fn eval(&mut self, e: &ast::Expr) -> Result<U256, EvalError> {
        use ast::ExprKind::*;
        self.depth += 1;
        if self.depth > 64 {
            return Err(EvalError { msg: "recursion limit reached".into() });
        }
        let r = match &e.kind {
            Lit(lit, sub) => {
                let base = match &lit.kind {
                    ast::LitKind::Number(s) => {
                        U256::from_dec_str(s).ok_or(EvalError { msg: "arithmetic overflow".into() })?
                    }
                    ast::LitKind::Bool(b) => U256::from_u64(*b as u64),
                    _ => return Err(EvalError { msg: "unsupported literal".into() }),
                };
                match sub {
                    Some(s) => {
                        let mult: u128 = match s.data {
                            ast::SubDenomination::Wei => 1,
                            ast::SubDenomination::Gwei => 1_000_000_000,
                            ast::SubDenomination::Ether => 1_000_000_000_000_000_000,
                            ast::SubDenomination::Seconds => 1,
                            ast::SubDenomination::Minutes => 60,
                            ast::SubDenomination::Hours => 3600,
                            ast::SubDenomination::Days => 86400,
                            ast::SubDenomination::Weeks => 604800,
                            ast::SubDenomination::Years => 31536000,
                        };
                        base.checked_mul(U256::from_u128(mult)).ok_or(EvalError { msg: "arithmetic overflow".into() })?
                    }
                    None => base,
                }
            }
            Ident(ident) => {
                let res = self.cx.lookup(ident.name, &[], self.contract, self.source);
                match res.as_deref() {
                    Some([Res::Item(ItemId::Variable(vid)), ..]) => {
                        let v = &self.cx.hir.variables[*vid];
                        if v.mutability != Some(ast::VarMut::Constant) {
                            return Err(EvalError { msg: "only constant variables are allowed".into() });
                        }
                        let Some(init) = v.ast.and_then(|a| a.initializer.as_ref()) else {
                            return Err(EvalError { msg: "unsupported expression".into() });
                        };
                        let saved = (self.contract, self.source);
                        self.contract = v.contract;
                        self.source = v.source;
                        let r = self.eval(init);
                        self.contract = saved.0;
                        self.source = saved.1;
                        r?
                    }
                    _ => return Err(EvalError { msg: "unsupported expression".into() }),
                }
            }
            Binary(a, op, b) => {
                let x = self.eval(a)?;
                let y = self.eval(b)?;
                use ast::BinOpKind::*;
                let overflow = || EvalError { msg: "arithmetic overflow".into() };
                match op.data {
                    Add => x.checked_add(y).ok_or_else(overflow)?,
                    Sub => x.checked_sub(y).ok_or_else(overflow)?,
                    Mul => x.checked_mul(y).ok_or_else(overflow)?,
                    Div => x.div_rem(y).ok_or(EvalError { msg: "attempted to divide by zero".into() })?.0,
                    Rem => {
                        x.div_rem(y)
                            .ok_or(EvalError { msg: "attempted to calculate the remainder with a divisor of zero".into() })?
                            .1
                    }
                    Pow => x.checked_pow(y).ok_or_else(overflow)?,
                    Shl => match y.to_u64() {
                        Some(n) if n < 256 => x.shl(n as u32),
                        _ => U256::ZERO,
                    },
                    Shr | Sar => match y.to_u64() {
                        Some(n) if n < 256 => x.shr(n as u32),
                        _ => U256::ZERO,
                    },
                    BitAnd => x.bitand(y),
                    BitOr => x.bitor(y),
                    BitXor => x.bitxor(y),
                    _ => return Err(EvalError { msg: "unsupported binary operation".into() }),
                }
            }
            Unary(op, a) => {
                let x = self.eval(a)?;
                match op.data {
                    ast::UnOpKind::Neg => x.wrapping_neg(),
                    ast::UnOpKind::BitNot => x.not(),
                    _ => return Err(EvalError { msg: "unsupported unary operation".into() }),
                }
            }
            Tuple(v) if v.len() == 1 && v[0].is_some() => self.eval(v[0].as_ref().unwrap())?,
            _ => return Err(EvalError { msg: "unsupported expression".into() }),
        };
        self.depth -= 1;
        Ok(r)
    }
}

fn eval_var_array_sizes(cx: &mut LowerCtx<'_, '_>, vid: VariableId) {
    let Some(v_ast) = cx.hir.variables[vid].ast else { return };
    let (contract, source) = (cx.hir.variables[vid].contract, cx.hir.variables[vid].source);
    let mut ty = cx.hir.variables[vid].ty.clone();
    eval_sizes_rec(cx, &mut ty, &v_ast.ty, contract, source);
    cx.hir.variables[vid].ty = ty;
}

fn eval_sizes_rec(cx: &mut LowerCtx<'_, '_>, ty: &mut Type, ast_ty: &ast::Type, contract: Option<ContractId>, source: SourceId) {
    match (&mut ty.kind, &ast_ty.kind) {
        (TypeKind::Array(inner, size), ast::TypeKind::Array(ainner, asize)) => {
            eval_sizes_rec(cx, inner, ainner, contract, source);
            if let (Some(size), Some(expr)) = (size, asize) {
                let mut ev = ConstEval { cx, contract, source, depth: 0 };
                match ev.eval(expr) {
                    Ok(v) => {
                        if v.is_zero() {
                            cx.dcx.emit(Diag::new(Level::Error, "array length must be greater than zero").span(expr.span));
                        }
                        *size = ArraySize::Known(v.to_dec_string());
                    }
                    Err(e) => {
                        cx.dcx.emit(
                            Diag::new(Level::Error, format!("failed to evaluate constant: {}", e.msg))
                                .span(expr.span)
                                .span_label(expr.span, "evaluation of constant value failed here"),
                        );
                    }
                }
            }
        }
        (TypeKind::Mapping(k, v), ast::TypeKind::Mapping(m)) => {
            eval_sizes_rec(cx, k, &m.key, contract, source);
            eval_sizes_rec(cx, v, &m.value, contract, source);
        }
        (TypeKind::Function(f), ast::TypeKind::Function(af)) => {
            for (t, at) in f.parameters.iter_mut().zip(af.parameters.vars.iter()) {
                eval_sizes_rec(cx, t, &at.ty, contract, source);
            }
            if let Some(r) = &af.returns {
                for (t, at) in f.returns.iter_mut().zip(r.vars.iter()) {
                    eval_sizes_rec(cx, t, &at.ty, contract, source);
                }
            }
        }
        _ => {}
    }
}

// ---- data locations ----

/// Whether a type is a reference type requiring a data location.
pub fn is_reference_type(hir: &Hir, ty: &Type) -> bool {
    match &ty.kind {
        TypeKind::Elementary(ElementaryType::String | ElementaryType::Bytes) => true,
        TypeKind::Array(..) | TypeKind::Mapping(..) => true,
        TypeKind::Custom(ItemId::Struct(_)) => true,
        TypeKind::Custom(ItemId::Udvt(u)) => {
            let _ = u;
            false
        }
        _ => {
            let _ = hir;
            false
        }
    }
}

pub fn contains_mapping(hir: &Hir, ty: &Type, depth: usize) -> bool {
    if depth > 32 {
        return false;
    }
    match &ty.kind {
        TypeKind::Mapping(..) => true,
        TypeKind::Array(inner, _) => contains_mapping(hir, inner, depth + 1),
        TypeKind::Custom(ItemId::Struct(s)) => {
            hir.structs[*s].fields.iter().any(|&f| contains_mapping(hir, &hir.variables[f].ty, depth + 1))
        }
        _ => false,
    }
}

pub fn contains_internal_function(hir: &Hir, ty: &Type, depth: usize) -> bool {
    if depth > 32 {
        return false;
    }
    match &ty.kind {
        TypeKind::Function(f) => !matches!(f.visibility, Visibility::External | Visibility::Public),
        TypeKind::Array(inner, _) => contains_internal_function(hir, inner, depth + 1),
        TypeKind::Mapping(_, v) => contains_internal_function(hir, v, depth + 1),
        TypeKind::Custom(ItemId::Struct(s)) => {
            hir.structs[*s].fields.iter().any(|&f| contains_internal_function(hir, &hir.variables[f].ty, depth + 1))
        }
        _ => false,
    }
}

fn check_data_location(cx: &mut LowerCtx<'_, '_>, vid: VariableId) {
    let v = &cx.hir.variables[vid];
    let span = v.span;
    let ty = v.ty.clone();
    let kind = v.kind;
    let loc = v.data_location;
    let is_ref = is_reference_type(&cx.hir, &ty);
    if !is_ref {
        if let Some(l) = loc {
            if !(l == DataLocation::Transient && kind == VarKind::State) {
                cx.dcx.emit(
                    Diag::new(Level::Error, "data location can only be specified for array, struct or mapping types").span(span),
                );
            }
        }
    } else {
        // Determine allowed locations.
        let (required, allowed): (bool, Vec<DataLocation>) = match kind {
            VarKind::State | VarKind::Constant => (false, vec![DataLocation::Transient]),
            VarKind::Struct | VarKind::Event | VarKind::Error => (false, vec![]),
            VarKind::Statement | VarKind::TryCatch => {
                (true, vec![DataLocation::Memory, DataLocation::Storage, DataLocation::Calldata])
            }
            VarKind::FunctionTypeParam => (true, vec![DataLocation::Memory, DataLocation::Storage, DataLocation::Calldata]),
            VarKind::FunctionParam | VarKind::FunctionReturn => {
                let f = v.function.map(|f| &cx.hir.functions[f]);
                match f {
                    None => (true, vec![DataLocation::Memory, DataLocation::Storage, DataLocation::Calldata]),
                    Some(f) => {
                        let in_library = f.contract.is_some_and(|c| cx.hir.contracts[c].kind == ast::ContractKind::Library);
                        let in_interface = f.contract.is_some_and(|c| cx.hir.contracts[c].kind == ast::ContractKind::Interface);
                        let allowed = match f.kind {
                            FunctionKind::Constructor => vec![DataLocation::Memory, DataLocation::Storage],
                            FunctionKind::Modifier => vec![DataLocation::Memory, DataLocation::Storage, DataLocation::Calldata],
                            _ => match f.visibility {
                                Visibility::External | Visibility::Public if in_library => {
                                    vec![DataLocation::Memory, DataLocation::Storage, DataLocation::Calldata]
                                }
                                Visibility::External | Visibility::Public => {
                                    let _ = in_interface;
                                    vec![DataLocation::Memory, DataLocation::Calldata]
                                }
                                _ => vec![DataLocation::Memory, DataLocation::Storage, DataLocation::Calldata],
                            },
                        };
                        (true, allowed)
                    }
                }
            }
        };
        match loc {
            None => {
                if required {
                    cx.dcx.emit(Diag::new(Level::Error, "expected data location").span(span));
                }
            }
            Some(l) => {
                if !allowed.contains(&l) {
                    cx.dcx.emit(Diag::new(Level::Error, format!("invalid data location `{}`", l.to_str())).span(span));
                }
            }
        }
    }
    // Public function parameter/return type restrictions.
    if matches!(kind, VarKind::FunctionParam | VarKind::FunctionReturn) {
        if let Some(fid) = v.function {
            let f = &cx.hir.functions[fid];
            let in_library = f.contract.is_some_and(|c| cx.hir.contracts[c].kind == ast::ContractKind::Library);
            if matches!(f.visibility, Visibility::Public | Visibility::External) && f.kind != FunctionKind::Modifier && !in_library {
                if contains_mapping(&cx.hir, &ty, 0) {
                    cx.dcx.emit(
                        Diag::new(
                            Level::Error,
                            "types containing mappings cannot be parameter or return types of public functions",
                        )
                        .span(span),
                    );
                }
                if contains_internal_function(&cx.hir, &ty, 0) {
                    cx.dcx.emit(
                        Diag::new(
                            Level::Error,
                            "types containing internal function pointers cannot be parameter or return types of public functions",
                        )
                        .span(span),
                    );
                }
            }
        }
    }
}

// ---- recursive structs ----

fn struct_field_structs(hir: &Hir, ty: &Type, out: &mut Vec<StructId>) {
    match &ty.kind {
        TypeKind::Custom(ItemId::Struct(s)) => out.push(*s),
        TypeKind::Array(inner, Some(_)) => struct_field_structs(hir, inner, out),
        _ => {}
    }
}

fn check_recursive_structs(cx: &mut LowerCtx<'_, '_>) {
    let n = cx.hir.structs.len();
    let mut visited = vec![false; n];
    for root in 0..n {
        if visited[root] {
            continue;
        }
        let mut path: Vec<StructId> = Vec::new();
        let mut reported: Vec<StructId> = Vec::new();
        dfs(cx, root, root, &mut path, &mut visited, &mut reported);
        visited[root] = true;
        for s in reported {
            let span = cx.hir.structs[s].span;
            cx.dcx.emit(Diag::new(Level::Error, "recursive struct definition").span(span));
        }
    }

    fn dfs(
        cx: &LowerCtx<'_, '_>,
        root: StructId,
        s: StructId,
        path: &mut Vec<StructId>,
        visited: &mut Vec<bool>,
        reported: &mut Vec<StructId>,
    ) -> bool {
        let fields = cx.hir.structs[s].fields.clone();
        for f in fields {
            let mut targets = Vec::new();
            struct_field_structs(&cx.hir, &cx.hir.variables[f].ty, &mut targets);
            for t in targets {
                if t == root {
                    reported.extend(path.iter().copied());
                    reported.push(root);
                    for &p in path.iter() {
                        visited[p] = true;
                    }
                    return true;
                }
                if let Some(idx) = path.iter().position(|&p| p == t) {
                    reported.extend(path[idx..].iter().copied());
                    for &p in path.iter() {
                        visited[p] = true;
                    }
                    return true;
                }
                if visited[t] {
                    continue;
                }
                path.push(t);
                if dfs(cx, root, t, path, visited, reported) {
                    return true;
                }
                path.pop();
                visited[t] = true;
            }
        }
        false
    }
}
