new='''fn type_has_err(ty: &Type) -> bool {
    match &ty.kind {
        TypeKind::Err => true,
        TypeKind::Array(inner, _) => type_has_err(inner),
        TypeKind::Mapping(k, v) => type_has_err(k) || type_has_err(v),
        TypeKind::Function(f) => f.parameters.iter().chain(f.returns.iter()).any(type_has_err),
        _ => false,
    }
}

#[derive(Clone)]
struct LocCtx {
    required: bool,
    allowed: Vec<DataLocation>,
    /// Description for the note, e.g. "public function parameter".
    desc: String,
    /// Whether to also check public-function type restrictions (mappings, internal fn pointers).
    public_restrictions: bool,
}

fn fmt_list(items: &[&str]) -> String {
    match items.len() {
        0 => String::new(),
        1 => items[0].to_string(),
        2 => format!("{} or {}", items[0], items[1]),
        _ => {
            let mut s = String::new();
            for (i, it) in items.iter().enumerate() {
                if i == items.len() - 1 {
                    s.push_str("or ");
                    s.push_str(it);
                } else {
                    s.push_str(it);
                    s.push_str(", ");
                }
            }
            s
        }
    }
}

fn loc_note(ctx: &LocCtx, got: Option<DataLocation>) -> String {
    let names: Vec<String> = if ctx.allowed.is_empty() {
        vec!["`none`".to_string()]
    } else if matches!(ctx.desc.as_str(), "state variable") {
        vec!["`none`".to_string(), "`transient`".to_string()]
    } else {
        ctx.allowed.iter().map(|l| format!("`{}`", l.to_str())).collect()
    };
    let refs: Vec<&str> = names.iter().map(|s| s.as_str()).collect();
    let mut s = format!("data location must be {} for {}", fmt_list(&refs), ctx.desc);
    if let Some(g) = got {
        s.push_str(&format!(", but got `{}`", g.to_str()));
    }
    s
}

fn function_param_ctx(cx: &LowerCtx<'_, '_>, fid: FunctionId, is_return: bool) -> LocCtx {
    let f = &cx.hir.functions[fid];
    let in_library = f.contract.is_some_and(|c| cx.hir.contracts[c].kind == ast::ContractKind::Library);
    let all = vec![DataLocation::Memory, DataLocation::Storage, DataLocation::Calldata];
    let (allowed, vis_desc) = match f.kind {
        FunctionKind::Constructor => (vec![DataLocation::Memory, DataLocation::Storage], String::new()),
        FunctionKind::Modifier => (all.clone(), "internal ".to_string()),
        _ => {
            let vis = if f.contract.is_none() { Visibility::Internal } else { f.visibility };
            match vis {
                Visibility::External | Visibility::Public if in_library => (all.clone(), format!("{} ", vis.to_str())),
                Visibility::External | Visibility::Public => {
                    (vec![DataLocation::Memory, DataLocation::Calldata], format!("{} ", vis.to_str()))
                }
                _ => (all.clone(), format!("{} ", vis.to_str())),
            }
        }
    };
    let desc = if is_return {
        format!("{vis_desc}function return parameter")
    } else {
        format!("{vis_desc}function parameter")
    };
    let public_restrictions = f.kind != FunctionKind::Modifier
        && !in_library
        && matches!(f.visibility, Visibility::Public | Visibility::External)
        && f.contract.is_some();
    LocCtx { required: true, allowed, desc, public_restrictions }
}

fn check_data_location(cx: &mut LowerCtx<'_, '_>, vid: VariableId) {
    let v = &cx.hir.variables[vid];
    let Some(v_ast) = v.ast else { return };
    let ty = v.ty.clone();
    let kind = v.kind;
    let all = vec![DataLocation::Memory, DataLocation::Storage, DataLocation::Calldata];
    let ctx = match kind {
        VarKind::State | VarKind::Constant => LocCtx {
            required: false,
            allowed: vec![DataLocation::Transient],
            desc: "state variable".into(),
            public_restrictions: false,
        },
        VarKind::Struct | VarKind::Event | VarKind::Error => {
            LocCtx { required: false, allowed: vec![], desc: "variable".into(), public_restrictions: false }
        }
        VarKind::Statement => LocCtx { required: true, allowed: all, desc: "variable".into(), public_restrictions: false },
        VarKind::TryCatch => LocCtx {
            required: true,
            allowed: vec![DataLocation::Memory],
            desc: "try/catch clause".into(),
            public_restrictions: false,
        },
        VarKind::FunctionTypeParam => LocCtx { required: true, allowed: all, desc: "internal function parameter".into(), public_restrictions: false },
        VarKind::FunctionParam | VarKind::FunctionReturn => match v.function {
            Some(fid) => function_param_ctx(cx, fid, kind == VarKind::FunctionReturn),
            None => LocCtx { required: true, allowed: all, desc: "internal function parameter".into(), public_restrictions: false },
        },
    };
    check_var_loc(cx, &ty, v_ast, &ctx, kind);
}

fn check_var_loc(cx: &mut LowerCtx<'_, '_>, ty: &Type, v_ast: &ast::VariableDefinition, ctx: &LocCtx, kind: VarKind) {
    let span = v_ast.span;
    let loc = v_ast.data_location.map(|l| l.data);
    if type_has_err(ty) {
        return;
    }
    let is_ref = is_reference_type(&cx.hir, ty);
    if !is_ref {
        if let Some(l) = loc {
            if !(l == DataLocation::Transient && matches!(kind, VarKind::State | VarKind::Constant)) {
                cx.dcx.emit(
                    Diag::new(Level::Error, "data location can only be specified for array, struct or mapping types").span(span),
                );
            }
        }
    } else {
        match loc {
            None => {
                if ctx.required {
                    cx.dcx.emit(Diag::new(Level::Error, "expected data location").span(span).note(loc_note(ctx, None)));
                }
            }
            Some(l) => {
                if !ctx.allowed.contains(&l) {
                    cx.dcx.emit(
                        Diag::new(Level::Error, format!("invalid data location `{}`", l.to_str()))
                            .span(span)
                            .note(loc_note(ctx, Some(l))),
                    );
                }
            }
        }
    }
    if ctx.public_restrictions {
        if contains_mapping(&cx.hir, ty, 0) {
            cx.dcx.emit(
                Diag::new(Level::Error, "types containing mappings cannot be parameter or return types of public functions")
                    .span(ty.span),
            );
        }
        if contains_internal_function(&cx.hir, ty, 0) {
            cx.dcx.emit(
                Diag::new(
                    Level::Error,
                    "types containing internal function pointers cannot be parameter or return types of public functions",
                )
                .span(ty.span),
            );
        }
    }
    // Nested function types: check their parameters with the same context.
    check_nested_fn_types(cx, ty, &v_ast.ty, ctx, kind);
}

fn check_nested_fn_types(cx: &mut LowerCtx<'_, '_>, ty: &Type, ast_ty: &ast::Type, ctx: &LocCtx, kind: VarKind) {
    match (&ty.kind, &ast_ty.kind) {
        (TypeKind::Array(inner, _), ast::TypeKind::Array(ainner, _)) => check_nested_fn_types(cx, inner, ainner, ctx, kind),
        (TypeKind::Mapping(k, v), ast::TypeKind::Mapping(m)) => {
            check_nested_fn_types(cx, k, &m.key, ctx, kind);
            check_nested_fn_types(cx, v, &m.value, ctx, kind);
        }
        (TypeKind::Function(f), ast::TypeKind::Function(af)) => {
            let base_ctx = match kind {
                VarKind::FunctionParam | VarKind::FunctionReturn | VarKind::FunctionTypeParam => ctx.clone(),
                _ => LocCtx {
                    required: true,
                    allowed: vec![DataLocation::Memory, DataLocation::Storage, DataLocation::Calldata],
                    desc: "internal function parameter".into(),
                    public_restrictions: false,
                },
            };
            let pctx = LocCtx { public_restrictions: false, ..base_ctx.clone() };
            for (t, at) in f.parameters.iter().zip(af.parameters.vars.iter()) {
                let c = LocCtx { desc: pctx.desc.replace("return parameter", "parameter"), ..pctx.clone() };
                check_var_loc(cx, t, at, &c, VarKind::FunctionTypeParam);
            }
            if let Some(r) = &af.returns {
                for (t, at) in f.returns.iter().zip(r.vars.iter()) {
                    let c = LocCtx { desc: pctx.desc.replace("return parameter", "parameter").replace("parameter", "return parameter"), ..pctx.clone() };
                    check_var_loc(cx, t, at, &c, VarKind::FunctionTypeParam);
                }
            }
        }
        _ => {}
    }
}

