cat > /workspace/src/abi.rs <<'EOF'
//! ABI and function selector output.

use crate::ast::{ElementaryType, FunctionKind, StateMutability, Visibility};
use crate::sema::hir::*;
use crate::source_map::SourceMap;
use serde_json::{json, Map, Value};
use std::collections::BTreeMap;

pub fn emit(hir: &Hir, kinds: &[String], _sm: &SourceMap) -> Value {
    let want_abi = kinds.iter().any(|k| k == "abi");
    let want_hashes = kinds.iter().any(|k| k == "hashes");
    let mut contracts: BTreeMap<String, Value> = BTreeMap::new();
    for (cid, c) in hir.contracts.iter().enumerate() {
        let file = hir.sources[c.source].file.name.display();
        let key = format!("{file}:{}", c.name.name);
        let mut obj = Map::new();
        let items = contract_abi(hir, cid);
        if want_abi {
            obj.insert("abi".into(), Value::Array(items.iter().map(|i| i.json.clone()).collect()));
        }
        if want_hashes {
            let mut hashes: BTreeMap<String, String> = BTreeMap::new();
            for item in &items {
                if let Some(sig) = &item.signature {
                    hashes.insert(sig.clone(), crate::keccak::selector_hex(sig));
                }
            }
            let mut m = Map::new();
            for (k, v) in hashes {
                m.insert(k, Value::String(v));
            }
            obj.insert("hashes".into(), Value::Object(m));
        }
        contracts.insert(key, Value::Object(obj));
    }
    let mut out = Map::new();
    let mut cm = Map::new();
    for (k, v) in contracts {
        cm.insert(k, v);
    }
    out.insert("contracts".into(), Value::Object(cm));
    out.insert("version".into(), Value::String("0.1.8".into()));
    Value::Object(out)
}

struct AbiItem {
    sort_key: (u8, String),
    json: Value,
    signature: Option<String>,
}

fn sm_str(sm: StateMutability) -> &'static str {
    sm.to_str()
}

/// ABI representation of a type: (abi type, internal type, components, canonical sig type)
struct AbiType {
    ty: String,
    internal: String,
    components: Option<Vec<Value>>,
    sig: String,
}

fn qualified_name(hir: &Hir, contract: Option<ContractId>, name: &str) -> String {
    match contract {
        Some(c) => format!("{}.{}", hir.contracts[c].name.name, name),
        None => name.to_string(),
    }
}

fn abi_type(hir: &Hir, ty: &Type) -> AbiType {
    match &ty.kind {
        TypeKind::Elementary(e) => {
            let s = e.to_abi_str();
            AbiType { ty: s.clone(), internal: e.to_internal_str(), components: None, sig: s }
        }
        TypeKind::Array(inner, size) => {
            let inner_t = abi_type(hir, inner);
            let suffix = match size {
                Some(ArraySize::Known(n)) => format!("[{n}]"),
                Some(ArraySize::Unknown) => "[]".to_string(),
                None => "[]".to_string(),
            };
            AbiType {
                ty: format!("{}{}", inner_t.ty, suffix),
                internal: format!("{}{}", inner_t.internal, suffix),
                components: inner_t.components,
                sig: format!("{}{}", inner_t.sig, suffix),
            }
        }
        TypeKind::Mapping(..) => AbiType { ty: "mapping".into(), internal: "mapping".into(), components: None, sig: "mapping".into() },
        TypeKind::Function(f) => {
            let params: Vec<String> = f.parameters.iter().map(|p| abi_type(hir, p).internal).collect();
            let rets: Vec<String> = f.returns.iter().map(|p| abi_type(hir, p).internal).collect();
            let mut s = format!("function ({})", params.join(","));
            match f.state_mutability {
                StateMutability::NonPayable => {}
                m => {
                    s.push(' ');
                    s.push_str(m.to_str());
                }
            }
            s.push(' ');
            s.push_str(match f.visibility {
                Visibility::External | Visibility::Public => "external",
                Visibility::Internal | Visibility::Private => "internal",
            });
            if !rets.is_empty() {
                s.push_str(&format!(" returns ({})", rets.join(",")));
            }
            AbiType { ty: "function".into(), internal: s, components: None, sig: "function".into() }
        }
        TypeKind::Custom(id) => match *id {
            ItemId::Contract(c) => AbiType {
                ty: "address".into(),
                internal: format!("contract {}", hir.contracts[c].name.name),
                components: None,
                sig: "address".into(),
            },
            ItemId::Enum(e) => {
                let en = &hir.enums[e];
                AbiType {
                    ty: "uint8".into(),
                    internal: format!("enum {}", qualified_name(hir, en.contract, en.name.as_str())),
                    components: None,
                    sig: "uint8".into(),
                }
            }
            ItemId::Udvt(u) => {
                let ud = &hir.udvts[u];
                let inner = abi_type(hir, &ud.ty);
                AbiType {
                    ty: inner.ty,
                    internal: qualified_name(hir, ud.contract, ud.name.as_str()),
                    components: None,
                    sig: inner.sig,
                }
            }
            ItemId::Struct(s) => {
                let st = &hir.structs[s];
                let mut comps = Vec::new();
                let mut sigs = Vec::new();
                for &f in &st.fields {
                    let v = &hir.variables[f];
                    let t = abi_type(hir, &v.ty);
                    comps.push(param_json(v.name.map(|n| n.name.as_str()).unwrap_or(""), &t, None));
                    sigs.push(t.sig);
                }
                AbiType {
                    ty: "tuple".into(),
                    internal: format!("struct {}", qualified_name(hir, st.contract, st.name.as_str())),
                    components: Some(comps),
                    sig: format!("({})", sigs.join(",")),
                }
            }
            _ => AbiType { ty: "?".into(), internal: "?".into(), components: None, sig: "?".into() },
        },
        TypeKind::Err => AbiType { ty: "?".into(), internal: "?".into(), components: None, sig: "?".into() },
    }
}

fn param_json(name: &str, t: &AbiType, indexed: Option<bool>) -> Value {
    let mut m = Map::new();
    m.insert("name".into(), Value::String(name.to_string()));
    m.insert("type".into(), Value::String(t.ty.clone()));
    if let Some(i) = indexed {
        m.insert("indexed".into(), Value::Bool(i));
    }
    m.insert("internalType".into(), Value::String(t.internal.clone()));
    if let Some(c) = &t.components {
        m.insert("components".into(), Value::Array(c.clone()));
    }
    Value::Object(m)
}

fn params_json(hir: &Hir, vars: &[VariableId], indexed: bool) -> (Vec<Value>, Vec<String>) {
    let mut out = Vec::new();
    let mut sigs = Vec::new();
    for &vid in vars {
        let v = &hir.variables[vid];
        let t = abi_type(hir, &v.ty);
        let name = v.name.map(|n| n.name.as_str()).unwrap_or("");
        out.push(param_json(name, &t, if indexed { Some(v.indexed) } else { None }));
        sigs.push(t.sig);
    }
    (out, sigs)
}

fn function_item(hir: &Hir, f: &Function) -> AbiItem {
    let (inputs, in_sigs) = params_json(hir, &f.parameters, false);
    let (outputs, _) = params_json(hir, &f.returns, false);
    let name = f.name.map(|n| n.name.as_str().to_string()).unwrap_or_default();
    let mut m = Map::new();
    m.insert("type".into(), json!("function"));
    m.insert("name".into(), Value::String(name.clone()));
    m.insert("inputs".into(), Value::Array(inputs));
    m.insert("outputs".into(), Value::Array(outputs));
    m.insert("stateMutability".into(), json!(sm_str(f.state_mutability)));
    AbiItem {
        sort_key: (4, name.clone()),
        json: Value::Object(m),
        signature: Some(format!("{}({})", name, in_sigs.join(","))),
    }
}

/// Getter for a public state variable.
fn getter_item(hir: &Hir, v: &Variable) -> Option<AbiItem> {
    let name = v.name?.name.as_str().to_string();
    let mut inputs = Vec::new();
    let mut in_sigs = Vec::new();
    let mut ty = &v.ty;
    loop {
        match &ty.kind {
            TypeKind::Mapping(k, val) => {
                let t = abi_type(hir, k);
                inputs.push(param_json("", &t, None));
                in_sigs.push(t.sig);
                ty = val;
            }
            TypeKind::Array(inner, _) => {
                let t = abi_type(hir, &Type { span: ty.span, kind: TypeKind::Elementary(ElementaryType::UInt(0)) });
                inputs.push(param_json("", &t, None));
                in_sigs.push(t.sig);
                ty = inner;
            }
            _ => break,
        }
    }
    let mut outputs = Vec::new();
    match &ty.kind {
        TypeKind::Custom(ItemId::Struct(s)) => {
            let st = &hir.structs[*s];
            for &f in &st.fields {
                let fv = &hir.variables[f];
                if matches!(fv.ty.kind, TypeKind::Array(..) | TypeKind::Mapping(..)) {
                    continue;
                }
                let t = abi_type(hir, &fv.ty);
                outputs.push(param_json(fv.name.map(|n| n.name.as_str()).unwrap_or(""), &t, None));
            }
        }
        _ => {
            let t = abi_type(hir, ty);
            outputs.push(param_json("", &t, None));
        }
    }
    let mut m = Map::new();
    m.insert("type".into(), json!("function"));
    m.insert("name".into(), Value::String(name.clone()));
    m.insert("inputs".into(), Value::Array(inputs));
    m.insert("outputs".into(), Value::Array(outputs));
    m.insert("stateMutability".into(), json!("view"));
    Some(AbiItem {
        sort_key: (4, name.clone()),
        json: Value::Object(m),
        signature: Some(format!("{}({})", name, in_sigs.join(","))),
    })
}

fn function_sig_key(hir: &Hir, f: &Function) -> String {
    let (_, sigs) = params_json(hir, &f.parameters, false);
    format!("{}({})", f.name.map(|n| n.name.as_str()).unwrap_or(""), sigs.join(","))
}

fn contract_abi(hir: &Hir, cid: ContractId) -> Vec<AbiItem> {
    let c = &hir.contracts[cid];
    let mut items: Vec<AbiItem> = Vec::new();
    let mut seen_sigs: std::collections::HashSet<String> = std::collections::HashSet::new();
    // Constructor, fallback, receive: own only.
    if let Some(ctor) = c.ctor {
        let f = &hir.functions[ctor];
        let (inputs, _) = params_json(hir, &f.parameters, false);
        let mut m = Map::new();
        m.insert("type".into(), json!("constructor"));
        m.insert("inputs".into(), Value::Array(inputs));
        m.insert("stateMutability".into(), json!(sm_str(f.state_mutability)));
        items.push(AbiItem { sort_key: (0, String::new()), json: Value::Object(m), signature: None });
    }
    if let Some(fb) = c.fallback {
        let f = &hir.functions[fb];
        let mut m = Map::new();
        m.insert("type".into(), json!("fallback"));
        m.insert("stateMutability".into(), json!(sm_str(f.state_mutability)));
        items.push(AbiItem { sort_key: (3, String::new()), json: Value::Object(m), signature: None });
    }
    if let Some(rc) = c.receive {
        let f = &hir.functions[rc];
        let mut m = Map::new();
        m.insert("type".into(), json!("receive"));
        m.insert("stateMutability".into(), json!(sm_str(f.state_mutability)));
        items.push(AbiItem { sort_key: (5, String::new()), json: Value::Object(m), signature: None });
    }
    // Walk linearized bases: most derived first.
    for &b in &c.linearized_bases {
        let bc = &hir.contracts[b];
        for &item in &bc.items {
            match item {
                ItemId::Function(fid) => {
                    let f = &hir.functions[fid];
                    if f.kind != FunctionKind::Function {
                        continue;
                    }
                    if !matches!(f.visibility, Visibility::Public | Visibility::External) {
                        continue;
                    }
                    let key = function_sig_key(hir, f);
                    if !seen_sigs.insert(key) {
                        continue;
                    }
                    items.push(function_item(hir, f));
                }
                ItemId::Variable(vid) => {
                    let v = &hir.variables[vid];
                    if v.visibility != Some(Visibility::Public) {
                        continue;
                    }
                    if let Some(g) = getter_item(hir, v) {
                        if let Some(sig) = &g.signature {
                            if !seen_sigs.insert(sig.clone()) {
                                continue;
                            }
                        }
                        items.push(g);
                    }
                }
                ItemId::Event(eid) => {
                    let e = &hir.events[eid];
                    let (inputs, in_sigs) = params_json(hir, &e.parameters, true);
                    let key = format!("event {}({})", e.name.name, in_sigs.join(","));
                    if !seen_sigs.insert(key) {
                        continue;
                    }
                    let mut m = Map::new();
                    m.insert("type".into(), json!("event"));
                    m.insert("name".into(), Value::String(e.name.name.as_str().into()));
                    m.insert("inputs".into(), Value::Array(inputs));
                    m.insert("anonymous".into(), Value::Bool(e.anonymous));
                    items.push(AbiItem {
                        sort_key: (2, e.name.name.as_str().into()),
                        json: Value::Object(m),
                        signature: None,
                    });
                }
                ItemId::Error(eid) => {
                    let e = &hir.errors[eid];
                    let (inputs, in_sigs) = params_json(hir, &e.parameters, false);
                    let key = format!("error {}({})", e.name.name, in_sigs.join(","));
                    if !seen_sigs.insert(key) {
                        continue;
                    }
                    let mut m = Map::new();
                    m.insert("type".into(), json!("error"));
                    m.insert("name".into(), Value::String(e.name.name.as_str().into()));
                    m.insert("inputs".into(), Value::Array(inputs));
                    items.push(AbiItem {
                        sort_key: (1, e.name.name.as_str().into()),
                        json: Value::Object(m),
                        signature: None,
                    });
                }
                _ => {}
            }
        }
    }
    items.sort_by(|a, b| a.sort_key.cmp(&b.sort_key));
    items
}
