// SPDX-License-Identifier: UNLICENSED
pragma solidity >=0.8.0 <0.9.0;
pragma abicoder v2;

type Wad is uint256;
type Ray is uint256;

using { addWad as +, subWad as -, eqWad as ==, ltWad as < } for Wad global;
using WadMath for Wad global;

function addWad(Wad a, Wad b) pure returns (Wad) { return Wad.wrap(Wad.unwrap(a) + Wad.unwrap(b)); }
function subWad(Wad a, Wad b) pure returns (Wad) { return Wad.wrap(Wad.unwrap(a) - Wad.unwrap(b)); }
function eqWad(Wad a, Wad b) pure returns (bool) { return Wad.unwrap(a) == Wad.unwrap(b); }
function ltWad(Wad a, Wad b) pure returns (bool) { return Wad.unwrap(a) < Wad.unwrap(b); }

library WadMath {
    uint256 internal constant WAD = 1e18;
    function mul(Wad a, Wad b) internal pure returns (Wad) {
        return Wad.wrap(Wad.unwrap(a) * Wad.unwrap(b) / WAD);
    }
    function toRay(Wad a) internal pure returns (Ray) {
        return Ray.wrap(Wad.unwrap(a) * 1e9);
    }
}

struct Order {
    address maker;
    Wad amount;
    uint64 deadline;
    bytes signature;
    uint256[] fills;
}

enum Status { Open, Filled, Cancelled }

event GlobalEvent(uint256 indexed id, Order order);
error GlobalError(string reason);

interface IOracle {
    struct Price { uint128 value; uint64 timestamp; }
    function price(address asset) external view returns (Price memory);
    function update(address asset, Price calldata p) external;
}

contract Exchange {
    mapping(bytes32 => Order) public orders;
    mapping(bytes32 => Status) public statuses;
    mapping(address => mapping(bytes4 => bool)) public approvals;
    Order[] public history;
    IOracle public immutable oracle;
    address payable public feeRecipient;
    uint256 public constant FEE_BPS = 30;
    bytes32 public constant DOMAIN_SEPARATOR = keccak256("Exchange");
    Wad public totalVolume;
    Status[3] public statusCounts;
    uint8[2][] public grid;
    bytes4[] public selectors;
    string[] public names;
    bool internal locked;

    event OrderPlaced(bytes32 indexed id, address indexed maker, Wad amount);
    event OrderFilled(bytes32 indexed id, address taker, uint256[] fills) anonymous;
    error OrderExpired(bytes32 id, uint64 deadline, uint64 now_);
    error Reentrancy();

    modifier nonReentrant() {
        if (locked) revert Reentrancy();
        locked = true;
        _;
        locked = false;
    }

    modifier onlyAfter(uint64 t) {
        require(block.timestamp > t, "too early");
        _;
    }

    constructor(IOracle _oracle, address payable _fee) payable {
        oracle = _oracle;
        feeRecipient = _fee;
    }

    receive() external payable {}
    fallback(bytes calldata input) external payable returns (bytes memory output) {
        output = input;
    }

    function place(Order calldata order) external nonReentrant returns (bytes32 id) {
        id = keccak256(abi.encode(order.maker, order.amount, order.deadline));
        if (order.deadline < block.timestamp) {
            revert OrderExpired(id, order.deadline, uint64(block.timestamp));
        }
        orders[id] = order;
        statuses[id] = Status.Open;
        history.push(order);
        totalVolume = totalVolume + order.amount;
        emit OrderPlaced(id, order.maker, order.amount);
    }

    function fill(bytes32 id, uint256[] memory fills) public virtual onlyAfter(0) {
        Order storage o = orders[id];
        for (uint256 i; i < fills.length; i++) {
            o.fills.push(fills[i]);
        }
        statuses[id] = Status.Filled;
        emit OrderFilled(id, msg.sender, fills);
    }

    function cancel(bytes32 id) external {
        delete orders[id];
        statuses[id] = Status.Cancelled;
    }

    function quote(address asset, Wad amount) external view returns (Wad, Ray) {
        IOracle.Price memory p = oracle.price(asset);
        Wad value = amount.mul(Wad.wrap(uint256(p.value)));
        return (value, value.toRay());
    }

    function batch(bytes[] calldata calls) external returns (bytes[] memory results) {
        results = new bytes[](calls.length);
        for (uint256 i = 0; i < calls.length; i++) {
            (bool ok, bytes memory ret) = address(this).delegatecall(calls[i]);
            if (!ok) {
                assembly {
                    revert(add(ret, 32), mload(ret))
                }
            }
            results[i] = ret;
        }
    }

    function selectorOf(string memory sig) public pure returns (bytes4 sel) {
        sel = bytes4(keccak256(bytes(sig)));
    }

    function math(int256 x, uint256 y) public pure returns (int256 r) {
        unchecked {
            r = x * 2 - int256(y) / 3 % 7;
            r = r ** 2;
            r = -r;
            r = ~r;
            r = r << 1 >> 2;
            r = r & 0xff | 0x100 ^ 0x1;
        }
        bool b = x > 0 && y < 10 || !(x == 0);
        r = b ? r : -r;
        r += 1; r -= 1; r *= 1; r /= 1; r %= 7; r <<= 1; r >>= 1; r |= 1; r &= 1; r ^= 1;
        r++; r--; ++r; --r;
    }

    function asm(uint256 a, uint256 b) public pure returns (uint256 result) {
        assembly ("memory-safe") {
            function f(x, y) -> z {
                z := add(x, y)
                if iszero(z) { z := 1 }
            }
            let i := 0
            for { } lt(i, 10) { i := add(i, 1) } {
                if eq(i, 5) { continue }
                if eq(i, 8) { break }
                result := f(result, a)
            }
            switch b
            case 0 { result := 0 }
            case 1 { result := add(result, 1) }
            default { result := mul(result, b) }
            let x, y := g()
            function g() -> p, q { p := 1 q := 2 leave }
            result := add(result, x)
            mstore(0x40, add(mload(0x40), 0x20))
            let s := sload(totalVolume.slot)
            let o := orders.slot
            result := add(result, s)
        }
    }

    function tuples() public pure returns (uint256 a, uint256 b) {
        (a, b) = (1, 2);
        (a, ) = (b, a);
        (, b) = (a, b);
        uint256[] memory arr = new uint256[](2);
        (arr[0], arr[1]) = (b, a);
    }

    function ternaryAndLiterals() public pure returns (uint256) {
        uint256 x = 1 ether + 1 gwei + 1 wei + 1 seconds + 1 minutes + 1 hours + 1 days + 1 weeks;
        x += 0x1234_5678 + 1_000_000 + 1e18 + 2.5e3;
        string memory s = "hello" " " "world";
        bytes memory h = hex"deadbeef" hex"cafe";
        string memory u = unicode"héllo";
        address a = 0x5B38Da6a701c568545dCfcB03FcB875f56beddC4;
        bool t = true || false;
        bytes32 z = bytes32(0);
        return t ? x + bytes(s).length + h.length + bytes(u).length + uint160(a) + uint256(z) : 0;
    }

    function ext() external view returns (address, uint256, bytes memory) {
        return (address(this), address(this).balance, address(this).code);
    }

    function callOpts(address payable to) external payable {
        to.transfer(msg.value / 2);
        (bool ok,) = to.call{value: msg.value / 4, gas: 50000}("");
        require(ok);
        Exchange(payable(address(this))).cancel{gas: 100000}(bytes32(0));
        new Exchange{value: 1, salt: bytes32(0)}(oracle, to);
    }

    function dowhile() public pure {
        uint256 i;
        do { i++; } while (i < 10);
        while (i > 0) { i--; if (i == 5) break; else continue; }
    }
}

contract Child is Exchange {
    constructor() Exchange(IOracle(address(0)), payable(address(0))) {}
    function fill(bytes32 id, uint256[] memory fills) public override {
        super.fill(id, fills);
    }
}
