//! Contract-level analysis checks (after lowering).

use super::checks;
use super::hir::*;
use crate::ast::{ContractKind, FunctionKind, StateMutability, Visibility};
use crate::diag::{Diag, DiagCtxt, Level};
use crate::span::Span;
use crate::u256::U256;
use std::collections::HashMap;

pub fn analyze(dcx: &DiagCtxt, hir: &Hir, print_storage: bool) {
    for cid in 0..hir.contracts.len() {
        check_duplicates(dcx, hir, cid);
        check_storage(dcx, hir, cid, print_storage);
        check_functions_basic(dcx, hir, cid);
        check_overrides(dcx, hir, cid);
        check_ambiguous(dcx, hir, cid);
        check_unimplemented(dcx, hir, cid);
    }
}

pub fn print_max_storage_sizes(_dcx: &DiagCtxt, _hir: &Hir) {}

// ---- signatures ----

pub fn function_param_sig(hir: &Hir, f: &Function) -> String {
    crate::abi::params_sig(hir, &f.parameters)
}

fn function_return_sig(hir: &Hir, f: &Function) -> String {
    crate::abi::params_sig(hir, &f.returns)
}

/// Getter signature parts for a public state variable: (param types sig, return types sig).
fn getter_sigs(hir: &Hir, v: &Variable) -> (String, String) {
    crate::abi::getter_sigs(hir, v)
}

// ---- duplicates ----

fn check_duplicates(dcx: &DiagCtxt, hir: &Hir, cid: ContractId) {
    let c = &hir.contracts[cid];
    // Functions: own only.
    let mut funcs: Vec<(String, FunctionId)> = Vec::new();
    for &item in &c.items {
        if let ItemId::Function(fid) = item {
            let f = &hir.functions[fid];
            if f.kind != FunctionKind::Function {
                continue;
            }
            let Some(name) = f.name else { continue };
            funcs.push((format!("{}({})", name.name, function_param_sig(hir, f)), fid));
        }
    }
    report_dups(dcx, hir, &funcs, "function", |fid| hir.functions[fid].name.map(|n| n.span).unwrap_or(hir.functions[fid].span));
    // Events: own + inherited.
    let mut events: Vec<(String, EventId)> = Vec::new();
    for &b in &c.linearized_bases {
        for &item in &hir.contracts[b].items {
            if let ItemId::Event(eid) = item {
                let e = &hir.events[eid];
                events.push((format!("{}({})", e.name.name, crate::abi::params_sig(hir, &e.parameters)), eid));
            }
        }
    }
    report_dups(dcx, hir, &events, "event", |eid| hir.events[eid].name.span);
}

fn report_dups<T: Copy + PartialEq>(
    dcx: &DiagCtxt,
    _hir: &Hir,
    items: &[(String, T)],
    what: &str,
    span_of: impl Fn(T) -> Span,
) {
    let mut reported = vec![false; items.len()];
    for i in 0..items.len() {
        if reported[i] {
            continue;
        }
        let mut others = Vec::new();
        for j in i + 1..items.len() {
            if items[j].0 == items[i].0 {
                others.push(j);
                reported[j] = true;
            }
        }
        if !others.is_empty() {
            let mut d = Diag::new(Level::Error, format!("{what} with same name and parameter types declared twice"))
                .span(span_of(items[i].1));
            for j in others {
                d = d.span_note(span_of(items[j].1), "other declaration");
            }
            dcx.emit(d);
        }
    }
}

// ---- storage ----

pub fn type_storage_slots(hir: &Hir, ty: &Type, depth: usize) -> Option<U256> {
    if depth > 64 {
        return Some(U256::ONE);
    }
    Some(match &ty.kind {
        TypeKind::Array(inner, Some(ArraySize::Known(n))) => {
            let n = U256::from_dec_str(n)?;
            let inner = type_storage_slots(hir, inner, depth + 1)?;
            n.checked_mul(inner)?
        }
        TypeKind::Custom(ItemId::Struct(s)) => {
            let mut total = U256::ONE;
            for &f in &hir.structs[*s].fields {
                let t = type_storage_slots(hir, &hir.variables[f].ty, depth + 1)?;
                total = total.checked_add(t)?;
            }
            total
        }
        _ => U256::ONE,
    })
}

fn check_storage(dcx: &DiagCtxt, hir: &Hir, cid: ContractId, print: bool) {
    let c = &hir.contracts[cid];
    let mut total = Some(U256::ZERO);
    for &b in c.linearized_bases.iter().rev() {
        for &item in &hir.contracts[b].items {
            if let ItemId::Variable(vid) = item {
                let v = &hir.variables[vid];
                if v.mutability.is_some() {
                    continue;
                }
                total = total.and_then(|t| type_storage_slots(hir, &v.ty, 0).and_then(|s| t.checked_add(s)));
            }
        }
    }
    match total {
        Some(t) => {
            if print {
                let file = hir.sources[c.source].file.name.display();
                dcx.emit(
                    Diag::new(
                        Level::Note,
                        format!("{}:{} requires a maximum of {} storage slots", file, c.name.name, t.to_dec_string()),
                    )
                    .span(c.name.span),
                );
            }
        }
        None => {
            dcx.emit(Diag::new(Level::Error, "contract requires too much storage").span(c.name.span));
        }
    }
}

// ---- basic function checks ----

fn check_functions_basic(dcx: &DiagCtxt, hir: &Hir, cid: ContractId) {
    let c = &hir.contracts[cid];
    for &item in &c.items {
        let ItemId::Function(fid) = item else { continue };
        let f = &hir.functions[fid];
        if !f.has_body && f.kind != FunctionKind::Constructor {
            if c.kind == ContractKind::Library {
                dcx.emit(Diag::new(Level::Error, "library functions must be implemented if declared").code(9231).span(f.span));
            } else if c.kind != ContractKind::Interface && !f.marked_virtual {
                dcx.emit(
                    Diag::new(Level::Error, "functions without implementation must be marked virtual").code(5424).span(f.span),
                );
            }
        }
        if f.marked_virtual && f.visibility == Visibility::Private {
            dcx.emit(Diag::new(Level::Error, "`virtual` and `private` cannot be used together").code(3942).span(f.span));
        }
    }
}

// ---- overrides ----

#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
enum Proxy {
    Function(FunctionId),
    Variable(VariableId),
}

impl Proxy {
    fn contract(self, hir: &Hir) -> ContractId {
        match self {
            Proxy::Function(f) => hir.functions[f].contract.unwrap(),
            Proxy::Variable(v) => hir.variables[v].contract.unwrap(),
        }
    }
    fn span(self, hir: &Hir) -> Span {
        match self {
            Proxy::Function(f) => hir.functions[f].span,
            Proxy::Variable(v) => hir.variables[v].span,
        }
    }
    fn is_modifier(self, hir: &Hir) -> bool {
        matches!(self, Proxy::Function(f) if hir.functions[f].kind == FunctionKind::Modifier)
    }
    fn name(self, hir: &Hir) -> String {
        match self {
            Proxy::Function(f) => hir.functions[f].name.map(|n| n.name.as_str().to_string()).unwrap_or_default(),
            Proxy::Variable(v) => hir.variables[v].name.map(|n| n.name.as_str().to_string()).unwrap_or_default(),
        }
    }
    /// Signature key: kind + name + params.
    fn sig(self, hir: &Hir) -> String {
        match self {
            Proxy::Function(f) => {
                let func = &hir.functions[f];
                let prefix = if func.kind == FunctionKind::Modifier { "modifier " } else { "" };
                format!("{}{}({})", prefix, self.name(hir), function_param_sig(hir, func))
            }
            Proxy::Variable(v) => {
                let (p, _) = getter_sigs(hir, &hir.variables[v]);
                format!("{}({})", self.name(hir), p)
            }
        }
    }
    fn returns_sig(self, hir: &Hir) -> String {
        match self {
            Proxy::Function(f) => function_return_sig(hir, &hir.functions[f]),
            Proxy::Variable(v) => getter_sigs(hir, &hir.variables[v]).1,
        }
    }
    fn has_override(self, hir: &Hir) -> bool {
        match self {
            Proxy::Function(f) => hir.functions[f].override_.is_some(),
            Proxy::Variable(v) => hir.variables[v].override_.is_some(),
        }
    }
    fn override_span(self, hir: &Hir) -> Option<Span> {
        match self {
            Proxy::Function(f) => hir.functions[f].override_,
            Proxy::Variable(v) => hir.variables[v].override_,
        }
    }
    fn overrides(self, hir: &Hir) -> Vec<ContractId> {
        match self {
            Proxy::Function(f) => hir.functions[f].overrides.clone(),
            Proxy::Variable(v) => hir.variables[v].overrides.clone(),
        }
    }
    fn visibility(self, hir: &Hir) -> Visibility {
        match self {
            Proxy::Function(f) => hir.functions[f].visibility,
            Proxy::Variable(_) => Visibility::Public,
        }
    }
    fn is_virtual(self, hir: &Hir) -> bool {
        match self {
            Proxy::Function(f) => {
                let func = &hir.functions[f];
                func.marked_virtual
                    || !func.has_body
                    || func.contract.is_some_and(|c| hir.contracts[c].kind == ContractKind::Interface)
            }
            Proxy::Variable(_) => false,
        }
    }
    fn is_implemented(self, hir: &Hir) -> bool {
        match self {
            Proxy::Function(f) => hir.functions[f].has_body,
            Proxy::Variable(_) => true,
        }
    }
    fn desc(self, hir: &Hir) -> &'static str {
        match self {
            Proxy::Function(f) => {
                if hir.functions[f].kind == FunctionKind::Modifier {
                    "modifier"
                } else {
                    "function"
                }
            }
            Proxy::Variable(_) => "public state variable",
        }
    }
}

/// Functions (and public state variables) inherited from direct bases, keyed by signature.
/// Returns, per signature, the list of proxies (one per direct base, most-specific definition).
fn inherited_functions(hir: &Hir, cid: ContractId, out: &mut Vec<(String, Proxy)>, cache: &mut HashMap<ContractId, Vec<(String, Proxy)>>) {
    if let Some(v) = cache.get(&cid) {
        out.extend(v.iter().cloned());
        return;
    }
    let mut result: Vec<(String, Proxy)> = Vec::new();
    for &base in &hir.contracts[cid].bases {
        let mut in_base: Vec<(String, Proxy)> = Vec::new();
        for &item in &hir.contracts[base].items {
            let p = match item {
                ItemId::Function(f) if hir.functions[f].kind != FunctionKind::Constructor => Proxy::Function(f),
                ItemId::Variable(v) if hir.variables[v].visibility == Some(Visibility::Public) => Proxy::Variable(v),
                _ => continue,
            };
            let sig = p.sig(hir);
            if !in_base.iter().any(|(s, _)| *s == sig) {
                in_base.push((sig, p));
            }
        }
        let mut inh = Vec::new();
        inherited_functions(hir, base, &mut inh, cache);
        for (sig, p) in inh {
            if !in_base.iter().any(|(s, _)| *s == sig) {
                in_base.push((sig, p));
            }
        }
        result.extend(in_base);
    }
    cache.insert(cid, result.clone());
    out.extend(result);
}

fn check_overrides(dcx: &DiagCtxt, hir: &Hir, cid: ContractId) {
    let c = &hir.contracts[cid];
    let mut cache = HashMap::new();
    let mut inherited = Vec::new();
    inherited_functions(hir, cid, &mut inherited, &mut cache);

    let mut own: Vec<Proxy> = Vec::new();
    for &item in &c.items {
        if let ItemId::Function(f) = item {
            if hir.functions[f].kind == FunctionKind::Constructor {
                continue;
            }
            own.push(Proxy::Function(f));
        }
    }
    for &item in &c.items {
        if let ItemId::Variable(v) = item {
            let var = &hir.variables[v];
            if var.visibility != Some(Visibility::Public) {
                if var.override_.is_some() {
                    dcx.emit(
                        Diag::new(Level::Error, "override can only be used with public state variables").code(8022).span(var.span),
                    );
                }
                continue;
            }
            own.push(Proxy::Variable(v));
        }
    }
    for item in own {
        check_override_list(dcx, hir, cid, item, &inherited);
    }
}

fn check_override_list(dcx: &DiagCtxt, hir: &Hir, cid: ContractId, item: Proxy, inherited: &[(String, Proxy)]) {
    let sig = item.sig(hir);
    let mut base_functions: Vec<Proxy> = Vec::new();
    for (s, p) in inherited {
        if *s == sig && !base_functions.contains(p) {
            base_functions.push(*p);
        }
    }
    let specified = item.overrides(hir);
    // Duplicates in override list.
    if item.has_override(hir) {
        let mut seen = Vec::new();
        for &c in &specified {
            if seen.contains(&c) {
                dcx.emit(
                    Diag::new(Level::Error, format!("duplicate contract found in override list of `{}`", item.name(hir)))
                        .code(4520)
                        .span(item.span(hir)),
                );
                return;
            }
            seen.push(c);
        }
    }
    let mut expected: Vec<ContractId> = Vec::new();
    for p in &base_functions {
        let c = p.contract(hir);
        if !expected.contains(&c) {
            expected.push(c);
        }
    }
    if item.has_override(hir) && expected.is_empty() {
        let desc = match item {
            Proxy::Function(f) if hir.functions[f].kind == FunctionKind::Modifier => "Modifier",
            Proxy::Function(_) => "Function",
            Proxy::Variable(_) => "public state variable",
        };
        dcx.emit(
            Diag::new(Level::Error, format!("{desc} has override specified but does not override anything"))
                .code(7792)
                .span(item.span(hir)),
        );
    }
    let _ = cid;
    if expected.len() > 1 {
        let mut missing: Vec<ContractId> = expected.iter().copied().filter(|c| !specified.contains(c)).collect();
        missing.sort();
        if !missing.is_empty() {
            let desc = match item {
                Proxy::Function(f) if hir.functions[f].kind == FunctionKind::Modifier => "Modifier",
                Proxy::Function(_) => "Function",
                Proxy::Variable(_) => "Public state variable",
            };
            let names: Vec<String> = missing.iter().map(|c| format!("`{}`", hir.contracts[*c].name.name)).collect();
            let plural = if missing.len() > 1 { "contracts" } else { "contract" };
            dcx.emit(
                Diag::new(Level::Error, format!("{desc} needs to specify overridden {plural} {}", join_and(&names)))
                    .code(4327)
                    .span(item.override_span(hir).unwrap_or(item.span(hir))),
            );
        }
    }
    let mut surplus: Vec<ContractId> = specified.iter().copied().filter(|c| !expected.contains(c)).collect();
    surplus.sort();
    surplus.dedup();
    // Only report contracts that are bases (non-bases were reported during lowering).
    surplus.retain(|c| hir.contracts[cid].linearized_bases.contains(c));
    if !surplus.is_empty() {
        let names: Vec<String> = surplus.iter().map(|c| format!("`{}`", hir.contracts[*c].name.name)).collect();
        let plural = if surplus.len() > 1 { "contracts" } else { "contract" };
        dcx.emit(
            Diag::new(Level::Error, format!("invalid {plural} specified in override list: {}", join_and(&names)))
                .code(2353)
                .span(item.override_span(hir).unwrap_or(item.span(hir))),
        );
    }
    for base in base_functions {
        check_override(dcx, hir, item, base);
    }
}

fn join_and(names: &[String]) -> String {
    match names.len() {
        0 => String::new(),
        1 => names[0].clone(),
        _ => format!("{} and {}", names[..names.len() - 1].join(", "), names[names.len() - 1]),
    }
}

fn check_override(dcx: &DiagCtxt, hir: &Hir, overriding: Proxy, base: Proxy) {
    let base_is_interface_fn =
        matches!(base, Proxy::Function(_)) && hir.contracts[base.contract(hir)].kind == ContractKind::Interface;
    let desc = overriding.desc(hir);
    let base_desc = base.desc(hir);
    if overriding.is_modifier(hir) != base.is_modifier(hir) {
        return;
    }
    if !overriding.has_override(hir) && !base_is_interface_fn {
        dcx.emit(
            Diag::new(Level::Error, format!("overriding {desc} is missing `override` specifier"))
                .code(9456)
                .span(overriding.span(hir))
                .span_note(base.span(hir), format!("overridden {base_desc} is here"))
                .help("add `override` to the function signature"),
        );
    }
    if let Proxy::Variable(_) = base {
        dcx.emit(
            Diag::new(Level::Error, "cannot override public state variable")
                .code(1452)
                .span(base.span(hir))
                .span_note(overriding.span(hir), format!("overriding {desc} is here")),
        );
    } else if !base.is_virtual(hir) {
        dcx.emit(
            Diag::new(Level::Error, format!("cannot override non-virtual {base_desc}"))
                .code(4334)
                .span(base.span(hir))
                .span_note(overriding.span(hir), format!("overriding {desc} is here"))
                .help(format!("add `virtual` to the base {base_desc} to allow overriding")),
        );
    }
    if let Proxy::Variable(_) = overriding {
        if base.visibility(hir) != Visibility::External {
            dcx.emit(
                Diag::new(Level::Error, "public state variable can only override external function")
                    .code(5225)
                    .span(overriding.span(hir))
                    .span_note(base.span(hir), "overridden function is here")
                    .note(format!("base function has `{}` visibility", base.visibility(hir).to_str())),
            );
        }
    } else if overriding.visibility(hir) != base.visibility(hir) {
        if !(base.visibility(hir) == Visibility::External && overriding.visibility(hir) == Visibility::Public) {
            dcx.emit(
                Diag::new(
                    Level::Error,
                    format!(
                        "overriding {desc} changes visibility from `{}` to `{}`",
                        base.visibility(hir).to_str(),
                        overriding.visibility(hir).to_str()
                    ),
                )
                .code(9098)
                .span(overriding.span(hir))
                .span_note(base.span(hir), format!("overridden {base_desc} is here")),
            );
        }
    }
    if let Proxy::Function(bf) = base {
        let bfn = &hir.functions[bf];
        if bfn.kind == FunctionKind::Function {
            if overriding.returns_sig(hir) != base.returns_sig(hir) {
                dcx.emit(
                    Diag::new(Level::Error, format!("overriding {desc} has different return types"))
                        .code(4822)
                        .span(overriding.span(hir))
                        .span_note(base.span(hir), format!("overridden {base_desc} is here")),
                );
            }
            if let Proxy::Function(of) = overriding {
                let ofn = &hir.functions[of];
                let (sm_o, sm_b) = (ofn.state_mutability, bfn.state_mutability);
                if sm_o != sm_b {
                    let allowed = matches!(
                        (sm_b, sm_o),
                        (StateMutability::NonPayable, StateMutability::View)
                            | (StateMutability::NonPayable, StateMutability::Pure)
                            | (StateMutability::View, StateMutability::Pure)
                    );
                    if !allowed {
                        dcx.emit(
                            Diag::new(
                                Level::Error,
                                format!(
                                    "overriding function changes state mutability from `{}` to `{}`",
                                    sm_b.to_str(),
                                    sm_o.to_str()
                                ),
                            )
                            .code(6959)
                            .span(overriding.span(hir)),
                        );
                    }
                }
            }
        }
    }
}

// ---- ambiguous overrides ----

fn check_ambiguous(dcx: &DiagCtxt, hir: &Hir, cid: ContractId) {
    let c = &hir.contracts[cid];
    let mut cache = HashMap::new();
    let mut inherited = Vec::new();
    inherited_functions(hir, cid, &mut inherited, &mut cache);
    // Remove signatures defined in the current contract.
    let mut own_sigs: Vec<String> = Vec::new();
    for &item in &c.items {
        match item {
            ItemId::Function(f) if hir.functions[f].kind != FunctionKind::Constructor => own_sigs.push(Proxy::Function(f).sig(hir)),
            ItemId::Variable(v) if hir.variables[v].visibility == Some(Visibility::Public) => own_sigs.push(Proxy::Variable(v).sig(hir)),
            _ => {}
        }
    }
    inherited.retain(|(s, _)| !own_sigs.contains(s));
    // Group by signature, preserving first-seen order.
    let mut groups: Vec<(String, Vec<Proxy>)> = Vec::new();
    for (s, p) in inherited {
        if let Some(g) = groups.iter_mut().find(|(gs, _)| *gs == s) {
            if !g.1.contains(&p) {
                g.1.push(p);
            }
        } else {
            groups.push((s, vec![p]));
        }
    }
    for (_, mut protos) in groups {
        protos.retain(|p| p.is_implemented(hir));
        if protos.len() <= 1 {
            continue;
        }
        let first = protos[0];
        let kind = if first.is_modifier(hir) { "modifier" } else { "function" };
        let mut contracts: Vec<ContractId> = protos.iter().map(|p| p.contract(hir)).collect();
        contracts.sort();
        contracts.dedup();
        let names: Vec<String> = contracts.iter().map(|c| format!("`{}`", hir.contracts[*c].name.name)).collect();
        dcx.emit(
            Diag::new(Level::Error, format!("derived contract must override {kind} `{}`", first.name(hir)))
                .code(6480)
                .span(c.name.span)
                .note(format!("two or more base classes define {kind} with same name and parameter types"))
                .note(format!("defined in: {}", names.join(", "))),
        );
    }
}

// ---- unimplemented ----

fn check_unimplemented(dcx: &DiagCtxt, hir: &Hir, cid: ContractId) {
    let c = &hir.contracts[cid];
    if matches!(c.kind, ContractKind::AbstractContract | ContractKind::Interface) {
        return;
    }
    // Walk linearized bases from most derived; track implemented signatures.
    let mut implemented: Vec<String> = Vec::new();
    let mut unimplemented: Vec<(FunctionId, ContractId)> = Vec::new();
    for &b in &c.linearized_bases {
        for &item in &hir.contracts[b].items {
            match item {
                ItemId::Function(f) => {
                    let func = &hir.functions[f];
                    if func.kind == FunctionKind::Constructor {
                        continue;
                    }
                    let sig = Proxy::Function(f).sig(hir);
                    if func.has_body {
                        if !implemented.contains(&sig) {
                            implemented.push(sig);
                        }
                    } else if !implemented.contains(&sig) && !unimplemented.iter().any(|(uf, _)| Proxy::Function(*uf).sig(hir) == sig) {
                        unimplemented.push((f, b));
                    }
                }
                ItemId::Variable(v) => {
                    let var = &hir.variables[v];
                    if var.visibility == Some(Visibility::Public) {
                        let sig = Proxy::Variable(v).sig(hir);
                        if !implemented.contains(&sig) {
                            implemented.push(sig);
                        }
                    }
                }
                _ => {}
            }
        }
    }
    for (f, b) in unimplemented {
        let func = &hir.functions[f];
        let kind = if func.kind == FunctionKind::Modifier { "modifier" } else { "function" };
        let name = func.name.map(|n| n.name.as_str().to_string()).unwrap_or_default();
        dcx.emit(
            Diag::new(Level::Error, format!("contract `{}` has unimplemented functions", c.name.name))
                .code(3656)
                .span(c.name.span)
                .span_suggestion(c.ast.kind_span, "mark the contract as abstract", "abstract contract")
                .span_note(func.span, format!("unimplemented {kind} `{name}` defined in `{}`", hir.contracts[b].name.name)),
        );
    }
}

#[allow(dead_code)]
fn _unused() {
    let _ = checks::is_reference_type;
}
