uint256 constant MAX = type(uint256).max;
bytes32 constant SALT = keccak256(abi.encodePacked("salt", uint8(1)));

function freeHelper(uint256 a) pure returns (uint256 b) {
    b = a * 2;
}

enum Color { Red, Green, Blue }

struct Point { int256 x; int256 y; }

library Points {
    function add(Point memory a, Point memory b) internal pure returns (Point memory) {
        return Point(a.x + b.x, a.y + b.y);
    }
    function isZero(Point memory a) internal pure returns (bool) {
        return a.x == 0 && a.y == 0;
    }
}

using Points for Point global;

abstract contract Base is IThing {
    uint256 internal _counter;
    event Incremented(uint256 indexed newValue, address by);
    error TooBig(uint256 value, uint256 max);

    function increment() public virtual returns (uint256) {
        if (_counter >= L.LIMIT) revert TooBig(_counter, L.LIMIT);
        unchecked { _counter++; }
        emit Incremented(_counter, msg.sender);
        return _counter;
    }

    function thing() external view virtual override returns (uint256) {
        return _counter;
    }
}

contract Derived is Base {
    using L for uint256;
    using L for *;

    Point public origin;
    Point[] public points;
    mapping(Color => Point) public colored;
    Color public constant DEFAULT = Color.Green;
    address public immutable deployer;
    function(uint256) internal pure returns (uint256) private _hook;
    function(uint256) external view returns (uint256)[] public hooks;
    bytes32 public constant CODE_HASH = keccak256(type(Derived).creationCode);

    constructor(Point memory o) payable {
        origin = o;
        deployer = msg.sender;
        _hook = freeHelper;
    }

