        sel = bytes4(data[:4]);
        rest = data[4:];
        (uint256 a, address b) = abi.decode(data[4:], (uint256, address));
        a; b;
    }

    function many() external payable returns (uint256) {
        bytes memory payload = abi.encodeWithSelector(this.increment.selector);
        bytes memory payload2 = abi.encodeWithSignature("increment()");
        bytes memory payload3 = abi.encodeCall(this.increment, ());
        (bool ok, bytes memory out) = address(this).call{value: msg.value}(payload);
