        v += uint256(uint160(tx.origin)) + tx.gasprice + uint256(bytes32(msg.sig)) + msg.value + uint160(block.coinbase) + uint256(blockhash(block.number - 1));
        address recovered = ecrecover(bytes32(0), 27, bytes32(0), bytes32(0));
        v += addmod(v, 1, 7) + mulmod(v, 2, 7) + uint160(recovered);
