//! AST validation pass (runs after parsing, before lowering).

use crate::ast::*;
use crate::diag::{Diag, DiagCtxt, Level};
use crate::span::Span;

pub fn validate(dcx: &DiagCtxt, ast: &SourceUnit) {
    let mut v = Validator { dcx, contract: None, in_loop: 0, in_modifier: false, in_unchecked: false };
    for item in &ast.items {
        v.visit_item(item);
    }
}

struct Validator<'d> {
    dcx: &'d DiagCtxt,
    contract: Option<ContractKind>,
    in_loop: usize,
    in_modifier: bool,
    in_unchecked: bool,
}

impl<'d> Validator<'d> {
    fn err(&self, span: Span, msg: impl Into<String>) {
        self.dcx.emit(Diag::new(Level::Error, msg).span(span));
    }

    fn visit_item(&mut self, item: &Item) {
        match &item.kind {
            ItemKind::Pragma(p) => self.check_pragma(item.span, p),
            ItemKind::Import(_) => {}
            ItemKind::Using(u) => {
                if u.ty.is_none() && self.contract.is_none() {
                    self.err(item.span, "the type has to be specified explicitly at file level (cannot use `*`)");
                }
                if let Some(ty) = &u.ty {
                    self.visit_type(ty);
                }
            }
            ItemKind::Contract(c) => {
                if c.kind == ContractKind::Library && !c.bases.is_empty() {
                    self.err(c.name.span, "library is not allowed to inherit");
                }
                for b in &c.bases {
                    self.visit_call_args(&b.arguments);
                }
                if let Some(l) = &c.layout {
                    self.visit_expr(l);
                }
                let prev = self.contract;
                self.contract = Some(c.kind);
                for sub in &c.body {
                    self.visit_item(sub);
                }
                self.contract = prev;
            }
            ItemKind::Function(f) => self.visit_function(item.span, f),
            ItemKind::Variable(v) => {
                if self.contract == Some(ContractKind::Library) && v.mutability.map(|m| m.data) != Some(VarMut::Constant) {
                    self.err(item.span, "library cannot have non-constant state variable");
                }
                self.visit_var(v);
            }
            ItemKind::Struct(s) => {
                if s.fields.is_empty() {
                    self.err(item.span, "structs must have at least one field");
                }
                for f in &s.fields {
                    self.visit_var(f);
                }
            }
            ItemKind::Enum(e) => {
                if e.variants.is_empty() {
                    self.err(item.span, "enum must have at least one variant");
                }
            }
            ItemKind::Udvt(u) => self.visit_type(&u.ty),
            ItemKind::Error(e) => {
                for v in &e.parameters.vars {
                    self.visit_var(v);
                }
            }
            ItemKind::Event(e) => {
                for v in &e.parameters.vars {
                    self.visit_var(v);
                }
            }
        }
    }

    fn check_pragma(&self, span: Span, p: &PragmaDirective) {
        let known = match &p.tokens {
            PragmaTokens::Version(..) => true,
            PragmaTokens::Custom(a, b) => {
                let a = a.value();
                match (a.as_str(), b) {
                    ("abicoder", Some(b)) => matches!(b.value().as_str(), "v1" | "v2"),
                    ("experimental", Some(b)) => {
                        matches!(b.value().as_str(), "ABIEncoderV2" | "SMTChecker" | "__test" | "__testOnlyAnalysis")
                    }
                    _ => false,
                }
            }
            PragmaTokens::Verbatim(_) => false,
        };
        if !known {
            self.err(span, "unknown pragma");
        }
    }

    fn visit_function(&mut self, span: Span, f: &ItemFunction) {
        let header = &f.header;
        match self.contract {
            None => {
                if f.kind == FunctionKind::Function {
                    if let Some(vis) = header.visibility {
                        self.dcx.emit(
                            Diag::new(Level::Error, "free functions cannot have visibility")
                                .span(span)
                                .help(format!("remove `{}` from the declaration", vis.data.to_str())),
                        );
                    }
                    if f.body.is_none() {
                        self.err(span, "free functions must be implemented");
                    }
                }
            }
            Some(ckind) => match f.kind {
                FunctionKind::Function => {
                    if header.visibility.is_none() {
                        self.dcx.emit(
                            Diag::new(Level::Error, "no visibility specified").span(span).help("add `public` to the declaration"),
                        );
                    }
                }
                FunctionKind::Receive | FunctionKind::Fallback => {
                    if f.kind == FunctionKind::Receive {
                        if header.state_mutability.map(|s| s.data) != Some(StateMutability::Payable) {
                            self.dcx.emit(
                                Diag::new(Level::Error, "receive ether function must be payable")
                                    .span(span)
                                    .help("add `payable` state mutability"),
                            );
                        }
                        if !header.parameters.vars.is_empty() {
                            self.err(span, "receive ether function cannot take parameters");
                        }
                        if ckind == ContractKind::Library {
                            self.err(span, "libraries cannot have receive ether functions");
                        }
                    }
                    if header.visibility.is_none() {
                        self.dcx.emit(
                            Diag::new(Level::Error, "no visibility specified").span(span).help("add `external` to the declaration"),
                        );
                    }
                }
                _ => {}
            },
        }
        if f.body.is_none() && !header.modifiers.is_empty() && f.kind != FunctionKind::Constructor {
            self.err(span, "functions without implementation cannot have modifiers");
        }
        for v in &header.parameters.vars {
            self.visit_var(v);
        }
        if let Some(r) = &header.returns {
            for v in &r.vars {
                self.visit_var(v);
            }
        }
        for m in &header.modifiers {
            self.visit_call_args(&m.arguments);
        }
        if let Some(body) = &f.body {
            if f.kind == FunctionKind::Modifier && !block_has_placeholder(body) {
                let name_span = header.name.map(|n| n.span).unwrap_or(span);
                self.err(name_span, "modifier must have a `_;` placeholder statement");
            }
            let prev_mod = self.in_modifier;
            self.in_modifier = f.kind == FunctionKind::Modifier;
            let prev_loop = self.in_loop;
            self.in_loop = 0;
            self.visit_block(body);
            self.in_loop = prev_loop;
            self.in_modifier = prev_mod;
        }
    }

    fn visit_var(&mut self, v: &VariableDefinition) {
        self.visit_type(&v.ty);
        if let Some(init) = &v.initializer {
            self.visit_expr(init);
        }
    }

    fn visit_type(&mut self, ty: &Type) {
        match &ty.kind {
            TypeKind::Elementary(_) | TypeKind::Custom(_) => {}
            TypeKind::Array(inner, size) => {
                self.visit_type(inner);
                if let Some(s) = size {
                    self.visit_expr(s);
                }
            }
            TypeKind::Function(f) => {
                for v in &f.parameters.vars {
                    self.visit_type(&v.ty);
                }
                if let Some(r) = &f.returns {
                    for v in &r.vars {
                        if let Some(name) = v.name {
                            self.dcx.emit(
                                Diag::new(Level::Error, "return parameters in function types may not be named")
                                    .span(v.span)
                                    .span_suggestion(name.span, format!("remove `{}`", name.name), ""),
                            );
                        }
                        self.visit_type(&v.ty);
                    }
                }
            }
            TypeKind::Mapping(m) => {
                self.visit_type(&m.key);
                self.visit_type(&m.value);
            }
        }
    }

    fn visit_block(&mut self, b: &Block) {
        for s in &b.stmts {
            self.visit_stmt(s);
        }
    }

    fn visit_stmt_no_decl(&mut self, s: &Stmt) {
        if matches!(s.kind, StmtKind::DeclSingle(_) | StmtKind::DeclMulti(..)) {
            self.dcx.emit(
                Diag::new(Level::Error, "variable declarations can only be used inside blocks")
                    .span(s.span)
                    .help("wrap the statement in a block (`{ ... }`)"),
            );
        }
        self.visit_stmt(s);
    }

    fn visit_stmt(&mut self, s: &Stmt) {
        match &s.kind {
            StmtKind::Assembly(a) => {
                for flag in &a.flags {
                    if flag.value != "memory-safe" {
                        self.dcx.emit(Diag::new(Level::Warning, "unknown inline assembly flag").span(flag.span));
                    }
                }
            }
            StmtKind::DeclSingle(v) => self.visit_var(v),
            StmtKind::DeclMulti(vars, e) => {
                for v in vars.iter().flatten() {
                    self.visit_var(v);
                }
                self.visit_expr(e);
            }
            StmtKind::Block(b) => self.visit_block(b),
            StmtKind::UncheckedBlock(b) => {
                let prev = self.in_unchecked;
                self.in_unchecked = true;
                self.visit_block(b);
                self.in_unchecked = prev;
            }
            StmtKind::Break => {
                if self.in_loop == 0 {
                    self.err(s.span, "`break` outside of a loop");
                }
            }
            StmtKind::Continue => {
                if self.in_loop == 0 {
                    self.err(s.span, "`continue` outside of a loop");
                }
