                self.visit_stmt_no_decl(body);
                self.in_loop -= 1;
                self.visit_expr(cond);
            }
            StmtKind::Emit(_, args) | StmtKind::Revert(_, args) => self.visit_call_args(args),
            StmtKind::Expr(e) => self.visit_expr(e),
            StmtKind::For { init, cond, next, body } => {
                if let Some(i) = init {
                    self.visit_stmt(i);
                }
                if let Some(c) = cond {
                    self.visit_expr(c);
                }
                if let Some(n) = next {
                    self.visit_expr(n);
                }
                self.in_loop += 1;
                self.visit_stmt_no_decl(body);
                self.in_loop -= 1;
            }
            StmtKind::If(c, t, e) => {
                self.visit_expr(c);
                self.visit_stmt_no_decl(t);
                if let Some(e) = e {
                    self.visit_stmt_no_decl(e);
                }
            }
            StmtKind::Return(e) => {
                if let Some(e) = e {
                    self.visit_expr(e);
                }
            }
            StmtKind::Try(t) => {
                self.visit_expr(&t.expr);
                if let Some(r) = &t.returns {
                    for v in &r.vars {
                        self.visit_var(v);
                    }
                }
                self.visit_block(&t.block);
                for c in &t.catch {
                    for v in &c.args.vars {
                        self.visit_var(v);
                    }
                    self.visit_block(&c.block);
                }
            }
            StmtKind::While(c, body) => {
                self.visit_expr(c);
                self.in_loop += 1;
                self.visit_stmt_no_decl(body);
                self.in_loop -= 1;
            }
            StmtKind::Placeholder => {
                if !self.in_modifier {
                    self.err(s.span, "placeholder statements can only be used in modifiers");
                }
            }
        }
    }

    fn visit_call_args(&mut self, args: &CallArgs) {
        for e in args.exprs() {
            self.visit_expr(e);
        }
    }

    fn visit_expr(&mut self, e: &Expr) {
        match &e.kind {
            ExprKind::Array(v) => {
                for x in v {
                    self.visit_expr(x);
                }
            }
            ExprKind::Assign(a, _, b) | ExprKind::Binary(a, _, b) => {
                self.visit_expr(a);
                self.visit_expr(b);
            }
            ExprKind::Call(c, args) => {
                self.visit_expr(c);
                self.visit_call_args(args);
            }
            ExprKind::CallOptions(c, args) => {
                self.visit_expr(c);
                for a in args {
                    self.visit_expr(&a.value);
                }
            }
            ExprKind::Delete(x) | ExprKind::Unary(_, x) => self.visit_expr(x),
            ExprKind::Ident(_) => {}
            ExprKind::Index(a, b) => {
                self.visit_expr(a);
                if let Some(b) = b {
                    self.visit_expr(b);
                }
            }
            ExprKind::Slice(a, b, c) => {
                self.visit_expr(a);
                if let Some(b) = b {
                    self.visit_expr(b);
                }
                if let Some(c) = c {
                    self.visit_expr(c);
                }
            }
            ExprKind::Lit(lit, sub) => {
                if let Some(sub) = sub {
                    let span = lit.span.to(sub.span);
                    if matches!(lit.kind, LitKind::Number(_) | LitKind::Rational(_)) {
                        if lit.symbol.as_str().starts_with("0x") {
                            self.dcx.emit(
                                Diag::new(Level::Error, "hexadecimal numbers cannot be used with unit denominations")
                                    .span(span)
                                    .help("you can use an expression of the form \"0x1234 * 1 days\" instead"),
                            );
                        } else if sub.data == SubDenomination::Years {
                            self.err(span, "using \"years\" as a unit denomination is deprecated");
                        }
                    }
                }
            }
            ExprKind::Member(a, _) => self.visit_expr(a),
            ExprKind::New(ty) | ExprKind::TypeCall(ty) | ExprKind::Type(ty) => self.visit_type(ty),
            ExprKind::Payable(args) => self.visit_call_args(args),
            ExprKind::Ternary(a, b, c) => {
                self.visit_expr(a);
                self.visit_expr(b);
                self.visit_expr(c);
            }
            ExprKind::Tuple(v) => {
                for x in v.iter().flatten() {
                    self.visit_expr(x);
                }
            }
        }
    }
}

fn block_has_placeholder(block: &Block) -> bool {
    block.stmts.iter().any(stmt_has_placeholder)
}

fn stmt_has_placeholder(stmt: &Stmt) -> bool {
    match &stmt.kind {
        StmtKind::Placeholder => true,
        StmtKind::Block(b) | StmtKind::UncheckedBlock(b) => block_has_placeholder(b),
        StmtKind::If(_, t, e) => stmt_has_placeholder(t) || e.as_ref().is_some_and(|e| stmt_has_placeholder(e)),
        StmtKind::While(_, b) | StmtKind::DoWhile(b, _) => stmt_has_placeholder(b),
        StmtKind::For { body, .. } => stmt_has_placeholder(body),
        StmtKind::Try(t) => block_has_placeholder(&t.block) || t.catch.iter().any(|c| block_has_placeholder(&c.block)),
        _ => false,
    }
}
