    /// contract for constructors).
    fn resolve_modifier_path(&self, path: &ast::Path, contract: Option<ContractId>, source: SourceId, is_ctor: bool) -> Option<Res> {
        let first = path.segments[0];
        let Some(resl) = self.lookup(first.name, &[], contract, source) else {
            self.emit_unresolved(first);
            return None;
        };
        let mut res = resl[0];
        for (i, seg) in path.segments.iter().enumerate().skip(1) {
            let prev = path.segments[i - 1];
            match res {
                Res::Item(ItemId::Contract(c)) => {
                    let Some(r) = self.contract_scopes[c].get(seg.name) else {
                        self.emit_unresolved(*seg);
                        return None;
                    };
                    res = r[0];
                }
                Res::Namespace(s) => {
                    let Some(r) = self.source_exports[s].get(seg.name) else {
                        self.emit_unresolved(*seg);
                        return None;
                    };
                    res = r[0];
                }
                Res::Item(id) => {
                    self.dcx.emit(
                        Diag::new(
                            Level::Error,
                            format!("`{}` is a {}, which cannot be indexed in type paths", prev.name, id.description()),
                        )
                        .span(prev.span),
                    );
                    return None;
                }
                _ => break,
            }
        }
        let expected = if is_ctor { "expected base class or modifier" } else { "expected modifier" };
        let found = match res {
            Res::Item(ItemId::Function(f)) if self.hir.functions[f].kind == FunctionKind::Modifier => return Some(res),
            Res::Item(ItemId::Contract(c)) => {
                if is_ctor && contract.is_some_and(|cur| cur != c && self.hir.contracts[cur].linearized_bases.contains(&c)) {
                    return Some(res);
                }
                "contract"
            }
            Res::Item(id) => id.description(),
            Res::Builtin(_) | Res::This(_) | Res::Super(_) => "builtin",
            Res::Namespace(_) => "namespace",
            Res::Err => return None,
        };
        self.dcx.emit(Diag::new(Level::Error, format!("{expected}, found {found}")).span(path.span()));
        None
    }

