/// "modifier-style base constructor call without arguments"
fn check_ctor_modifiers(cx: &mut LowerCtx<'_, '_>) {
    for fid in 0..cx.hir.functions.len() {
        let f = &cx.hir.functions[fid];
        if f.kind != FunctionKind::Constructor {
            continue;
        }
        let Some(ast) = f.ast else { continue };
        let mut errs = Vec::new();
        for (i, m) in ast.header.modifiers.iter().enumerate() {
            if let Some(Res::Item(ItemId::Contract(_))) = f.modifiers.get(i) {
                if m.arguments.span.len() == 0 {
                    errs.push(m.name.span());
                }
            }
        }
        for span in errs {
            cx.dcx.emit(Diag::new(Level::Error, "modifier-style base constructor call without arguments").span(span));
        }
    }
}''')
