            self.0.pop();
        }
    }
    fn mul_small(&mut self, m: u32) {
        let mut carry: u64 = 0;
        for d in self.0.iter_mut() {
            let v = (*d as u64) * (m as u64) + carry;
            *d = v as u32;
            carry = v >> 32;
        }
        if carry > 0 {
            self.0.push(carry as u32);
        }
    }
    fn add_small(&mut self, a: u32) {
        let mut carry = a as u64;
        for d in self.0.iter_mut() {
            if carry == 0 {
                break;
            }
            let v = (*d as u64) + carry;
            *d = v as u32;
            carry = v >> 32;
        }
        if carry > 0 {
            self.0.push(carry as u32);
        }
    }
    /// Divides in place by `d`, returning the remainder.
    fn div_small(&mut self, d: u32) -> u32 {
        let mut rem: u64 = 0;
        for x in self.0.iter_mut().rev() {
            let v = (rem << 32) | (*x as u64);
            *x = (v / d as u64) as u32;
            rem = v % d as u64;
        }
        self.trim();
        rem as u32
    }
    fn bits(&self) -> usize {
        match self.0.last() {
            None => 0,
            Some(&top) => (self.0.len() - 1) * 32 + (32 - top.leading_zeros() as usize),
        }
    }
    fn from_dec_str(s: &str) -> Self {
        let mut r = BigUint::zero();
        for c in s.bytes() {
            r.mul_small(10);
            r.add_small((c - b'0') as u32);
        }
        r
    }
    fn from_hex_str(s: &str) -> Self {
        let mut r = BigUint::zero();
        for c in s.chars() {
            r.mul_small(16);
            r.add_small(c.to_digit(16).unwrap_or(0));
        }
        r
    }
    fn to_dec_string(&self) -> String {
        if self.is_zero() {
            return "0".to_string();
        }
        let mut v = self.clone();
        let mut digits = Vec::new();
