fn check_underscores(body: &str) -> Option<&'static str> {
    let bytes = body.as_bytes();
    if bytes.last() == Some(&b'_') {
        return Some("remove trailing underscores");
    }
    let mut prev = false;
    for &b in bytes {
        if b == b'_' {
            if prev {
                return Some("only 1 consecutive underscore `_` is allowed between digits");
            }
            prev = true;
        } else {
            prev = false;
        }
    }
    None
