/// Parses an integer literal token text.
pub fn parse_integer(text: &str) -> NumResult {
    if text.starts_with("0b") || text.starts_with("0o") {
        return NumResult::Silent;
    }
    if let Some(hex) = text.strip_prefix("0x") {
        if hex.is_empty() {
            return NumResult::Silent;
        }
        if let Some(help) = check_underscores(hex) {
            return NumResult::Err("invalid use of underscores in number literal".into(), Some(help.into()));
        }
        let clean: String = hex.chars().filter(|c| *c != '_').collect();
        if clean.is_empty() {
            return NumResult::Silent;
        }
        let v = BigUint::from_hex_str(&clean);
        if v.bits() > 256 {
            return NumResult::Err("integer part too large".into(), None);
        }
        return NumResult::Ok(LitKind::Number(v.to_dec_string()));
    }
    if let Some(help) = check_underscores(text) {
        return NumResult::Err("invalid use of underscores in number literal".into(), Some(help.into()));
    }
    let clean: String = text.chars().filter(|c| *c != '_').collect();
    if clean.len() > 1 && clean.starts_with('0') {
        return NumResult::Err("leading zeros are not allowed in integers".into(), None);
    }
    let v = BigUint::from_dec_str(&clean);
    if v.bits() > 256 {
        return NumResult::Err("integer part too large".into(), None);
    }
    NumResult::Ok(LitKind::Number(v.to_dec_string()))
}

/// Parses a rational literal token text.
pub fn parse_rational(text: &str) -> NumResult {
    if text.starts_with("0x") || text.starts_with("0b") || text.starts_with("0o") {
        return NumResult::Silent;
    }
    let (mantissa, exp_str) = match text.find(['e', 'E']) {
        Some(i) => (&text[..i], Some(&text[i + 1..])),
        None => (text, None),
    };
    let (int_part, frac_part) = match mantissa.find('.') {
        Some(i) => (&mantissa[..i], Some(&mantissa[i + 1..])),
        None => (mantissa, None),
    };
    // Exponent validity.
    let mut exp_neg = false;
    let mut exp_digits = "";
    if let Some(e) = exp_str {
        let e2 = if let Some(r) = e.strip_prefix('-') {
            exp_neg = true;
            r
        } else if let Some(r) = e.strip_prefix('+') {
            return NumResult::Err("`+` is not allowed in the exponent".into(), None);
        } else {
            e
        };
        if e2.chars().filter(|c| *c != '_').count() == 0 {
            return NumResult::Silent;
        }
        exp_digits = e2;
    }
    // Underscore checks.
    if let Some(frac) = frac_part {
        if int_part.ends_with('_') || frac.starts_with('_') {
            return NumResult::Err(
                "invalid use of underscores in number literal".into(),
                Some("remove underscores in front of the fraction part".into()),
            );
        }
    }
    if exp_str.is_some() && (mantissa.ends_with('_') || exp_digits.starts_with('_')) {
        return NumResult::Err(
            "invalid use of underscores in number literal".into(),
            Some("remove underscores in front of the exponent".into()),
        );
    }
    if let Some(help) = check_underscores(text) {
        return NumResult::Err("invalid use of underscores in number literal".into(), Some(help.into()));
    }
    if let Some(frac) = frac_part {
        if frac.chars().filter(|c| c.is_ascii_digit()).count() == 0 {
            return NumResult::Err("empty rational".into(), None);
        }
    }
    let int_clean: String = int_part.chars().filter(|c| *c != '_').collect();
    if int_clean.len() > 1 && int_clean.starts_with('0') {
        return NumResult::Err("leading zeros are not allowed in integers".into(), None);
    }
    let frac_clean: String = frac_part.unwrap_or("").chars().filter(|c| *c != '_').collect();
    let exp_clean: String = exp_digits.chars().filter(|c| *c != '_').collect();
    // Exponent magnitude.
    let exp: i64 = if exp_clean.is_empty() {
        0
    } else {
        let trimmed = exp_clean.trim_start_matches('0');
        if trimmed.len() > 6 {
            return NumResult::Err("exponent too large".into(), None);
        }
        let v: i64 = trimmed.parse().unwrap_or(0);
        if v >= 1234 {
            return NumResult::Err("exponent too large".into(), None);
        }
        if exp_neg { -v } else { v }
    };
    // value = M * 10^(exp - frac_len)
    let digits = format!("{int_clean}{frac_clean}");
    let mut numerator = BigUint::from_dec_str(digits.trim_start_matches('0'));
    let k = exp - frac_clean.len() as i64;
    let mut denominator = BigUint::from_u32(1);
    if numerator.is_zero() {
        return NumResult::Ok(LitKind::Number("0".into()));
    }
    if k >= 0 {
        for _ in 0..k {
            numerator.mul_small(10);
        }
    } else {
        denominator = BigUint::pow10((-k) as u32);
        // Reduce by 2 and 5.
        for &p in &[2u32, 5u32] {
            while numerator.divisible_by(p) && denominator.divisible_by(p) {
                numerator.div_small(p);
                denominator.div_small(p);
            }
        }
    }
    if numerator.bits() > 256 || denominator.bits() > 256 {
        return NumResult::Err("rational part too large".into(), None);
    }
    if denominator == BigUint::from_u32(1) {
        NumResult::Ok(LitKind::Number(numerator.to_dec_string()))
    } else {
        NumResult::Ok(LitKind::Rational(text.chars().filter(|c| *c != '_').collect()))
    }
}

/// Returns the bytes represented by a string literal token (including prefix and quotes).
pub fn str_lit_bytes(kind: TLitKind, raw: &str) -> Vec<u8> {
    let body = match kind {
        TLitKind::HexStr => &raw[3..],
        TLitKind::UnicodeStr => &raw[7..],
        _ => raw,
    };
    let inner = &body[1..body.len().saturating_sub(1)];
    match kind {
        TLitKind::HexStr => {
            let hex: String = inner.chars().filter(|c| c.is_ascii_hexdigit()).collect();
            (0..hex.len() / 2).map(|i| u8::from_str_radix(&hex[i * 2..i * 2 + 2], 16).unwrap_or(0)).collect()
        }
        _ => unescape_str(inner),
    }
}

/// Unescapes a string literal body.
pub fn unescape_str(s: &str) -> Vec<u8> {
    let mut out = Vec::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c != '\\' {
            let mut buf = [0u8; 4];
            out.extend_from_slice(c.encode_utf8(&mut buf).as_bytes());
            continue;
        }
        let Some(e) = chars.next() else { break };
        match e {
            'n' => out.push(b'\n'),
            'r' => out.push(b'\r'),
            't' => out.push(b'\t'),
            '\\' => out.push(b'\\'),
            '\'' => out.push(b'\''),
            '"' => out.push(b'"'),
            '\n' => {}
            'x' => {
                let mut v = 0u8;
                for _ in 0..2 {
                    if let Some(d) = chars.peek().and_then(|c| c.to_digit(16)) {
                        v = v * 16 + d as u8;
                        chars.next();
                    }
                }
                out.push(v);
            }
            'u' => {
                let mut v = 0u32;
                for _ in 0..4 {
                    if let Some(d) = chars.peek().and_then(|c| c.to_digit(16)) {
                        v = v * 16 + d;
                        chars.next();
                    }
                }
                if let Some(ch) = char::from_u32(v) {
                    let mut buf = [0u8; 4];
                    out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                }
            }
            other => {
                let mut buf = [0u8; 4];
                out.extend_from_slice(other.encode_utf8(&mut buf).as_bytes());
            }
        }
    }
    out
}
